Object.assign(window.BUILTIN_COURSES = window.BUILTIN_COURSES || {}, {"oge-ru":{"course":"Подготовка к ОГЭ. Русский язык","tag":"ОГЭ 2027","goal":"ОГЭ","grade":9,"grades":null,"ver":2,"author":true,"blocks":{"s0":{"name":"2 · Грамматическая основа","tasks":"","color":"#7b4cf5"},"s1":{"name":"3 · Обособленные члены","tasks":"","color":"#ee5fa8"},"s2":{"name":"3 · Вводные слова и обращения","tasks":"","color":"#2f86ea"},"s3":{"name":"2–3 · Сложное предложение","tasks":"","color":"#16a8a0"},"s4":{"name":"4 · Словосочетание","tasks":"","color":"#ff8a3d"},"s5":{"name":"5 · Орфография","tasks":"","color":"#3fae4f"},"s6":{"name":"6–8 · Работа с текстом","tasks":"","color":"#e5484d"},"s7":{"name":"1 · Сжатое изложение","tasks":"","color":"#e3a500"},"s8":{"name":"9 · Сочинение","tasks":"","color":"#8b5cf6"},"s9":{"name":"Итоговое собеседование","tasks":"","color":"#0ea5e9"}},"lessons":[{"id":"oge-ru-01","title":"Подлежащее и способы его выражения","block":"s0","oge":"Задание 2 · Грамматическая основа","learn":["находить подлежащее, выраженное разными частями речи","отличать подлежащее от дополнения"],"theory":[{"h":"Что такое подлежащее","t":"Подлежащее называет того, о ком или о чём говорится в предложении, и отвечает на вопрос именительного падежа «кто? что?».","list":["Подлежащее и сказуемое вместе – грамматическая основа.","Подлежащее подчёркиваем одной чертой.","Чаще всего подлежащее – существительное или местоимение в именительном падеже."],"ex":["[[s:Ветер]] [[p:гнал]] по небу облака.","[[s:Мы]] [[p:вернулись]] поздно."],"mini":[{"q":"Подлежащее отвечает на вопросы…","a":"кто? что?|кто что|кто, что"},{"q":"В каком падеже обычно стоит подлежащее?","a":"в именительном|именительный|им. п."}]},{"h":"Подлежащее – не только существительное","t":"На экзамене чаще всего ошибаются, когда подлежащее выражено другой частью речи или сочетанием слов.","ex":["Инфинитив: [[s:Учиться]] – [[p:наш долг]].","Числительное: [[s:Семеро]] [[p:одного не ждут]].","Прилагательное или причастие в значении существительного: [[s:Отдыхающие]] [[p:вернулись]] с пляжа.","Сочетание слов: [[s:Брат с сестрой]] [[p:ушли]] в кино. [[s:Несколько учеников]] [[p:остались]] после урока."],"table":[["Чем выражено","Пример"],["существительное","[[s:Снег]] выпал."],["местоимение","[[s:Кто-то]] постучал."],["инфинитив","[[s:Петь]] – его призвание."],["числительное","[[s:Трое]] опоздали."],["слово в значении существительного","[[s:Дежурный]] открыл окно."],["неделимое сочетание","[[s:Мама с дочкой]] гуляли."]],"mini":[{"q":"Найдите подлежащее: «Курить вредно».","a":"курить"},{"q":"Найдите подлежащее: «Пятеро вышли вперёд».","a":"пятеро"}]},{"h":"Подлежащее или дополнение?","t":"Существительное в винительном падеже может совпадать по форме с именительным. Проверяем по смыслу: кто совершает действие.","list":["«Платье задело стул»: что задело? – платье (подлежащее); задело что? – стул (дополнение).","Если по смыслу определить трудно, подлежащее обычно стоит первым: «Мать любит дочь»."],"ex":["[[s:Солнце]] [[p:осветило]] [[o:поляну]].","[[o:Поляну]] [[p:осветило]] [[s:солнце]]."],"mini":[{"q":"Что подлежащее в предложении «Поляну осветило солнце»?","a":"солнце"}]}],"practice":[{"t":"Подчеркните подлежащее одной чертой (инструмент «Подлежащее»).","key":"1) мечтать; 2) многие из нас; 3) двое рыбаков; 4) парус; 5) «нет» (слово в значении существительного)","items":["Мечтать не вредно.","Многие из нас любят осень.","Двое рыбаков сидели у костра.","Вдали показался парус.","Смелое «нет» прозвучало в тишине."]},{"t":"Подчеркните подлежащее; над ним подпишите, чем оно выражено (инструмент «Подпись»: сущ., мест., инф., числ., прил.).","key":"1) учёные (прил. в значении сущ.); 2) каждый (мест.); 3) отдыхать (инф.); 4) семь (числ.); 5) новенькая (прил. в значении сущ.)","items":["Учёные спорили до вечера.","Каждый получил задание.","Отдыхать после работы приятно.","Семь не делится на два.","Новенькая села у окна."]},{"t":"Подчеркните грамматическую основу. Маркером отметьте подлежащее, которое стоит после сказуемого.","key":"1) шумел дождь – после; 2) дождь шумел – до; 3) послышались голоса – после; 4) лежала книга – после","items":["За окном шумел дождь.","Дождь шумел за окном.","В лесу послышались голоса.","На столе лежала раскрытая книга."]},{"t":"Определите, что является подлежащим. Запишите ответ в поле.\n\nКолесо задело камень. Камень задело колесо. Дочь встретила мать.","key":"колесо; камень (по смыслу определить трудно – подлежащее стоит первым); дочь"},{"t":"Задание в формате ОГЭ (2). Выпишите грамматическую основу предложения.\n\nПосле долгих споров несколько человек решили остаться в лагере до утра.","key":"несколько человек решили остаться"}],"test":[{"q":"В каком предложении подлежащее выражено инфинитивом?","o":["Он любит читать.","Читать – значит думать.","Мы сели читать.","Читая, он улыбался."],"a":1,"e":"Инфинитив «читать» называет то, о чём говорится, и стоит в начале основы.","tag":"Подлежащее и способы его выражения"},{"q":"Найдите подлежащее: «Трое из нас вызвались помочь».","o":["трое","трое из нас","нас","вызвались"],"a":1,"e":"Числительное с зависимыми словами «из нас» – неделимое сочетание.","tag":"Подлежащее и способы его выражения"},{"q":"В каком предложении подлежащее – сочетание слов?","o":["Отец с сыном починили лодку.","Отец починил лодку с сыном.","Отец чинил лодку.","Лодку чинили вечером."],"a":0,"e":"Оба совершают действие, сказуемое во множественном числе.","tag":"Подлежащее и способы его выражения"},{"q":"Что является подлежащим: «Пароход задел баржу»?","o":["пароход","баржу","задел","нет подлежащего"],"a":0,"e":"Задел что? – баржу (дополнение). Что задело? – пароход.","tag":"Подлежащее и способы его выражения"},{"q":"Подлежащее в предложении «Провожающие махали руками» выражено…","o":["существительным","причастием в значении существительного","глаголом","местоимением"],"a":1,"e":"Провожающие – те, кто провожает.","tag":"Подлежащее и способы его выражения"},{"q":"Выпишите подлежащее: «Невдалеке темнел старый бор».","a":"бор","e":"Подлежащее стоит после сказуемого: что темнел? – бор.","tag":"Подлежащее и способы его выражения"}],"hwtest":[{"q":"Найдите подлежащее: «Каждый из нас знал ответ».","o":["каждый","каждый из нас","нас","ответ"],"a":1,"e":"Местоимение с зависимыми словами.","tag":"Подлежащее и способы его выражения"},{"q":"Где подлежащее выражено числительным?","o":["Пять делится на пять.","Пять книг лежали на столе.","Он купил пять книг.","Было пять часов."],"a":0,"e":"«Пять» само называет предмет речи.","tag":"Подлежащее и способы его выражения"},{"q":"Выпишите подлежащее: «Учиться никогда не поздно».","a":"учиться","e":"Инфинитив.","tag":"Подлежащее и способы его выражения"},{"q":"Выпишите подлежащее: «Вдали показалась деревня».","a":"деревня","e":"Подлежащее после сказуемого.","tag":"Подлежащее и способы его выражения"}],"hw":"Выписать из любого художественного текста 6 предложений с подлежащим, выраженным разными частями речи (сущ., мест., инф., числ., прил., сочетание слов), подчеркнуть основу. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Подлежащее, выраженное не существительным, и подлежащее после сказуемого.","tips":["Ищем основу от сказуемого.","Сочетания «двое друзей», «многие из нас», «брат с сестрой» – единое подлежащее.","Проверяем падеж: подлежащее не может стоять в винительном."]},"memo":{"h":"Как не ошибиться","t":"Ищем подлежащее после сказуемого: спрашиваем от глагола «кто? что делает?». Так подлежащее, стоящее в конце предложения, не потеряется.","ex":["Над рекой поднялся (что?) туман.","В углу стояли (что?) старинные часы."]},"date":"2026-09-01"},{"id":"oge-ru-02","title":"Простое глагольное сказуемое","block":"s0","oge":"Задание 2 · Грамматическая основа","learn":["находить простое глагольное сказуемое","не путать формы будущего времени и повелительного наклонения с составным сказуемым"],"theory":[{"h":"Что такое простое глагольное сказуемое","t":"Сказуемое называет действие или признак подлежащего и отвечает на вопросы «что делает? что сделал? каков? кто он?». Простое глагольное сказуемое выражено одним глаголом в любом наклонении.","list":["Изъявительное наклонение: читает, прочитал, будет читать.","Условное: прочитал бы.","Повелительное: пусть прочитает, давай почитаем.","Сказуемое подчёркиваем двумя чертами."],"ex":["[[s:Птицы]] [[p:улетели]] на юг.","[[s:Я]] [[p:буду писать]] завтра. (будущее сложное – простое сказуемое)","[[s:Ты]] [[p:пошёл бы]] с нами?"],"mini":[{"q":"Сколько слов в сказуемом «будем решать»? Какое это сказуемое?","a":"простое глагольное|простое"},{"q":"Сказуемое «пусть поёт» – простое или составное?","a":"простое"}]},{"h":"Фразеологизм в роли сказуемого","t":"Устойчивое сочетание с глаголом, которое можно заменить одним глаголом, – тоже простое глагольное сказуемое.","list":["бить баклуши = бездельничать","взять себя в руки = успокоиться","отдавать себе отчёт = понимать"],"ex":["[[s:Он]] весь день [[p:бил баклуши]].","[[s:Девочка]] [[p:взяла себя в руки]]."],"mini":[{"q":"«Он сломя голову бросился бежать». Можно ли заменить «сломя голову» одним глаголом?","a":"нет"}]}],"practice":[{"t":"Подчеркните грамматическую основу (подлежащее – одной чертой, сказуемое – двумя).","key":"1) мы будем готовить; 2) ты помог бы; 3) пусть ветер стихнет; 4) брат валял дурака; 5) давайте споём","items":["Мы будем готовить праздник всем классом.","Ты помог бы мне с задачей?","Пусть ветер стихнет к утру.","Весь вечер брат валял дурака.","Давайте споём хором!"]},{"t":"Над сказуемым подпишите наклонение: изъяв., усл., повел.","key":"1) изъяв.; 2) усл.; 3) повел.; 4) изъяв.; 5) повел.","items":["Снег выпал ночью.","Я пришёл бы раньше.","Пускай он расскажет сам.","Вечером они будут гулять.","Садитесь поближе к огню."]},{"t":"Выпишите сказуемые и укажите тип (все ли они простые глагольные?).\n\nСтарик долго смотрел на море. Потом он стал собирать сети. Солнце садилось.","key":"смотрел – простое глагольное; стал собирать – составное глагольное; садилось – простое глагольное"},{"t":"Задание в формате ОГЭ (2). Выпишите грамматическую основу.\n\nК вечеру ребята будут ждать нас на пристани.","key":"ребята будут ждать"}],"test":[{"q":"Какое сказуемое в предложении «Завтра мы будем рисовать»?","o":["простое глагольное","составное глагольное","составное именное","его нет"],"a":0,"e":"Будущее сложное время – одна форма глагола.","tag":"Простое глагольное сказуемое"},{"q":"Где сказуемое выражено фразеологизмом?","o":["Он держал язык за зубами.","Он держал книгу в руках.","Он долго держал паузу перед ответом.","Он держал собаку на поводке."],"a":0,"e":"Держать язык за зубами = молчать.","tag":"Простое глагольное сказуемое"},{"q":"Найдите простое глагольное сказуемое в условном наклонении.","o":["читал бы","буду читать","начал читать","хочу читать"],"a":0,"e":"Частица «бы» входит в форму глагола.","tag":"Простое глагольное сказуемое"},{"q":"Какое сказуемое простое глагольное?","o":["стал читать","пусть читает","был весёлым","хочет уйти"],"a":1,"e":"Частица «пусть» образует повелительное наклонение.","tag":"Простое глагольное сказуемое"},{"q":"Выпишите сказуемое: «Пусть они немного отдохнут».","a":"пусть отдохнут","e":"Повелительное наклонение с частицей «пусть».","tag":"Простое глагольное сказуемое"},{"q":"Сколько простых глагольных сказуемых: «Он вошёл, снял шапку и будет ждать»?","o":["одно","два","три","ни одного"],"a":2,"e":"Вошёл, снял, будет ждать – все простые.","tag":"Простое глагольное сказуемое"}],"hwtest":[{"q":"Какое сказуемое: «Мы будем петь»?","o":["простое глагольное","составное глагольное"],"a":0,"e":"Будущее сложное.","tag":"Простое глагольное сказуемое"},{"q":"Где сказуемое – фразеологизм?","o":["Он клевал носом.","Птица клевала зерно."],"a":0,"e":"Клевать носом = дремать.","tag":"Простое глагольное сказуемое"},{"q":"Выпишите сказуемое: «Давай поиграем в шахматы».","a":"давай поиграем","e":"Повелительное наклонение.","tag":"Простое глагольное сказуемое"}],"hw":"Составить 5 предложений с простым глагольным сказуемым в разных формах: будущее сложное, условное наклонение, повелительное с «пусть», фразеологизм. Подчеркнуть основу. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Простое глагольное сказуемое: все формы глагола и фразеологизмы.","tips":["Будущее сложное (буду читать) – простое сказуемое.","«Пусть», «давай», «бы» входят в сказуемое.","Фразеологизм проверяем заменой одним глаголом."]},"memo":{"h":"Главная ловушка","t":"«Буду читать» – это одна форма глагола (будущее время), а не два слова со своими значениями. Поэтому сказуемое простое.","ex":["стану читать – составное (начало действия)","буду читать – простое"]},"date":"2026-09-08"},{"id":"oge-ru-03","title":"Составное глагольное сказуемое","block":"s0","oge":"Задание 2 · Грамматическая основа","learn":["находить составное глагольное сказуемое","отличать его от простого с инфинитивом-обстоятельством цели"],"theory":[{"h":"Строение","t":"Составное глагольное сказуемое = вспомогательная часть + инфинитив. Вспомогательная часть выражает начало, продолжение, конец действия, желание, возможность, необходимость.","list":["Фазовые глаголы: начал, стал, продолжил, перестал, кончил + инфинитив.","Модальные глаголы: хочу, могу, умею, собираюсь, стараюсь + инфинитив.","Краткие прилагательные: должен, рад, готов, намерен + инфинитив.","Слова надо, нужно, можно, нельзя + инфинитив – тоже составное (в односоставных предложениях)."],"ex":["[[s:Дети]] [[p:начали играть]].","[[s:Я]] [[p:рад видеть]] вас.","[[s:Мы]] [[p:должны успеть]] к поезду."],"mini":[{"q":"Из каких частей состоит составное глагольное сказуемое?","a":"вспомогательная часть и инфинитив|вспомогательный глагол и инфинитив|глагол и инфинитив"},{"q":"Сказуемое «перестал шуметь» – какое?","a":"составное глагольное"}]},{"h":"Ловушка: инфинитив цели","t":"Если инфинитив обозначает цель (зачем?) действия другого глагола, это обстоятельство цели, а сказуемое простое.","list":["Проверка: можно ли вставить «чтобы»? Пришёл (чтобы) помочь – обстоятельство.","Хотел помочь – «чтобы» не вставить, это составное сказуемое.","Инфинитив, называющий действие другого лица, – дополнение: Мама попросила [[o:купить]] хлеб."],"ex":["[[s:Он]] [[p:пришёл]] [[a:помочь]]. – простое","[[s:Он]] [[p:хотел помочь]]. – составное"],"mini":[{"q":"«Ребята сели обедать». Сказуемое простое или составное?","a":"простое"},{"q":"«Ребята хотели обедать». Сказуемое?","a":"составное глагольное|составное"}]}],"practice":[{"t":"Подчеркните грамматическую основу.","key":"1) мы решили отправиться; 2) я пришёл (помочь – обстоятельство цели); 3) ветер начал стихать; 4) она готова ответить; 5) мальчик перестал бояться","items":["Мы решили отправиться в поход рано утром.","Я пришёл помочь тебе с уборкой.","К ночи ветер начал стихать.","Она готова ответить на любой вопрос.","Мальчик перестал бояться темноты."]},{"t":"Над инфинитивом подпишите его роль: «часть сказ.», «обст. цели» или «доп.».","key":"1) часть сказ.; 2) обст. цели; 3) доп.; 4) часть сказ.; 5) обст. цели","items":["Он умеет плавать.","Он вышел погулять.","Учитель велел нам читать вслух.","Мы продолжали спорить.","Друзья остановились отдохнуть."]},{"t":"Определите тип сказуемого. Запишите ответ в поле: номер – тип.\n\n1) Брат собирается поступать в колледж. 2) Брат поступит в колледж. 3) Брату надо поступать в колледж.","key":"1) составное глагольное (собирается поступать); 2) простое глагольное (поступит); 3) составное глагольное в односоставном предложении (надо поступать)"},{"t":"Задание в формате ОГЭ (2). Выпишите грамматическую основу.\n\nНесмотря на усталость, туристы продолжали подниматься к перевалу.","key":"туристы продолжали подниматься"}],"test":[{"q":"Где сказуемое составное глагольное?","o":["Он сел писать.","Он стал писать.","Он писал.","Он будет писать."],"a":1,"e":"«Стал» – начало действия.","tag":"Составное глагольное сказуемое"},{"q":"Где инфинитив – обстоятельство цели?","o":["Мы любим гулять.","Мы пошли гулять.","Мы перестали гулять.","Мы хотим гулять."],"a":1,"e":"Пошли (зачем?) гулять.","tag":"Составное глагольное сказуемое"},{"q":"Какое сказуемое: «Я должен вернуться»?","o":["простое глагольное","составное глагольное","составное именное"],"a":1,"e":"Должен + инфинитив.","tag":"Составное глагольное сказуемое"},{"q":"Выпишите сказуемое: «Птицы начали вить гнёзда».","a":"начали вить","e":"Фазовый глагол + инфинитив.","tag":"Составное глагольное сказуемое"},{"q":"В каком предложении инфинитив – дополнение?","o":["Отец научил меня плавать.","Я научился плавать.","Я люблю плавать.","Я пошёл плавать."],"a":0,"e":"Плавать будет «я», а учил отец: действие другого лица.","tag":"Составное глагольное сказуемое"},{"q":"Какое сказуемое: «Мы собираемся поехать на море»?","o":["простое глагольное","составное глагольное"],"a":1,"e":"Собираемся + инфинитив.","tag":"Составное глагольное сказуемое"}],"hwtest":[{"q":"Где сказуемое составное?","o":["Он может прийти.","Он придёт."],"a":0,"e":"Модальный глагол + инфинитив.","tag":"Составное глагольное сказуемое"},{"q":"Где инфинитив обозначает цель?","o":["Сестра уехала учиться.","Сестра продолжает учиться."],"a":0,"e":"Уехала (зачем?) учиться.","tag":"Составное глагольное сказуемое"},{"q":"Выпишите сказуемое: «Дождь перестал идти».","a":"перестал идти","e":"Фазовый глагол.","tag":"Составное глагольное сказуемое"}],"hw":"Записать 6 пар предложений: в первом инфинитив входит в составное сказуемое, во втором – обстоятельство цели (хотел учиться / приехал учиться). Подчеркнуть основу. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Составное глагольное сказуемое и инфинитив цели.","tips":["Проверка «чтобы».","Краткие прилагательные должен, рад, готов – вспомогательная часть.","Инфинитив действия другого лица – дополнение."]},"memo":{"h":"Проверка «чтобы»","t":"Если между глаголом и инфинитивом встаёт «чтобы» – инфинитив отвечает на вопрос «зачем?» и в сказуемое не входит.","ex":["Поехал (зачем?) учиться – простое.","Решил учиться – составное."]},"date":"2026-09-15"},{"id":"oge-ru-04","title":"Составное именное сказуемое","block":"s0","oge":"Задание 2 · Грамматическая основа","learn":["находить связку и именную часть","отличать составное именное сказуемое от простого"],"theory":[{"h":"Строение","t":"Составное именное сказуемое = глагол-связка + именная часть. Именная часть называет признак подлежащего: кто он? каков?","list":["Связка «быть» в настоящем времени обычно опускается: Брат – врач. Брат был врачом.","Полузнаменательные связки: стать, становиться, казаться, являться, считаться, оказаться.","Именная часть: существительное, прилагательное (полное или краткое), причастие, числительное, местоимение, наречие."],"ex":["[[s:Ночь]] [[p:была тихой]].","[[s:Он]] [[p:стал известным художником]].","[[s:Задача]] [[p:оказалась несложной]].","[[s:Море]] [[p:спокойно]]. (нулевая связка)"],"mini":[{"q":"Что такое нулевая связка?","a":"пропущенная связка быть|связка быть в настоящем времени|опущенная связка"},{"q":"Найдите именную часть: «Небо казалось бездонным».","a":"бездонным"}]},{"h":"Простое или составное именное?","t":"«Был» может быть и связкой, и самостоятельным глаголом.","list":["Он был в школе (находился) – простое глагольное.","Он был учителем (кем был?) – составное именное.","Краткое прилагательное и краткое причастие – всегда составное именное: Письмо написано. Он счастлив."],"ex":["[[s:Отец]] [[p:был]] дома. – простое","[[s:Отец]] [[p:был инженером]]. – составное именное"],"mini":[{"q":"«Окно открыто». Тип сказуемого?","a":"составное именное"},{"q":"«Мы были в музее». Тип сказуемого?","a":"простое глагольное|простое"}]}],"practice":[{"t":"Подчеркните грамматическую основу.","key":"1) вода была холодной; 2) мой брат – студент; 3) задание оказалось трудным; 4) двери заперты; 5) он считается лучшим вратарём","items":["Вода в озере была холодной.","Мой брат – студент.","Задание оказалось трудным.","Двери заперты на ключ.","Он считается лучшим вратарём школы."]},{"t":"Над именной частью подпишите, чем она выражена: сущ., прил., кр. прил., кр. прич.","key":"1) кр. прил. (рады); 2) сущ. (капитаном); 3) кр. прич. (закрыт); 4) прил. (свежим)","items":["Мы рады гостям.","Отец был капитаном.","Магазин закрыт.","Утро выдалось свежим."]},{"t":"Определите тип сказуемого (простое глагольное, составное глагольное, составное именное). Запишите в поле.\n\n1) Сестра была в библиотеке. 2) Сестра была библиотекарем. 3) Сестра хотела стать библиотекарем.","key":"1) простое глагольное; 2) составное именное; 3) хотела стать библиотекарем – сложное сказуемое (составное глагольное + именная часть); на ОГЭ достаточно указать «составное»"},{"t":"Задание в формате ОГЭ (2). Выпишите грамматическую основу.\n\nДорога после дождя стала скользкой и опасной.","key":"дорога стала скользкой и опасной"}],"test":[{"q":"Где сказуемое составное именное?","o":["Он стал врачом.","Он стал лечить.","Он лечил.","Он будет лечить."],"a":0,"e":"Стал (кем?) врачом.","tag":"Составное именное сказуемое"},{"q":"Какое сказуемое: «Дверь открыта»?","o":["простое глагольное","составное именное","составное глагольное"],"a":1,"e":"Краткое причастие – именная часть.","tag":"Составное именное сказуемое"},{"q":"В каком предложении «был» – самостоятельный глагол?","o":["Он был в театре.","Он был актёром.","Он был весёлым.","Он был прав."],"a":0,"e":"Был = находился.","tag":"Составное именное сказуемое"},{"q":"Выпишите именную часть: «Москва – столица России».","a":"столица","e":"Связка нулевая.","tag":"Составное именное сказуемое"},{"q":"Найдите предложение с нулевой связкой.","o":["Ветер холодный.","Ветер стал холодным.","Ветер был холодным.","Ветер дул холодный."],"a":0,"e":"Связка «есть» опущена.","tag":"Составное именное сказуемое"},{"q":"Какое сказуемое: «Вечер выдался тёплым»?","o":["простое глагольное","составное именное"],"a":1,"e":"Выдался – связка, тёплым – именная часть.","tag":"Составное именное сказуемое"}],"hwtest":[{"q":"Где сказуемое составное именное?","o":["Я счастлив.","Я радуюсь."],"a":0,"e":"Краткое прилагательное.","tag":"Составное именное сказуемое"},{"q":"Выпишите грамматическую основу: «Задача была решена быстро».","a":"задача была решена","e":"Связка + краткое причастие.","tag":"Составное именное сказуемое"},{"q":"Где сказуемое простое?","o":["Мы были на море.","Мы были моряками."],"a":0,"e":"Были = находились.","tag":"Составное именное сказуемое"}],"hw":"Составить 6 предложений с составным именным сказуемым: именная часть – сущ., полное прил., кр. прил., кр. прич.; одно – с нулевой связкой; одно – со связкой «казаться». Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Связка и именная часть; «был» как связка и как глагол.","tips":["Краткие формы – всегда именное сказуемое.","Тире между подлежащим и сказуемым – признак нулевой связки.","Вопрос «каков? кто он?»."]},"memo":{"h":"Вопрос к сказуемому","t":"Если к сказуемому можно задать вопрос «каков? кто он? что с ним?» – это именное сказуемое. Если «что делает?» – глагольное.","ex":["Лес был (каков?) густым.","Лес был (где?) за рекой – простое."]},"date":"2026-09-22"},{"id":"oge-ru-05","title":"Односоставные предложения","block":"s0","oge":"Задание 2 · Грамматическая основа","learn":["отличать двусоставные и односоставные предложения","определять вид односоставного предложения"],"theory":[{"h":"Что такое односоставное предложение","t":"В односоставном предложении один главный член, и второй не нужен для понимания.","list":["Подчёркиваем главный член так, как подсказывает его форма: существительное в им. п. – одной чертой, глагол – двумя.","Неполное предложение – другое: в нём член пропущен, но восстанавливается из соседнего предложения."],"ex":["[[s:Зима]]. – назывное","[[p:Люблю]] грозу в начале мая. – определённо-личное"],"mini":[{"q":"Сколько главных членов в односоставном предложении?","a":"один|1"}]},{"h":"Виды односоставных предложений","table":[["Вид","Главный член","Пример"],["определённо-личное","глагол 1-го или 2-го лица, повелительное наклонение (деятель – я, мы, ты, вы)","[[p:Читаю]] книгу. [[p:Приходите]] завтра."],["неопределённо-личное","глагол 3-го лица мн. ч. или прошедшее время мн. ч. (деятель неизвестен)","В дверь [[p:постучали]]."],["обобщённо-личное","действие относится к любому человеку (пословицы)","Что [[p:посеешь]], то и [[p:пожнёшь]]."],["безличное","нет и не может быть деятеля: безличный глагол, слово категории состояния, инфинитив, «нет»","[[p:Светает]]. Мне [[p:холодно]]. [[p:Не видать]] берегов."],["назывное","существительное в им. п. (бытие, наличие)","[[s:Ночь]]. [[s:Улица]]. [[s:Фонарь]]."]],"mini":[{"q":"«Звонят в дверь». Какой вид?","a":"неопределённо-личное"},{"q":"«Смеркалось». Какой вид?","a":"безличное"},{"q":"«Тишина». Какой вид?","a":"назывное"}]},{"h":"Как определить вид: алгоритм","list":["1. Нашли главный член. Это существительное в им. п.? – назывное.","2. Глагол. Можно подставить «я / ты / мы / вы»? – определённо-личное.","3. Можно подставить «они» (кто-то)? – неопределённо-личное.","4. Деятеля нет и не подставить никого? – безличное."],"ex":["Мне не спится. – безличное (форма на -ся без деятеля)","Тебе звонили. – неопределённо-личное"],"mini":[{"q":"«Мне не спится» – какой вид?","a":"безличное"}]}],"practice":[{"t":"Подчеркните главный член каждого предложения.","key":"1) утро (назывное); 2) иду (определённо-личное); 3) вынесли (неопр.-личное); 4) свежо (безличное); 5) любишь, люби (обобщённо-личное)","items":["Раннее утро.","Иду по тропинке к реке.","Из дома вынесли старый шкаф.","На улице свежо.","Любишь кататься – люби и саночки возить."]},{"t":"Над главным членом подпишите вид предложения: опр.-л., неопр.-л., обобщ.-л., безл., назыв.","key":"1) безл.; 2) неопр.-л.; 3) опр.-л.; 4) назыв.; 5) безл.","items":["Морозит.","Об этом писали в газетах.","Пишите разборчиво.","Тишина и покой.","Нам не хватило времени."]},{"t":"Найдите среди предложений двусоставные. Запишите их номера в поле.\n\n1) Ветер стих. 2) Тихо. 3) Мне тихо и спокойно. 4) Звёзды погасли. 5) Ночь.","key":"1 и 4"},{"t":"Определите, двусоставное это предложение или односоставное, и выпишите грамматическую основу.\n\nДо самого вечера мне не давали покоя тревожные мысли.","key":"двусоставное: мысли не давали покоя («мне» – дополнение)"},{"t":"Определите вид предложения и выпишите главный член.\n\nВ классе громко заговорили о предстоящих каникулах.","key":"неопределённо-личное: заговорили"}],"test":[{"q":"Определите вид: «Пахнет сиренью».","o":["безличное","неопределённо-личное","назывное","определённо-личное"],"a":0,"e":"Безличный глагол, деятеля нет.","tag":"Односоставные предложения"},{"q":"Определите вид: «Ждём вас в гости».","o":["определённо-личное","неопределённо-личное","безличное"],"a":0,"e":"Ждём = мы ждём.","tag":"Односоставные предложения"},{"q":"Определите вид: «На стене повесили карту».","o":["неопределённо-личное","безличное","назывное"],"a":0,"e":"Кто-то повесил.","tag":"Односоставные предложения"},{"q":"Какое предложение назывное?","o":["Летний вечер.","Вечереет.","Вечер наступил.","Вечером гуляли."],"a":0,"e":"Главный член – существительное в им. п.","tag":"Односоставные предложения"},{"q":"Какое предложение двусоставное?","o":["Мне холодно.","Холодно.","Ветер холодный.","Похолодало."],"a":2,"e":"Ветер (подлежащее) + холодный (сказуемое).","tag":"Односоставные предложения"},{"q":"Выпишите главный член: «Без труда не вытащишь и рыбку из пруда».","a":"не вытащишь","e":"Обобщённо-личное предложение.","tag":"Односоставные предложения"},{"q":"Какой вид: «Нельзя опаздывать»?","o":["безличное","определённо-личное","неопределённо-личное"],"a":0,"e":"Нельзя + инфинитив.","tag":"Односоставные предложения"}],"hwtest":[{"q":"Вид: «Стемнело».","o":["безличное","назывное"],"a":0,"e":"Безличный глагол.","tag":"Односоставные предложения"},{"q":"Вид: «Позвоните мне вечером».","o":["определённо-личное","неопределённо-личное"],"a":0,"e":"Повелительное наклонение.","tag":"Односоставные предложения"},{"q":"Выпишите главный член: «Тебя искали все утро».","a":"искали","e":"Неопределённо-личное.","tag":"Односоставные предложения"},{"q":"Вид: «Осень».","o":["назывное","безличное"],"a":0,"e":"Существительное в им. п.","tag":"Односоставные предложения"}],"hw":"Найти в стихотворениях А. С. Пушкина или Ф. И. Тютчева по два односоставных предложения каждого вида (5 видов). Выписать, подчеркнуть главный член, подписать вид. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Вид односоставного предложения по форме главного члена.","tips":["Подставляем «я/ты/мы/вы» или «они».","Дополнение в дательном падеже (мне, нам) – не подлежащее.","Назывное – только существительное в им. п., без сказуемого."]},"memo":{"h":"Безличное ≠ неопределённо-личное","t":"В неопределённо-личном деятель есть, но неизвестен: «Дверь открыли» (кто-то открыл). В безличном деятеля нет вообще: «Мне грустно».","ex":["Принесли почту. – неопр.-личное","Стемнело. – безличное"]},"date":"2026-09-29"},{"id":"oge-ru-06","title":"Однородные члены предложения","block":"s0","oge":"Задание 2 · Грамматическая основа","learn":["находить однородные члены","ставить знаки при однородных членах и обобщающем слове","отличать однородные определения от неоднородных"],"theory":[{"h":"Однородные члены и союзы","t":"Однородные члены отвечают на один вопрос, относятся к одному слову и являются одним членом предложения.","list":["Без союзов – запятая: Читали, писали, решали.","Одиночные союзы И, ДА (= и), ИЛИ – запятая не ставится: Читали и писали.","Противительные А, НО, ДА (= но), ОДНАКО – запятая ставится: Маленький, но сильный.","Повторяющиеся союзы (и… и, ни… ни, или… или) – запятая перед вторым и далее: И днём, и ночью.","Двойные союзы (как… так и, не только… но и) – запятая перед второй частью: Не только дети, но и взрослые."],"ex":["[[s:Мы]] [[p:купили]] [[o:яблоки]], [[o:груши]] и [[o:сливы]].","Ни [[s:ветер]], ни [[s:дождь]] не [[p:испугали]] туристов."],"mini":[{"q":"Нужна ли запятая: «Читали и рисовали»?","a":"нет"},{"q":"Нужна ли запятая перед «но»: «Медленно но верно»?","a":"да"}]},{"h":"Обобщающее слово","t":"Обобщающее слово называет то, что потом перечисляется.","list":["Обобщающее слово перед однородными – двоеточие: Везде: в поле, в лесу, в саду – тишина.","После однородных – тире: В поле, в лесу, в саду – везде тишина.","Если после перечня предложение продолжается – двоеточие перед и тире после."],"mini":[{"q":"Какой знак ставим после обобщающего слова перед однородными членами?","a":"двоеточие"}]},{"h":"Однородные и неоднородные определения","t":"Однородные определения характеризуют предмет с одной стороны (по цвету, размеру, впечатлению) – между ними запятая. Неоднородные – с разных сторон, запятая не нужна.","list":["Красные, жёлтые, оранжевые листья – однородные (цвет).","Большой каменный дом – неоднородные (размер и материал).","Проверка: можно ли вставить «и»? Если да – однородные."],"mini":[{"q":"«Старый деревянный мост» – нужна ли запятая?","a":"нет"}]}],"practice":[{"t":"Расставьте знаки препинания (нажимайте на промежутки между словами).","key":"1) Над лугом летали бабочки, стрекозы и пчёлы. 2) Он говорил тихо, но уверенно. 3) И в городе, и в деревне ждали весны. 4) На столе лежало всё необходимое: тетради, ручки, линейка. 5) Ни мороз, ни ветер не остановили путников.","items":["Над лугом летали бабочки стрекозы и пчёлы.","Он говорил тихо но уверенно.","И в городе и в деревне ждали весны.","На столе лежало всё необходимое тетради ручки линейка.","Ни мороз ни ветер не остановили путников."]},{"t":"Подчеркните однородные члены как члены предложения (выберите нужный инструмент).","key":"1) поля, леса, луга – подлежащие; 2) читал и перечитывал – сказуемые; 3) в саду и в огороде – обстоятельства; 4) тёплое, ласковое – определения","items":["Поля леса и луга покрылись снегом.","Он читал и перечитывал письмо.","Мама работала в саду и в огороде.","Светило тёплое ласковое солнце."]},{"t":"Расставьте знаки. Объясните в поле, где определения однородные, а где нет.","key":"1) Высокие, стройные сосны (однородные – впечатление); 2) Высокие корабельные сосны (неоднородные – размер и назначение); 3) Белые, розовые, лиловые астры (однородные – цвет); 4) Новый школьный стадион (неоднородные)","items":["Высокие стройные сосны тянулись к небу.","Высокие корабельные сосны тянулись к небу.","На клумбе цвели белые розовые лиловые астры.","Открылся новый школьный стадион."]},{"t":"Расставьте знаки при обобщающем слове.","key":"1) Везде: на улицах, во дворах, на крышах – лежал снег. 2) Книги, тетради, карандаши – всё было разбросано. 3) Мы видели много птиц: снегирей, синиц, дятлов.","items":["Везде на улицах во дворах на крышах лежал снег.","Книги тетради карандаши всё было разбросано.","Мы видели много птиц снегирей синиц дятлов."]},{"t":"Задание в формате ОГЭ (3). Укажите номера, на месте которых в предложении должны стоять запятые. Запишите в поле.\n\nУтро было холодным (1) но ясным (2) и ребята решили (3) не только позавтракать (4) но и выйти к реке.","key":"1, 2, 4 (1 – перед «но»; 2 – между частями сложного предложения перед «и»; 4 – перед «но и»)"}],"test":[{"q":"Где нужна одна запятая?","o":["Он любил и музыку и живопись.","Он любил музыку и живопись.","Он любил музыку живопись и театр.","Он любил ни музыку ни живопись."],"a":0,"e":"Повторяющийся союз и… и: запятая перед вторым «и».","tag":"Однородные члены предложения"},{"q":"Где запятая НЕ нужна?","o":["Мы купили хлеб и молоко.","Мы купили хлеб но не молоко.","Мы купили не только хлеб но и молоко.","Мы купили хлеб молоко."],"a":0,"e":"Одиночный союз «и».","tag":"Однородные члены предложения"},{"q":"Какие определения однородные?","o":["густой еловый лес","густой тёмный лес","большой каменный дом","старый городской парк"],"a":1,"e":"Густой и тёмный – впечатление, можно вставить «и».","tag":"Однородные члены предложения"},{"q":"Какой знак после обобщающего слова, стоящего после однородных?","o":["тире","двоеточие","запятая"],"a":0,"e":"Однородные – тире – обобщающее слово.","tag":"Однородные члены предложения"},{"q":"Сколько запятых: «Ни солнце ни ветер ни дождь не мешали работе»?","a":"2","e":"Перед вторым и третьим «ни».","tag":"Однородные члены предложения"},{"q":"Где пунктуационная ошибка?","o":["Шёл дождь, и снег.","Шёл то дождь, то снег.","Шёл дождь или снег.","Шёл не дождь, а снег."],"a":0,"e":"Перед одиночным «и» с однородными запятая не нужна.","tag":"Однородные члены предложения"}],"hwtest":[{"q":"Нужна ли запятая: «Тихо но твёрдо»?","o":["да","нет"],"a":0,"e":"Противительный союз.","tag":"Однородные члены предложения"},{"q":"Где однородные определения?","o":["красные жёлтые листья","красные кленовые листья"],"a":0,"e":"Оба – цвет.","tag":"Однородные члены предложения"},{"q":"Знак после обобщающего слова перед однородными:","o":["двоеточие","тире"],"a":0,"e":"Обобщающее слово: О, О.","tag":"Однородные члены предложения"},{"q":"Сколько запятых: «И я и ты и он знали ответ»?","a":"2","e":"Повторяющийся союз.","tag":"Однородные члены предложения"}],"hw":"Составить 8 предложений по схемам из памятки (по одному на схему) и 2 пары предложений с однородными и неоднородными определениями. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Знаки при однородных членах: союзы и обобщающее слово.","tips":["Сначала находим однородные, потом смотрим на союзы.","Противительные союзы – всегда запятая.","Определения: проверка вставкой «и»."]},"memo":{"h":"Схемы с однородными","t":"Кружок – однородный член. Знак ставим так, как он стоит в предложении.","ex":["О, О и О.","И О, и О.","Не только О, но и О.","Обобщ. слово: О, О, О.","О, О – обобщ. слово."]},"date":"2026-10-06"},{"id":"oge-ru-07","title":"Причастный оборот: когда ставим запятые","block":"s1","oge":"Задание 3 · Обособленные члены","learn":["находить причастный оборот и определяемое слово","обособлять причастный оборот, стоящий после определяемого слова"],"theory":[{"h":"Причастный оборот и определяемое слово","t":"Причастный оборот – причастие с зависимыми словами. Он относится к существительному – определяемому слову – и отвечает на вопрос «какой?».","list":["Определяемое слово отмечаем крестиком, оборот подчёркиваем волнистой линией (это определение).","От определяемого слова ставим вопрос к причастию: лист (какой?) упавший на воду.","Зависимые слова причастия входят в оборот: упавший (куда?) на воду."],"ex":["[[x:Лист]], [[w:упавший на воду]], медленно поплыл.","[[w:Упавший на воду]] [[x:лист]] медленно поплыл."],"scheme":"✕слово, | причастный оборот |, …        | причастный оборот | ✕слово …","mini":[{"q":"Что такое причастный оборот?","a":"причастие с зависимыми словами|причастие с зависимыми"},{"q":"Каким членом предложения является причастный оборот?","a":"определением|определение"}]},{"h":"Главное правило","t":"Причастный оборот обособляется, если стоит после определяемого слова. Если он стоит перед определяемым словом – запятые не ставим.","list":["Оборот в середине предложения – запятые с двух сторон.","Оборот в конце – одна запятая перед ним.","Оборот перед определяемым словом – без запятых (кроме оборота при личном местоимении – об этом следующее занятие)."],"ex":["Мы подошли к [[x:дому]], [[w:стоящему на краю деревни]].","Наконец показалась [[w:стоящая на краю деревни]] [[x:изба]]."],"mini":[{"q":"Нужны ли запятые: «Прочитанная мной книга лежит на столе»?","a":"нет"},{"q":"Сколько запятых: «Книга прочитанная мной лежит на столе»?","a":"2|две"}]},{"h":"Ловушки в заданиях ОГЭ","list":["Оборот может быть отделён от определяемого слова другими словами – запятая всё равно нужна: [[x:Лес]] стоял, [[w:покрытый инеем]].","Два оборота при одном слове, соединённые «и», – запятой между ними нет: Тропинка, заросшая травой и уходящая в лес, была едва видна.","Причастие без зависимых слов (одиночное) после слова обычно не обособляется: Шёл человек усталый."],"mini":[{"q":"Нужна ли запятая между оборотами, соединёнными «и»?","a":"нет"}]}],"practice":[{"t":"Поставьте крестик над определяемым словом (инструмент «Определяемое слово») и подчеркните причастный оборот волнистой линией.","key":"1) дорога – ведущая к лесу; 2) звёзды – мерцавшие в вышине; 3) снегом (оборот: засыпанные снегом), определяемое – ветви; 4) письмо – полученное утром","items":["Дорога ведущая к лесу заросла травой.","Мы любовались звёздами мерцавшими в вышине.","Засыпанные снегом ветви сосен склонились к земле.","Письмо полученное утром лежало нераспечатанным."]},{"t":"Расставьте запятые.","key":"1) Дорога, ведущая к лесу, заросла травой. 2) Мы любовались звёздами, мерцавшими в вышине. 3) Без запятых. 4) Письмо, полученное утром, лежало нераспечатанным. 5) Без запятых.","items":["Дорога ведущая к лесу заросла травой.","Мы любовались звёздами мерцавшими в вышине.","Засыпанные снегом ветви сосен склонились к земле.","Письмо полученное утром лежало нераспечатанным.","Спрятавшееся за тучу солнце не показывалось до вечера."]},{"t":"Расставьте запятые. В двух предложениях два оборота при одном слове.","key":"1) Старик, сидевший у ворот и куривший трубку, кивнул нам. 2) Над полем, покрытым росой, поднимался туман. 3) Тропинка, петлявшая между холмами и терявшаяся в траве, привела нас к роднику. 4) Мы вошли в зал, украшенный цветами.","items":["Старик сидевший у ворот и куривший трубку кивнул нам.","Над полем покрытым росой поднимался туман.","Тропинка петлявшая между холмами и терявшаяся в траве привела нас к роднику.","Мы вошли в зал украшенный цветами."]},{"t":"Перестройте предложения так, чтобы оборот стоял после определяемого слова, и запишите их с запятыми.\n\n1) Выросшие за лето подсолнухи стояли вдоль забора. 2) Пожелтевшие от времени страницы шуршали в руках.","key":"1) Подсолнухи, выросшие за лето, стояли вдоль забора. 2) Страницы, пожелтевшие от времени, шуршали в руках."},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nВетер (1) налетевший с моря (2) раскачивал рыбацкие лодки (3) привязанные к причалу (4) и гнал на берег пену.","key":"1, 2, 3, 4"}],"test":[{"q":"В каком предложении нужны запятые?","o":["Сорванный ветром лист упал в реку.","Лист сорванный ветром упал в реку.","Ветер сорвал лист.","Лист упал в реку."],"a":1,"e":"Оборот после определяемого слова.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Где причастный оборот НЕ обособляется?","o":["Мост построенный в прошлом веке ещё стоит.","Построенный в прошлом веке мост ещё стоит.","Мы прошли по мосту построенному в прошлом веке."],"a":1,"e":"Оборот перед определяемым словом.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Сколько запятых: «Мы вышли на поляну освещённую солнцем»?","a":"1|одна","e":"Оборот в конце предложения – одна запятая.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Найдите определяемое слово: «Мальчик, читавший книгу, не заметил нас».","a":"мальчик","e":"Мальчик (какой?) читавший книгу.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Где пунктуационная ошибка?","o":["Река, покрытая льдом, блестела.","Покрытая льдом, река блестела.","Мы шли по реке, покрытой льдом."],"a":1,"e":"Оборот перед определяемым словом не обособляется.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Как подчёркивается причастный оборот?","o":["волнистой линией","двумя чертами","штрихпунктиром","пунктиром"],"a":0,"e":"Он является определением.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Нужна ли запятая между оборотами: «Книга, изданная давно и забытая всеми, лежала на полке»?","o":["нет","да"],"a":0,"e":"Обороты соединены союзом «и».","tag":"Причастный оборот: когда ставим запятые"}],"hwtest":[{"q":"Где нужны запятые?","o":["Спящий в кресле кот мурлыкал.","Кот спящий в кресле мурлыкал."],"a":1,"e":"Оборот после слова.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Сколько запятых: «Я увидел корабль идущий к берегу»?","a":"1|одна","e":"Оборот в конце.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Найдите определяемое слово: «Нарисованный углём портрет висел над камином».","a":"портрет","e":"Портрет (какой?) нарисованный углём.","tag":"Причастный оборот: когда ставим запятые"},{"q":"Где ошибка?","o":["Пришедшие, гости разделись.","Гости, пришедшие первыми, разделись."],"a":0,"e":"Запятая разорвала определение и определяемое слово.","tag":"Причастный оборот: когда ставим запятые"}],"hw":"Выписать из повести А. С. Пушкина «Капитанская дочка» или рассказов И. С. Тургенева 6 предложений с причастными оборотами: 3 – оборот после определяемого слова, 3 – перед ним. Отметить крестиком определяемое слово, подчеркнуть оборот. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Причастный оборот: место относительно определяемого слова решает всё.","tips":["Сначала крестик над определяемым словом.","Оборот в конце – одна запятая.","Обороты, соединённые «и», не разделяем запятой."]},"memo":{"h":"Три шага","t":"1) Найди причастие. 2) Найди слово, к которому оно относится, и поставь над ним крестик. 3) Оборот после крестика – выделяй, перед крестиком – нет.","ex":["[[x:Река]], [[w:скованная льдом]], молчала.","[[w:Скованная льдом]] [[x:река]] молчала."]},"date":"2026-10-13"},{"id":"oge-ru-08","title":"Одиночные и однородные определения, определения при местоимении","block":"s1","oge":"Задание 3 · Обособленные члены","learn":["обособлять два и более определения после определяемого слова","обособлять определения при личном местоимении"],"theory":[{"h":"Однородные определения после определяемого слова","t":"Два и более согласованных определения, стоящих после определяемого слова, обособляются.","list":["Одиночное определение после слова обычно не обособляется: Шёл человек усталый.","Два определения после слова – обособляем: Ночь, тёплая и звёздная, опустилась на город."],"ex":["[[x:Море]], [[w:спокойное]] и [[w:ласковое]], манило к себе.","[[x:Глаза]] её, [[w:серые]], [[w:внимательные]], смотрели прямо."],"mini":[{"q":"Сколько запятых: «Утро ясное и тихое обещало хороший день»?","a":"2|две"}]},{"h":"Определение при личном местоимении","t":"Определение, относящееся к личному местоимению (я, ты, он, она, мы, вы, они), обособляется всегда – и одиночное, и с оборотом, и перед местоимением, и после.","list":["[[w:Уставшие]], [[x:мы]] сели отдохнуть.","[[x:Он]], [[w:взволнованный]], вбежал в комнату.","[[w:Окружённый друзьями]], [[x:он]] улыбался."],"mini":[{"q":"Нужна ли запятая: «Счастливая она вернулась домой»?","a":"да"},{"q":"Нужна ли запятая: «Счастливая девочка вернулась домой»?","a":"нет"}]},{"h":"Когда определение входит в сказуемое","t":"Если прилагательное или причастие связано и с подлежащим, и со сказуемым, оно входит в состав сказуемого и не обособляется.","list":["Он вернулся усталым. Она сидела задумчивая.","Проверка: без этого слова смысл сказуемого обеднеет – «он вернулся каким?»."],"ex":["[[s:Он]] [[p:вернулся усталым]]."],"mini":[{"q":"«Мы пришли домой промокшие». Обособлять «промокшие»?","a":"нет"}]}],"practice":[{"t":"Поставьте крестик над определяемым словом и подчеркните определения волнистой линией.","key":"1) лес – густой, тёмный; 2) она – испуганная; 3) мы – измученные долгой дорогой; 4) голос – тихий, ласковый","items":["Лес густой и тёмный стоял стеной.","Испуганная она замолчала.","Измученные долгой дорогой мы уснули.","Голос её тихий ласковый успокаивал."]},{"t":"Расставьте запятые.","key":"1) Лес, густой и тёмный, стоял стеной. 2) Испуганная, она замолчала. 3) Измученные долгой дорогой, мы уснули. 4) Голос её, тихий, ласковый, успокаивал. 5) Без запятых.","items":["Лес густой и тёмный стоял стеной.","Испуганная она замолчала.","Измученные долгой дорогой мы уснули.","Голос её тихий ласковый успокаивал.","Измученные долгой дорогой путники уснули."]},{"t":"Расставьте запятые там, где они нужны. В одном предложении определение входит в сказуемое.","key":"1) Довольный, он рассмеялся. 2) Мы вернулись из похода загорелые (без запятых – часть сказуемого). 3) Река, широкая и быстрая, бурлила у камней. 4) Он, бледный, встал из-за стола.","items":["Довольный он рассмеялся.","Мы вернулись из похода загорелые.","Река широкая и быстрая бурлила у камней.","Он бледный встал из-за стола."]},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nПрохладный (1) после грозы (2) воздух был чист. Освежённые (3) мы двинулись дальше (4) по лесной тропе.","key":"3 (определение при местоимении «мы»); в первом предложении запятых нет"}],"test":[{"q":"Где нужна запятая?","o":["Весёлая она убежала.","Весёлая девочка убежала.","Девочка весёлая убежала.","Она была весёлая."],"a":0,"e":"Определение при личном местоимении.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"Сколько запятых: «Вода холодная и прозрачная бежала по камням»?","a":"2|две","e":"Два определения после определяемого слова.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"В каком предложении определение – часть сказуемого?","o":["Он пришёл усталый.","Усталый, он пришёл.","Он, усталый, пришёл.","Усталый человек пришёл."],"a":0,"e":"Пришёл каким? – связано со сказуемым.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"Где ошибка?","o":["Голодные, мы набросились на еду.","Голодные, ребята набросились на еду.","Мы, голодные, набросились на еду."],"a":1,"e":"Перед существительным одиночное определение не обособляется.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"Какое определение обособляется всегда?","o":["относящееся к личному местоимению","стоящее перед существительным","одиночное после существительного"],"a":0,"e":"Правило для личных местоимений.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"Нужны ли запятые: «Окно распахнутое настежь хлопало от ветра»?","o":["да, две","нет","одна"],"a":0,"e":"Причастный оборот после определяемого слова.","tag":"Одиночные и однородные определения, определения при местоимении"}],"hwtest":[{"q":"Где нужна запятая?","o":["Радостный он вбежал.","Радостный мальчик вбежал."],"a":0,"e":"Личное местоимение.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"Сколько запятых: «Ночь тихая и светлая стояла над городом»?","a":"2|две","e":"Два определения после слова.","tag":"Одиночные и однородные определения, определения при местоимении"},{"q":"Обособлять ли «весёлые»: «Мы вернулись весёлые»?","o":["нет","да"],"a":0,"e":"Часть сказуемого.","tag":"Одиночные и однородные определения, определения при местоимении"}],"hw":"Составить 6 предложений: 2 – с однородными определениями после определяемого слова, 2 – с определением при личном местоимении (перед ним и после), 2 – с определением в составе сказуемого. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Согласованные определения без причастного оборота: однородные после слова и при местоимении.","tips":["Личное местоимение – всегда запятые.","Одно определение после существительного – обычно без запятых.","Определение-часть сказуемого не обособляем."]},"memo":{"h":"Личное местоимение – всегда запятые","t":"Определение при «я, ты, он, мы, вы, они» выделяется где бы ни стояло. При существительном – смотрим на место и количество определений.","ex":["Голодный, он съел всё.","Голодный пёс съел всё.","Пёс, голодный и злой, рычал."]},"date":"2026-10-20"},{"id":"oge-ru-09","title":"Приложения","block":"s1","oge":"Задание 3 · Обособленные члены","learn":["находить приложение","обособлять распространённые приложения и приложения при местоимении","ставить дефис и тире при приложениях"],"theory":[{"h":"Что такое приложение","t":"Приложение – определение, выраженное существительным в том же падеже, что и определяемое слово. Оно даёт предмету другое название: профессия, возраст, родство, характеристика.","list":["Подчёркиваем волнистой линией, как определение.","Река Волга, город Казань, мой друг – инженер, учитель Петров."],"ex":["[[x:Брат]], [[w:студент университета]], приехал на каникулы."],"mini":[{"q":"Какой частью речи выражено приложение?","a":"существительным|существительное"}]},{"h":"Когда приложение обособляется","list":["Распространённое приложение после нарицательного существительного: Мой дед, старый моряк, любил рассказывать истории.","Приложение после имени собственного: Иван Петрович, наш сосед, починил забор.","Приложение при личном местоимении – всегда: Он, опытный врач, сразу всё понял. Опытный врач, он сразу всё понял.","Приложение с «как» в значении причины («будучи») обособляется: Как опытный врач, он понимал опасность."],"mini":[{"q":"Нужна ли запятая: «Как специалист он был незаменим»? («как» = в качестве)","a":"нет"},{"q":"Обособляется ли приложение при местоимении «он»?","a":"да|всегда"}]},{"h":"Дефис и тире","list":["Одиночное приложение к нарицательному существительному пишется через дефис: девочка-подросток, город-герой, учитель-новатор.","Не пишем дефис, если приложение стоит перед словом и само является прилагательным по смыслу: красавица дочь.","Тире ставят, если приложение в конце предложения поясняет и перед ним можно вставить «а именно»: Я люблю одно время года – осень."],"mini":[{"q":"Как пишется: город(?)герой?","a":"город-герой|через дефис"}]}],"practice":[{"t":"Поставьте крестик над определяемым словом и подчеркните приложение волнистой линией.","key":"1) Пётр Ильич – знаменитый композитор; 2) бабушка – бывшая учительница; 3) мы – жители маленького посёлка; 4) Ока – приток Волги","items":["Пётр Ильич знаменитый композитор родился в Воткинске.","Моя бабушка бывшая учительница проверяет мои тетради.","Мы жители маленького посёлка привыкли к тишине.","Ока приток Волги протекает через Калугу."]},{"t":"Расставьте знаки препинания.","key":"1) Пётр Ильич, знаменитый композитор, родился в Воткинске. 2) Моя бабушка, бывшая учительница, проверяет мои тетради. 3) Мы, жители маленького посёлка, привыкли к тишине. 4) Ока, приток Волги, протекает через Калугу.","items":["Пётр Ильич знаменитый композитор родился в Воткинске.","Моя бабушка бывшая учительница проверяет мои тетради.","Мы жители маленького посёлка привыкли к тишине.","Ока приток Волги протекает через Калугу."]},{"t":"Вставьте дефис там, где он нужен (впишите в пропуск «-» или оставьте пустым).","key":"город-герой, девочка-подросток, учитель-новатор, старик-рыбак, Москва-река","items":["город..герой","девочка..подросток","учитель..новатор","старик..рыбак","Москва..река"]},{"t":"Объясните, почему в одном предложении запятая нужна, а в другом нет. Запишите в поле.\n\n1) Как опытный врач, он сразу понял причину болезни. 2) Он работал в больнице как врач.","key":"1) «как опытный врач» = будучи опытным врачом (причина) – обособляем; 2) «как врач» = в качестве врача – не обособляем"},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nНаш учитель (1) географ по образованию (2) повёл нас в поход к реке (3) Чусовой (4) славящейся своими скалами.","key":"1, 2, 4"}],"test":[{"q":"Где есть приложение?","o":["Мой дядя, лётчик, приехал.","Мой дядя приехал.","Дядя приехал на самолёте.","Дядя и лётчик приехали."],"a":0,"e":"Лётчик – второе название дяди.","tag":"Приложения"},{"q":"Где нужна запятая?","o":["Он отличный пловец выиграл заплыв.","Отличный пловец выиграл заплыв.","Пловец выиграл заплыв.","Он выиграл заплыв."],"a":0,"e":"Приложение при личном местоимении: Он, отличный пловец, выиграл заплыв.","tag":"Приложения"},{"q":"Как пишется: «зима(?)волшебница»?","o":["через дефис","раздельно","слитно"],"a":0,"e":"Одиночное приложение к нарицательному существительному.","tag":"Приложения"},{"q":"Где «как» вводит обособленное приложение?","o":["Как старший, он отвечал за младших.","Он выступил как свидетель."],"a":0,"e":"Как старший = будучи старшим.","tag":"Приложения"},{"q":"Сколько запятых: «Гоголь автор „Мёртвых душ“ родился на Украине»?","a":"2|две","e":"Приложение после имени собственного.","tag":"Приложения"},{"q":"Какой знак: «В саду росло одно дерево ? старая яблоня»?","o":["тире","запятая","двоеточие"],"a":0,"e":"Можно вставить «а именно».","tag":"Приложения"}],"hwtest":[{"q":"Где приложение?","o":["Моя сестра, врач, спешила.","Моя сестра спешила к врачу."],"a":0,"e":"Врач – второе название сестры.","tag":"Приложения"},{"q":"Нужна ли запятая: «Мы студенты первого курса волновались»?","o":["да","нет"],"a":0,"e":"Приложение при местоимении.","tag":"Приложения"},{"q":"Как пишется: «мать(?)героиня»?","o":["через дефис","раздельно"],"a":0,"e":"Одиночное приложение.","tag":"Приложения"}],"hw":"Написать 6 предложений о знаменитых людях, используя распространённые приложения (профессия, заслуги); 2 – с приложением при личном местоимении; 2 слова с приложением через дефис. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Приложение – второе название предмета: когда запятые, когда дефис, когда тире.","tips":["Приложение = существительное в том же падеже.","При местоимении – всегда запятые.","«Как» = «будучи» – запятая; «как» = «в качестве» – нет."]},"memo":{"h":"Как найти приложение","t":"Ищем второе название того же предмета, выраженное существительным. «Кто он такой?» – «мой друг, художник».","ex":["Чехов, писатель и врач, ...","Москва – столица России (здесь не приложение, а сказуемое!)."]},"date":"2026-10-27"},{"id":"oge-ru-10","title":"Деепричастный оборот","block":"s1","oge":"Задание 3 · Обособленные члены","learn":["находить деепричастный оборот","выделять его запятыми в любом месте предложения","правильно ставить запятые рядом с союзами"],"theory":[{"h":"Деепричастный оборот","t":"Деепричастный оборот – деепричастие с зависимыми словами. Он обозначает добавочное действие и относится к глаголу-сказуемому, отвечая на вопрос «что делая? что сделав?».","list":["Подчёркиваем штрихпунктиром (как обстоятельство).","Деепричастия: читая, слушая, прочитав, оглянувшись.","Добавочное действие выполняет тот же, кто и основное: Он шёл (что делая?) насвистывая песенку."],"ex":["[[a:Закончив работу]], [[s:мы]] [[p:пошли]] домой.","[[s:Птицы]], [[a:громко щебеча]], [[p:кружили]] над деревом."],"mini":[{"q":"На какой вопрос отвечает деепричастный оборот?","a":"что делая? что сделав?|что делая|что сделав"},{"q":"Каким членом предложения является оборот?","a":"обстоятельством|обстоятельство"}]},{"h":"Главное правило","t":"Деепричастный оборот выделяется запятыми всегда, где бы он ни стоял.","list":["В начале – запятая после оборота.","В середине – запятые с двух сторон.","В конце – запятая перед оборотом."],"ex":["[[a:Взяв зонт]], она вышла.","Она, [[a:взяв зонт]], вышла.","Она вышла, [[a:взяв зонт]]."],"mini":[{"q":"Сколько запятых: «Мы шли по лесу собирая грибы»?","a":"1|одна"}]},{"h":"Оборот рядом с союзом","list":["Союз «и» перед оборотом не входит в него: Он улыбнулся и, махнув рукой, ушёл.","Два оборота, соединённые «и», не разделяются запятой: Подбежав к окну и распахнув его, он закричал.","Оборот в начале части сложного предложения: Солнце село, и, озябнув, мы вернулись в дом."],"ex":["Кот потянулся и, [[a:зевнув во весь рот]], улёгся снова."],"mini":[{"q":"Где ставим запятую: «…и махнув рукой ушёл»?","a":"после и и после рукой|и, махнув рукой, ушёл"}]}],"practice":[{"t":"Подчеркните деепричастный оборот штрихпунктиром (инструмент «Обстоятельство»), сказуемое – двумя чертами.","key":"1) выйдя из дома – заметил; 2) не отрывая глаз от книги – читала; 3) пригревая землю – светило; 4) обойдя все залы – вышли","items":["Выйдя из дома я заметил туман.","Сестра читала не отрывая глаз от книги.","Солнце пригревая землю светило всё ярче.","Обойдя все залы музея мы вышли на улицу."]},{"t":"Расставьте запятые.","key":"1) Выйдя из дома, я заметил туман. 2) Сестра читала, не отрывая глаз от книги. 3) Солнце, пригревая землю, светило всё ярче. 4) Обойдя все залы музея, мы вышли на улицу.","items":["Выйдя из дома я заметил туман.","Сестра читала не отрывая глаз от книги.","Солнце пригревая землю светило всё ярче.","Обойдя все залы музея мы вышли на улицу."]},{"t":"Расставьте запятые. Обратите внимание на союзы рядом с оборотом.","key":"1) Он остановился и, прислушавшись, улыбнулся. 2) Собрав вещи и попрощавшись с хозяевами, гости уехали. 3) Стемнело, и, разведя костёр, мы стали готовить ужин. 4) Дети смеялись и, взявшись за руки, кружились.","items":["Он остановился и прислушавшись улыбнулся.","Собрав вещи и попрощавшись с хозяевами гости уехали.","Стемнело и разведя костёр мы стали готовить ужин.","Дети смеялись и взявшись за руки кружились."]},{"t":"Замените одно из сказуемых деепричастным оборотом и запишите предложение с запятыми.\n\n1) Мальчик открыл дверь и вошёл в комнату. 2) Девочка смотрела в окно и мечтала о лете.","key":"1) Открыв дверь, мальчик вошёл в комнату. 2) Глядя в окно, девочка мечтала о лете (или: Девочка смотрела в окно, мечтая о лете)."},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nОхотник долго шёл по следу (1) и (2) потеряв его у ручья (3) остановился (4) чтобы отдохнуть.","key":"2, 3, 4 (1 – не нужна: однородные сказуемые с союзом «и»; 4 – перед «чтобы»)"}],"test":[{"q":"Где правильно расставлены запятые?","o":["Прочитав письмо, она улыбнулась.","Прочитав, письмо она улыбнулась.","Прочитав письмо она, улыбнулась.","Прочитав письмо она улыбнулась."],"a":0,"e":"Оборот в начале – запятая после него.","tag":"Деепричастный оборот"},{"q":"Сколько запятых: «Ветер дул не переставая ни на минуту»?","a":"1|одна","e":"Ветер дул, не переставая ни на минуту.","tag":"Деепричастный оборот"},{"q":"Где запятая после «и» нужна?","o":["Он встал и выглянув в окно ахнул.","Он встал и ахнул."],"a":0,"e":"Он встал и, выглянув в окно, ахнул.","tag":"Деепричастный оборот"},{"q":"Как подчёркивается деепричастный оборот?","o":["штрихпунктиром","волнистой линией","пунктиром","двумя чертами"],"a":0,"e":"Это обстоятельство.","tag":"Деепричастный оборот"},{"q":"Нужна ли запятая между оборотами: «Сняв куртку и повесив её на крючок, он сел»?","o":["нет","да"],"a":0,"e":"Обороты соединены «и».","tag":"Деепричастный оборот"},{"q":"Найдите деепричастный оборот: «Кошка, свернувшись клубком, спала у печки».","a":"свернувшись клубком","e":"Что сделав? – свернувшись клубком.","tag":"Деепричастный оборот"}],"hwtest":[{"q":"Сколько запятых: «Сделав уроки мы пошли гулять»?","a":"1|одна","e":"Оборот в начале.","tag":"Деепричастный оборот"},{"q":"Где ошибка?","o":["Она пела, моя посуду.","Она пела моя, посуду."],"a":1,"e":"Оборот «моя посуду» нельзя разрывать.","tag":"Деепричастный оборот"},{"q":"Сколько запятых: «Мы шагали и напевая песню не замечали усталости»?","a":"2|две","e":"И, напевая песню, не замечали.","tag":"Деепричастный оборот"}],"hw":"Описать в 6–7 предложениях утро выходного дня, используя 4 деепричастных оборота в разных местах предложения (начало, середина, конец, после союза «и»). Подчеркнуть обороты. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Деепричастный оборот обособляется всегда; союз «и» остаётся вне запятых.","tips":["Находим глагол, к которому относится оборот.","Запятые с обеих сторон в середине.","«И» не входит в оборот."]},"memo":{"h":"Обстоятельство – штрихпунктир","t":"Деепричастный оборот рассказывает, КАК или ПОСЛЕ ЧЕГО выполнено главное действие. Выделяем всегда.","ex":["Слушая музыку, он рисовал.","Он рисовал, слушая музыку."]},"date":"2026-11-03"},{"id":"oge-ru-11","title":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»","block":"s1","oge":"Задание 3 · Обособленные члены","learn":["обособлять одиночные деепричастия","не обособлять деепричастия-наречия и фразеологизмы","обособлять обстоятельства с предлогом «несмотря на»"],"theory":[{"h":"Одиночное деепричастие","t":"Одиночное деепричастие обычно обособляется: оно обозначает добавочное действие.","list":["Улыбаясь, она кивнула. Он, подумав, согласился.","Не обособляется деепричастие, которое по смыслу стало наречием и отвечает на вопрос «как?»: читать лёжа, стоять молча, есть не торопясь, сидеть не шевелясь.","Проверка: можно ли заменить наречием? Шёл не спеша = шёл медленно – запятой нет."],"ex":["[[s:Он]] [[p:слушал]] [[a:молча]]. (как? – молча)","[[a:Помолчав]], [[s:он]] [[p:ответил]]."],"mini":[{"q":"Нужна ли запятая: «Мальчик читал лёжа»?","a":"нет"},{"q":"Нужна ли запятая: «Подумав мальчик ответил»?","a":"да"}]},{"h":"Фразеологизмы с деепричастиями","t":"Устойчивые выражения не обособляются: они значат одно понятие.","list":["бежать сломя голову (очень быстро)","работать спустя рукава (небрежно)","работать засучив рукава (усердно)","слушать затаив дыхание (очень внимательно)","сидеть сложа руки (бездельничать)","трудиться не покладая рук"],"ex":["Мы работали [[a:не покладая рук]]."],"mini":[{"q":"Нужна ли запятая: «Он нёсся сломя голову»?","a":"нет"}]},{"h":"Обстоятельства с предлогом «несмотря на»","t":"Обстоятельство уступки с предлогом «несмотря на» (и «невзирая на») обособляется всегда.","list":["Несмотря на дождь, мы отправились в поход.","Мы, несмотря на усталость, дошли до вершины.","Предлоги «благодаря», «согласно», «вопреки» короткие обстоятельства обычно не выделяют: Благодаря помощи друзей мы успели."],"mini":[{"q":"Нужна ли запятая: «Несмотря на мороз дети гуляли»?","a":"да"}]}],"practice":[{"t":"Расставьте запятые там, где они нужны.","key":"1) Отдохнув, мы продолжили путь. 2) Он ел не спеша (без запятых). 3) Задумавшись, она не услышала звонка. 4) Ребята слушали затаив дыхание (без запятых). 5) Несмотря на поздний час, в окнах горел свет.","items":["Отдохнув мы продолжили путь.","Он ел не спеша.","Задумавшись она не услышала звонка.","Ребята слушали затаив дыхание.","Несмотря на поздний час в окнах горел свет."]},{"t":"Подчеркните обстоятельства штрихпунктиром. Над теми, что не обособляются, подпишите «нар.» или «фраз.».","key":"1) стоя – нар. (без запятых); 2) запыхавшись – обособляется; 3) сломя голову – фраз.; 4) смеясь – обособляется","items":["Пассажиры ехали стоя.","Запыхавшись он вбежал в класс.","Щенок помчался сломя голову.","Смеясь она рассказывала о поездке."]},{"t":"Расставьте запятые.","key":"1) Несмотря на ветер, рыбаки вышли в море. 2) Мы, несмотря на опоздание, успели на поезд. 3) Благодаря подсказке мы нашли дорогу (без запятых). 4) Трудились они не покладая рук (без запятых).","items":["Несмотря на ветер рыбаки вышли в море.","Мы несмотря на опоздание успели на поезд.","Благодаря подсказке мы нашли дорогу.","Трудились они не покладая рук."]},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nНесмотря на холод (1) мы шли (2) не торопясь (3) и (4) оглядываясь (5) любовались зимним лесом.","key":"1, 4, 5 (не торопясь = медленно – без запятых)"}],"test":[{"q":"Где запятая НЕ нужна?","o":["Он говорил не умолкая.","Помолчав он заговорил.","Улыбнувшись она ушла.","Она ушла улыбнувшись друзьям."],"a":0,"e":"Не умолкая = беспрерывно, наречное значение.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Где фразеологизм?","o":["слушать затаив дыхание","слушать, затаив обиду","слушать, закрыв глаза"],"a":0,"e":"Затаив дыхание = очень внимательно.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Нужна ли запятая: «Несмотря на трудности команда победила»?","o":["да","нет"],"a":0,"e":"Предлог «несмотря на».","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Где запятая нужна?","o":["Оглянувшись он увидел собаку.","Он сидел не шевелясь.","Он работал спустя рукава."],"a":0,"e":"Одиночное деепричастие с добавочным действием.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Выпишите деепричастие-наречие: «Мы ехали молча, глядя в окно».","a":"молча","e":"Как ехали? – молча.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Сколько запятых: «Мы несмотря на дождь гуляли до вечера»?","a":"2|две","e":"Обстоятельство в середине.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"}],"hwtest":[{"q":"Где запятая не нужна?","o":["Он стоял не двигаясь.","Подумав он кивнул."],"a":0,"e":"Наречное значение.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Нужна ли запятая: «Несмотря на усталость он улыбался»?","o":["да","нет"],"a":0,"e":"Несмотря на.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"},{"q":"Где фразеологизм?","o":["сидеть сложа руки","сидеть, сложив руки на коленях"],"a":0,"e":"Бездельничать.","tag":"Одиночные деепричастия, фразеологизмы и обороты с «несмотря на»"}],"hw":"Составить 4 пары предложений: в одном деепричастие обособляется, в другом – наречное значение или фразеологизм (не спеша / не спеша с ответом). Составить 2 предложения с «несмотря на». Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Исключения из правила об обособлении деепричастий и обороты с «несмотря на».","tips":["Вопрос «как?» и замена наречием – без запятых.","Фразеологизмы учим списком.","«Несмотря на» – всегда запятые."]},"memo":{"h":"Наречие или деепричастие?","t":"Задай вопрос от глагола. «Как?» и легко заменить наречием – без запятых. «Что делая? что сделав?» – запятые.","ex":["Шёл (как?) не торопясь = медленно.","Не торопясь с ответом, он размышлял (что делая?)."]},"date":"2026-11-10"},{"id":"oge-ru-12","title":"Уточняющие члены предложения","block":"s1","oge":"Задание 3 · Обособленные члены","learn":["находить уточняющие обстоятельства места и времени","обособлять пояснительные члены с «то есть», «или», «а именно»","обособлять присоединительные члены с «особенно», «даже», «например»"],"theory":[{"h":"Уточняющие обстоятельства","t":"Уточняющий член сужает, конкретизирует значение предыдущего: сначала сказано шире, потом – точнее.","list":["Место: Внизу, у самой воды, сидели рыбаки.","Время: Завтра, в семь часов утра, мы отправимся в путь.","Проверка: можно вставить «а именно» или «где именно? когда именно?»."],"ex":["[[a:Внизу]], [[a:у самой воды]], сидели рыбаки."],"mini":[{"q":"«Вчера, поздно вечером, пошёл снег». Какое слово уточняется?","a":"вчера"}]},{"h":"Пояснительные члены","t":"Пояснительный член называет то же самое другими словами и присоединяется союзами «то есть», «или» (в значении «то есть»), «а именно».","list":["Он изучает орнитологию, то есть науку о птицах.","Мы увидели ель, или ёлку, у самого окна.","Запятая ставится перед союзом и после пояснительного члена, если предложение продолжается."],"mini":[{"q":"Ставится ли запятая после «то есть»?","a":"нет"}]},{"h":"Присоединительные члены","t":"Присоединительный член добавляет дополнительные сведения и вводится словами «особенно», «даже», «в том числе», «например», «в частности», «а также».","list":["Все, особенно малыши, радовались снегу.","Я люблю фрукты, например яблоки и груши.","После «например» запятая не ставится, если это не начало предложения с вводным словом."],"mini":[{"q":"Как выделить: «Многие особенно новички волновались»?","a":"многие, особенно новички, волновались"}]}],"practice":[{"t":"Расставьте запятые при уточняющих обстоятельствах.","key":"1) Внизу, под горой, шумела река. 2) Сегодня, в четыре часа дня, начнётся концерт. 3) Здесь, на опушке, мы и разбили лагерь. 4) Весной, в начале апреля, прилетели грачи.","items":["Внизу под горой шумела река.","Сегодня в четыре часа дня начнётся концерт.","Здесь на опушке мы и разбили лагерь.","Весной в начале апреля прилетели грачи."]},{"t":"Расставьте запятые при пояснительных и присоединительных членах.","key":"1) На берегу росла ива, или ракита. 2) Все, даже самые младшие, приняли участие в игре. 3) Мы посетили много городов, в том числе Суздаль и Владимир. 4) Он купил лупу, то есть увеличительное стекло.","items":["На берегу росла ива или ракита.","Все даже самые младшие приняли участие в игре.","Мы посетили много городов в том числе Суздаль и Владимир.","Он купил лупу то есть увеличительное стекло."]},{"t":"Маркером отметьте слово, которое уточняется, а уточняющий член подчеркните как обстоятельство.","key":"1) далеко – за лесом; 2) вечером – около восьми часов; 3) повсюду – на улицах и в парках","items":["Далеко за лесом поднимался дым.","Вечером около восьми часов пришёл отец.","Повсюду на улицах и в парках лежали листья."]},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nНаверху (1) на самой вершине (2) росла одинокая сосна (3) и многие туристы (4) особенно фотографы (5) поднимались туда на рассвете.","key":"1, 2, 3, 4, 5 (3 – между частями сложного предложения)"}],"test":[{"q":"Где есть уточняющее обстоятельство?","o":["Вчера, около полуночи, пошёл дождь.","Вчера пошёл дождь.","Дождь шёл весь день.","Около полуночи пошёл дождь."],"a":0,"e":"Около полуночи уточняет «вчера».","tag":"Уточняющие члены предложения"},{"q":"Где нужна запятая перед «или»?","o":["Это был бегемот или гиппопотам.","Возьми ручку или карандаш."],"a":0,"e":"Или = то есть (пояснение).","tag":"Уточняющие члены предложения"},{"q":"Сколько запятых: «Все особенно девочки любили эту песню»?","a":"2|две","e":"Все, особенно девочки, любили…","tag":"Уточняющие члены предложения"},{"q":"Ставится ли запятая после «например»: «Я люблю ягоды например малину»?","o":["нет","да"],"a":0,"e":"Запятая только перед «например».","tag":"Уточняющие члены предложения"},{"q":"Какое слово уточняется: «Там, за рекой, начинался лес»?","a":"там","e":"За рекой – где именно.","tag":"Уточняющие члены предложения"},{"q":"Где пунктуационная ошибка?","o":["Летом, в июле, мы ездили на дачу.","Летом в июле, мы ездили на дачу."],"a":1,"e":"Уточнение выделяется с двух сторон.","tag":"Уточняющие члены предложения"}],"hwtest":[{"q":"Сколько запятых: «Утром часов в семь зазвонил телефон»?","a":"2|две","e":"Утром, часов в семь, зазвонил…","tag":"Уточняющие члены предложения"},{"q":"Нужна ли запятая перед «то есть»?","o":["да","нет"],"a":0,"e":"Пояснительный член.","tag":"Уточняющие члены предложения"},{"q":"Где присоединительный член?","o":["Все, даже бабушка, пели.","Все пели песни."],"a":0,"e":"Даже бабушка.","tag":"Уточняющие члены предложения"}],"hw":"Составить 6 предложений: 2 – с уточняющими обстоятельствами места и времени, 2 – с пояснительными членами («то есть», «или»), 2 – с присоединительными («особенно», «в том числе»). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Уточнение, пояснение, присоединение: от общего к частному.","tips":["Вставляем «а именно» для проверки.","«Или» = «то есть» – запятая.","После «например» запятая не нужна."]},"memo":{"h":"Сначала шире – потом точнее","t":"Уточнение работает как увеличительное стекло: «там» → «у старого моста», «скоро» → «через неделю».","ex":["Там, у старого моста, нас ждали.","Летом, в июле, мы поедем на море."]},"date":"2026-11-17"},{"id":"oge-ru-13","title":"Вводные слова и предложения","block":"s2","oge":"Задание 3 · Вводные слова и обращения","learn":["узнавать вводные слова по значению","выделять вводные слова запятыми","не выделять слова, которые никогда не бывают вводными"],"theory":[{"h":"Что такое вводные слова","t":"Вводные слова выражают отношение говорящего к сказанному или показывают источник, порядок мыслей. Они не являются членами предложения, к ним нельзя задать вопрос, и их можно убрать без потери смысла.","list":["Выделяются запятыми с двух сторон (в начале и в конце предложения – с одной).","Вводное предложение тоже выделяется: Он, как мне кажется, прав."],"ex":["Погода, [[b:к счастью]], наладилась.","[[b:Во-первых]], нужно выучить правило."],"mini":[{"q":"Являются ли вводные слова членами предложения?","a":"нет"}]},{"h":"Значения вводных слов","table":[["Значение","Вводные слова"],["уверенность","конечно, безусловно, разумеется, несомненно"],["неуверенность, предположение","кажется, вероятно, может быть, наверное, видимо, по-видимому"],["чувства","к счастью, к сожалению, к удивлению, к радости"],["источник сообщения","по-моему, по мнению…, по словам…, говорят, по сообщению…"],["порядок мыслей, связь","во-первых, во-вторых, итак, следовательно, значит, наконец, кстати, например"],["оформление мысли","словом, одним словом, другими словами, так сказать"],["привлечение внимания","видишь ли, знаете, послушайте, представьте"]],"mini":[{"q":"К какой группе относится «к сожалению»?","a":"чувства|эмоции|чувства говорящего"},{"q":"К какой группе относится «по словам учёных»?","a":"источник|источник сообщения"}]},{"h":"Слова, которые никогда не бывают вводными","t":"Их не выделяем запятыми ни в каком положении.","list":["вдруг, ведь, вот, вряд ли, едва ли, даже, именно, якобы, будто, как будто, словно, почти, приблизительно, лишь, только, всего лишь"],"ex":["Он [[b:вряд ли]] придёт.","Это [[b:именно]] то, что нужно."],"mini":[{"q":"Нужна ли запятая: «Он вряд ли успеет»?","a":"нет"}]}],"practice":[{"t":"Маркером отметьте вводные слова.","key":"1) кажется; 2) к сожалению; 3) во-первых; 4) по мнению синоптиков; 5) вводных слов нет","items":["Дождь кажется кончился.","Мы к сожалению опоздали на поезд.","Во-первых нужно составить план.","Зима по мнению синоптиков будет снежной.","Он вдруг вспомнил о письме."]},{"t":"Расставьте запятые.","key":"1) Дождь, кажется, кончился. 2) Мы, к сожалению, опоздали на поезд. 3) Во-первых, нужно составить план. 4) Зима, по мнению синоптиков, будет снежной. 5) Без запятых.","items":["Дождь кажется кончился.","Мы к сожалению опоздали на поезд.","Во-первых нужно составить план.","Зима по мнению синоптиков будет снежной.","Он вдруг вспомнил о письме."]},{"t":"Над вводным словом подпишите его значение: уверенность, неуверенность, чувства, источник, порядок.","key":"1) уверенность; 2) источник; 3) чувства; 4) порядок мыслей; 5) неуверенность","items":["Ты конечно прав.","Говорят скоро откроют новый парк.","К удивлению всех он победил.","Итак мы закончили работу.","Видимо поезд задерживается."]},{"t":"Расставьте запятые там, где они нужны. В двух предложениях запятые не нужны.","key":"1) Он, наверное, забыл о встрече. 2) Ведь мы договаривались (без запятых). 3) Это, по-моему, лучший рассказ. 4) Она будто не слышала вопроса (без запятых).","items":["Он наверное забыл о встрече.","Ведь мы договаривались.","Это по-моему лучший рассказ.","Она будто не слышала вопроса."]},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nЗадача (1) безусловно (2) была сложной (3) но мы (4) к счастью (5) справились с ней вовремя.","key":"1, 2, 3, 4, 5"}],"test":[{"q":"Где вводное слово?","o":["Он, наверное, устал.","Он вдруг устал.","Он даже не устал.","Он почти не устал."],"a":0,"e":"Наверное – неуверенность.","tag":"Вводные слова и предложения"},{"q":"Какое слово никогда не бывает вводным?","o":["вряд ли","конечно","кажется","итак"],"a":0,"e":"Вряд ли – частица.","tag":"Вводные слова и предложения"},{"q":"Сколько запятых: «К счастью дождь скоро прошёл»?","a":"1|одна","e":"Вводное слово в начале.","tag":"Вводные слова и предложения"},{"q":"Значение «по словам бабушки»:","o":["источник сообщения","уверенность","порядок мыслей"],"a":0,"e":"Указывает, кто сообщил.","tag":"Вводные слова и предложения"},{"q":"Где пунктуационная ошибка?","o":["Он, якобы, был там.","Он, кажется, был там.","Он, говорят, был там."],"a":0,"e":"«Якобы» не бывает вводным.","tag":"Вводные слова и предложения"},{"q":"Выпишите вводное слово: «Словом, всё закончилось хорошо».","a":"словом","e":"Оформление мысли.","tag":"Вводные слова и предложения"}],"hwtest":[{"q":"Где вводное слово?","o":["Он, видимо, ушёл.","Он именно ушёл."],"a":0,"e":"Видимо – предположение.","tag":"Вводные слова и предложения"},{"q":"Нужна ли запятая: «Он едва ли согласится»?","o":["нет","да"],"a":0,"e":"Едва ли не бывает вводным.","tag":"Вводные слова и предложения"},{"q":"Сколько запятых: «Мы во-вторых обсудили бюджет»?","a":"2|две","e":"Мы, во-вторых, обсудили…","tag":"Вводные слова и предложения"}],"hw":"Составить по одному предложению с вводными словами каждого значения из таблицы (7 предложений) и 3 предложения со словами, которые не бывают вводными. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Значения вводных слов и список невводных слов.","tips":["Проверяем удалением.","Учим таблицу значений.","Список невводных слов – наизусть."]},"memo":{"h":"Проверка удалением","t":"Убери слово – если предложение осталось целым и смысл не изменился, слово вводное.","ex":["Он, конечно, придёт → Он придёт.","Мы, к счастью, успели → Мы успели."]},"date":"2026-11-24"},{"id":"oge-ru-14","title":"Вводное слово или член предложения","block":"s2","oge":"Задание 3 · Вводные слова и обращения","learn":["различать вводные слова и созвучные члены предложения","проверять слово вопросом и удалением"],"theory":[{"h":"Одно слово – две роли","t":"Многие вводные слова могут быть членами предложения. Тогда к ним можно задать вопрос, и без них предложение теряет смысл.","table":[["Вводное слово","Член предложения"],["[[b:Кажется]], будет гроза.","Он [[p:кажется]] усталым. (сказуемое)"],["[[b:Может быть]], он прав.","Он [[p:может быть]] полезен."],["[[b:Видно]], он устал.","С горы [[p:видно]] реку."],["[[b:Верно]], ты ошибся.","Ты [[a:верно]] решил задачу. (как? – правильно)"],["[[b:Наконец]], последнее замечание. (порядок)","Мы [[a:наконец]] пришли. (после долгого ожидания)"],["[[b:Во всяком случае]], я попробую.","–"]],"mini":[{"q":"«Он может быть полезен». Вводное ли «может быть»?","a":"нет"},{"q":"«Может быть, он придёт». Вводное ли «может быть»?","a":"да"}]},{"h":"Как проверить","list":["1. Задаём вопрос от другого слова. Есть вопрос – член предложения.","2. Удаляем слово. Смысл не изменился – вводное.","3. Заменяем синонимом: «наверное → вероятно» (вводное), «верно → правильно» (член предложения)."],"ex":["Он [[a:действительно]] хорошо поёт. (как? – на самом деле, член предложения)","[[b:Действительно]], он хорошо поёт. (вводное – подтверждение)"],"mini":[{"q":"«Он, наконец, ушёл»: запятые нужны, если «наконец» означает…","a":"порядок мыслей|итог перечисления|в конце перечисления"}]},{"h":"«Однако» и «итак»","list":["«Однако» в начале предложения в значении «но» – союз, запятая после не ставится: Однако дождь не прекращался.","«Однако» в середине предложения – вводное: Дождь, однако, не прекращался.","«Итак» – вводное, выделяется: Итак, решение принято."],"mini":[{"q":"Нужна ли запятая после «однако»: «Однако он не пришёл»?","a":"нет"}]}],"practice":[{"t":"Расставьте запятые там, где слово вводное.","key":"1) Отсюда видно всю долину (без запятых). 2) Видно, мы заблудились. 3) Он кажется спокойным (без запятых). 4) Кажется, начинается дождь. 5) Ты верно ответил (без запятых).","items":["Отсюда видно всю долину.","Видно мы заблудились.","Он кажется спокойным.","Кажется начинается дождь.","Ты верно ответил."]},{"t":"Подчеркните выделенные слова как члены предложения или отметьте маркером, если они вводные.","key":"1) может быть – член предложения (сказуемое: может быть опасным); 2) может быть – вводное; 3) наконец – член предложения (обстоятельство); 4) наконец – вводное (порядок)","items":["Шторм может быть опасным.","Может быть шторм утихнет к ночи.","Мы наконец добрались до дома.","Наконец нужно сказать и о расходах."]},{"t":"Расставьте запятые.","key":"1) Однако холод не отступал (без запятых). 2) Холод, однако, не отступал. 3) Итак, пора подвести итоги. 4) Он, во всяком случае, обещал помочь.","items":["Однако холод не отступал.","Холод однако не отступал.","Итак пора подвести итоги.","Он во всяком случае обещал помочь."]},{"t":"Составьте пары предложений, где одно и то же слово (кажется, видно, правда) в первом – вводное, во втором – член предложения. Запишите в поле.","key":"Например: Правда, я не сразу понял. – Он сказал правду / Правда всегда побеждает (подлежащее). Кажется, пора. – Дом кажется большим. Видно, устал. – Из окна видно море."},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nС холма (1) видно (2) всю деревню (3) и (4) видно (5) отсюда не раз любовались закатом местные художники.","key":"3, 4, 5 (1, 2 – «видно» сказуемое; второе «видно» – вводное)"}],"test":[{"q":"Где «кажется» – вводное?","o":["Кажется, он прав.","Он кажется уставшим.","Мне кажется странным его поведение."],"a":0,"e":"Можно убрать без потери смысла.","tag":"Вводное слово или член предложения"},{"q":"Где «верно» – член предложения?","o":["Он верно понял задание.","Верно, он забыл."],"a":0,"e":"Понял как? – правильно.","tag":"Вводное слово или член предложения"},{"q":"Где нужна запятая после «однако»?","o":["Он, однако, не пришёл.","Однако он не пришёл."],"a":0,"e":"В середине предложения – вводное.","tag":"Вводное слово или член предложения"},{"q":"Сколько запятых: «Ты может быть знаешь ответ»?","a":"2|две","e":"Ты, может быть, знаешь ответ.","tag":"Вводное слово или член предложения"},{"q":"Где «наконец» – вводное?","o":["И, наконец, последнее правило.","Поезд наконец пришёл."],"a":0,"e":"Порядок изложения.","tag":"Вводное слово или член предложения"},{"q":"Где «видно» – сказуемое?","o":["Звёзд не видно.","Видно, ты спешил."],"a":0,"e":"Не видно (чего?) звёзд.","tag":"Вводное слово или член предложения"}],"hwtest":[{"q":"Где вводное слово?","o":["Может быть, завтра потеплеет.","Завтра может быть тепло."],"a":0,"e":"Можно убрать.","tag":"Вводное слово или член предложения"},{"q":"Нужна ли запятая: «Однако мы успели»?","o":["нет","да"],"a":0,"e":"Союз в начале предложения.","tag":"Вводное слово или член предложения"},{"q":"Где «правда» – вводное?","o":["Он, правда, опоздал.","Он сказал правду."],"a":0,"e":"Правда = действительно, признавая.","tag":"Вводное слово или член предложения"}],"hw":"Составить 5 пар предложений со словами: кажется, может быть, видно, верно, наконец (вводное / член предложения). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Различение вводных слов и членов предложения.","tips":["Вопрос к слову.","Удаление без потери смысла.","«Однако» в начале – союз."]},"memo":{"h":"Вопрос – решает","t":"Если к слову можно задать вопрос (как? каков? что делать?), это член предложения. Вводные слова вопросу не подчиняются.","ex":["Видно (что?) далеко – член предложения.","Видно, устал – вводное."]},"date":"2026-12-01"},{"id":"oge-ru-15","title":"Обращение","block":"s2","oge":"Задание 3 · Вводные слова и обращения","learn":["находить обращение","выделять обращение знаками","отличать обращение от подлежащего"],"theory":[{"h":"Что такое обращение","t":"Обращение называет того, к кому обращаются с речью. Оно не является членом предложения и выделяется запятыми или восклицательным знаком.","list":["В начале: Мама, ты дома? / Мама! Иди сюда.","В середине: Скажи, Петя, где ты был?","В конце: Спасибо за помощь, друзья.","Обращение может быть распространённым: Дорогие мои друзья, спасибо!"],"ex":["[[b:Дорогой друг]], пиши чаще.","Послушай, [[b:бабушка]], какая песня!"],"mini":[{"q":"Является ли обращение членом предложения?","a":"нет"}]},{"h":"Обращение или подлежащее","t":"Подлежащее связано со сказуемым, обращение – нет. Часто в предложении с обращением есть своё подлежащее – местоимение «ты» или «вы».","list":["Мама пришла. – подлежащее.","Мама, ты пришла? – обращение, подлежащее «ты».","Сказуемое в повелительном наклонении – признак обращения: Петя, закрой окно."],"ex":["[[b:Ребята]], [[s:вы]] [[p:готовы]]?","[[s:Ребята]] [[p:готовы]]."],"mini":[{"q":"«Ученики, откройте тетради». Обращение или подлежащее «ученики»?","a":"обращение"}]},{"h":"Особые случаи","list":["Частица «о» перед обращением запятой не отделяется: О море, как ты прекрасно!","Междометие «эй» отделяется: Эй, Ваня, подожди!","Части распространённого обращения могут быть разорваны: Дорогой, скажи, мой друг, ..."],"mini":[{"q":"Нужна ли запятая после «о»: «О весна без конца и без краю…»?","a":"нет"}]}],"practice":[{"t":"Отметьте обращения маркером и расставьте знаки препинания.","key":"1) Ребята, пора на урок! 2) Скажи мне, мудрый ворон, что ждёт нас впереди? 3) Спасибо тебе, дорогая бабушка. 4) О Волга, колыбель моя! 5) Дети пели (обращения нет).","items":["Ребята пора на урок!","Скажи мне мудрый ворон что ждёт нас впереди?","Спасибо тебе дорогая бабушка.","О Волга колыбель моя!","Дети пели."]},{"t":"Подчеркните грамматическую основу. Обращение не подчёркивайте – отметьте его маркером.","key":"1) обращение «Анна»; основа: ты знаешь; 2) основа: Анна знает; 3) обращение «друзья»; основа: (вы) помогите – односоставное определённо-личное","items":["Анна ты знаешь ответ?","Анна знает ответ.","Друзья помогите нам!"]},{"t":"Расставьте запятые.","key":"1) Эй, ямщик, не гони лошадей! 2) Расскажите, Иван Петрович, о своём путешествии. 3) Ты, Маша, лучше всех рисуешь. 4) Милый мой сынок, береги себя.","items":["Эй ямщик не гони лошадей!","Расскажите Иван Петрович о своём путешествии.","Ты Маша лучше всех рисуешь.","Милый мой сынок береги себя."]},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nПослушай (1) Серёжа (2) мы с ребятами (3) завтра (4) идём в поход.","key":"1, 2"}],"test":[{"q":"Где есть обращение?","o":["Коля, ты придёшь?","Коля придёт.","Я позвал Колю.","Коля и Петя пришли."],"a":0,"e":"Обращаются к Коле.","tag":"Обращение"},{"q":"Сколько запятых: «Скажите пожалуйста Анна Ивановна который час»?","a":"3|три","e":"Скажите, пожалуйста, Анна Ивановна, который час?","tag":"Обращение"},{"q":"Где «друзья» – подлежащее?","o":["Друзья пришли вовремя.","Друзья, приходите вовремя."],"a":0,"e":"Связано со сказуемым «пришли».","tag":"Обращение"},{"q":"Нужна ли запятая после «о»: «О поле поле кто тебя усеял»?","o":["нет, только после первого «поле»","да, после «о»"],"a":0,"e":"О поле, поле, кто тебя усеял…","tag":"Обращение"},{"q":"Является ли обращение членом предложения?","o":["нет","да"],"a":0,"e":"Не связано с членами предложения.","tag":"Обращение"},{"q":"Выпишите обращение: «Прощай, свободная стихия!»","a":"свободная стихия","e":"Распространённое обращение.","tag":"Обращение"}],"hwtest":[{"q":"Где обращение?","o":["Сестра, помоги!","Сестра помогла."],"a":0,"e":"Обращение к сестре.","tag":"Обращение"},{"q":"Сколько запятых: «Ты Петя молодец»?","a":"2|две","e":"Ты, Петя, молодец.","tag":"Обращение"},{"q":"Выпишите обращение: «Здравствуй, племя младое, незнакомое!»","a":"племя младое, незнакомое|племя младое незнакомое","e":"Распространённое обращение.","tag":"Обращение"}],"hw":"Написать короткое письмо другу (5–6 предложений), используя 4 обращения в разных местах предложения, одно – распространённое. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Обращение: знаки и отличие от подлежащего.","tips":["Обращение – не член предложения.","«О» не отделяем, «эй» – отделяем.","Повелительное наклонение подсказывает обращение."]},"memo":{"h":"Найди, к кому обращаются","t":"Если слово называет собеседника и к нему нельзя задать вопрос от сказуемого – это обращение, выделяем.","ex":["Ваня, ты читал? – обращение.","Ваня читал. – подлежащее."]},"date":"2026-12-08"},{"id":"oge-ru-16","title":"Вставные конструкции","block":"s2","oge":"Задание 3 · Вводные слова и обращения","learn":["находить вставные конструкции","выделять их скобками или тире","отличать вставные конструкции от вводных слов"],"theory":[{"h":"Что такое вставная конструкция","t":"Вставная конструкция сообщает дополнительные сведения, попутные замечания, пояснения. Она резко выбивается из предложения по смыслу и интонации.","list":["Выделяется скобками: Однажды (это было осенью) мы заблудились в лесу.","Или тире: Однажды – это было осенью – мы заблудились в лесу.","Чаще всего вставная конструкция – целое предложение."],"mini":[{"q":"Какими знаками выделяются вставные конструкции?","a":"скобками или тире|скобки или тире|скобками|тире"}]},{"h":"Вставная конструкция или вводное слово","list":["Вводное слово выражает отношение говорящего (конечно, к счастью) и выделяется запятыми.","Вставная конструкция добавляет новую информацию (дату, пояснение, комментарий) и выделяется скобками или тире.","Знаки внутри скобок ставятся по смыслу вставки: Вчера (как жаль!) мы не успели."],"ex":["Он, [[b:конечно]], согласился. – вводное","Он ([[b:я узнал об этом позже]]) согласился. – вставное"],"mini":[{"q":"«Летом (мне было тогда десять лет) мы переехали». Вставная конструкция или вводное?","a":"вставная|вставная конструкция"}]}],"practice":[{"t":"Отметьте маркером вставные конструкции.","key":"1) это было в июле; 2) нас было пятеро; 3) так звали нашего пса","items":["Однажды (это было в июле) мы ушли в горы.","Вечером – нас было пятеро – мы сели у костра.","Барбос (так звали нашего пса) встречал нас у ворот."]},{"t":"Определите, вставная это конструкция или вводное слово. Запишите в поле.\n\n1) Он, по-моему, прав. 2) Брат (он старше меня на пять лет) учится в институте. 3) К счастью, мы успели.","key":"1) вводное; 2) вставная конструкция; 3) вводное"},{"t":"Перепишите в поле, выделяя вставную конструкцию скобками.\n\nВ тот день мы это я хорошо помню впервые увидели море.","key":"В тот день (это я хорошо помню) мы впервые увидели море."},{"t":"Составьте два предложения со вставными конструкциями: одно со скобками, другое с тире. Запишите в поле.","key":"Например: Мой дедушка (он был лётчиком) много рассказывал о небе. Утром – было ещё темно – мы вышли из дома."}],"test":[{"q":"Где вставная конструкция?","o":["Летом (мне было семь лет) я научился плавать.","Летом, к счастью, я научился плавать.","Летом я научился плавать."],"a":0,"e":"Дополнительная справка в скобках.","tag":"Вставные конструкции"},{"q":"Какой знак может выделять вставную конструкцию?","o":["тире","двоеточие","точка с запятой"],"a":0,"e":"Скобки или тире.","tag":"Вставные конструкции"},{"q":"Какие знаки ставятся при вводных словах?","o":["запятые","скобки","кавычки"],"a":0,"e":"Вводные слова – запятыми.","tag":"Вставные конструкции"},{"q":"Выпишите вставную конструкцию: «Мой брат (он врач) работает ночью».","a":"он врач","e":"Пояснение в скобках.","tag":"Вставные конструкции"},{"q":"Можно ли поставить восклицательный знак внутри скобок?","o":["да, если вставка восклицательная","нет, никогда"],"a":0,"e":"Знаки внутри вставки – по её смыслу.","tag":"Вставные конструкции"}],"hwtest":[{"q":"Где вставная конструкция?","o":["Город (его основали в XII веке) красив.","Город, говорят, красив."],"a":0,"e":"Справка в скобках.","tag":"Вставные конструкции"},{"q":"Чем выделяют вставные конструкции?","o":["скобками или тире","только запятыми"],"a":0,"e":"Скобки или тире.","tag":"Вставные конструкции"},{"q":"«По-моему» – это…","o":["вводное слово","вставная конструкция"],"a":0,"e":"Источник мнения.","tag":"Вставные конструкции"}],"hw":"Написать 5 предложений о своей семье со вставными конструкциями (справки о возрасте, профессии, датах): 3 – со скобками, 2 – с тире. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Вставная конструкция – дополнительная информация в скобках или между тире.","tips":["Вставка = новая информация.","Вводное слово = отношение говорящего.","Внутри скобок – свои знаки."]},"memo":{"h":"Вставка – это «шёпот в сторону»","t":"Если часть предложения звучит как замечание вполголоса или справка, её берём в скобки.","ex":["Пушкин (это знает каждый) родился в Москве.","Мы приехали в Суздаль – город поразил нас – в начале мая."]},"date":"2026-12-15"},{"id":"oge-ru-17","title":"Сложносочинённое предложение","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["находить границы частей ССП","ставить запятую перед сочинительным союзом","видеть случаи, когда запятая не нужна"],"theory":[{"h":"Строение ССП","t":"Сложносочинённое предложение состоит из равноправных частей, которые соединены сочинительными союзами.","list":["Соединительные: и, да (= и), ни… ни, тоже, также.","Противительные: а, но, да (= но), однако, зато.","Разделительные: или, либо, то… то, не то… не то.","Каждую часть находим по грамматической основе."],"ex":["[[s:Солнце]] [[p:село]], и [[s:небо]] [[p:потемнело]].","[[s:Я]] [[p:звонил]], но [[s:никто]] не [[p:ответил]]."],"scheme":"[ ], и [ ].    [ ], но [ ].    То [ ], то [ ].","mini":[{"q":"Сколько грамматических основ: «Ветер стих, и пошёл снег»?","a":"2|две"}]},{"h":"Когда запятая перед «и» не нужна","t":"Запятая не ставится, если у частей есть общий второстепенный член или общее вводное слово.","list":["Общее обстоятельство: [[a:Вечером]] стих ветер и пошёл снег.","Общее вводное слово: [[b:К счастью]], дождь кончился и выглянуло солнце.","Две части – вопросительные, восклицательные или назывные: Кто ты и откуда ты? Как тихо и как светло!","Части – безличные предложения с синонимичными словами: Стало темно и холодно – здесь однородные сказуемые."],"mini":[{"q":"Нужна ли запятая: «Утром выпал снег и стало светло»?","a":"нет"},{"q":"Нужна ли запятая: «Выпал снег и стало светло»?","a":"да"}]},{"h":"ССП или простое с однородными сказуемыми","t":"Главная ошибка: поставить запятую между однородными сказуемыми.","list":["«Мальчик вошёл и сел» – одно подлежащее, два сказуемых: запятой нет.","«Мальчик вошёл, и все замолчали» – два подлежащих: запятая есть."],"ex":["[[s:Мальчик]] [[p:вошёл]] и [[p:сел]].","[[s:Мальчик]] [[p:вошёл]], и [[s:все]] [[p:замолчали]]."],"mini":[{"q":"Сколько основ: «Сестра вымыла посуду и вытерла стол»?","a":"1|одна"}]}],"practice":[{"t":"Подчеркните грамматические основы и расставьте запятые.","key":"1) Наступила осень, и птицы улетели на юг. 2) Брат читал, а сестра рисовала. 3) Он открыл окно и выглянул во двор (без запятой – однородные сказуемые). 4) То дождь шёл, то снег падал.","items":["Наступила осень и птицы улетели на юг.","Брат читал а сестра рисовала.","Он открыл окно и выглянул во двор.","То дождь шёл то снег падал."]},{"t":"Расставьте запятые. Объясните в поле, почему в двух предложениях запятой перед «и» нет.","key":"1) Вдали показался лес, и дорога пошла под гору. 2) Летом рано светает и поздно темнеет (общее обстоятельство «летом»). 3) Наверное, гроза прошла и небо прояснилось (общее вводное слово). 4) Ударил гром, и хлынул ливень.","items":["Вдали показался лес и дорога пошла под гору.","Летом рано светает и поздно темнеет.","Наверное гроза прошла и небо прояснилось.","Ударил гром и хлынул ливень."]},{"t":"Над союзом подпишите его разряд: соед., против., раздел.","key":"1) соед.; 2) против.; 3) раздел.; 4) против. (зато)","items":["Светило солнце и пели птицы.","Я спешил но опоздал.","Либо ты придёшь либо я приеду к тебе.","Дорога была длинной зато интересной."]},{"t":"Начертите схемы предложений в поле.\n\n1) Прошла неделя, и мы получили письмо. 2) Ветер то стихал, то усиливался. 3) Мама пекла пироги, а папа накрывал на стол.","key":"1) [ ], и [ ]. 2) простое с однородными сказуемыми: [П то ⩸, то ⩸]. 3) [ ], а [ ]."},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nНа рассвете (1) туман рассеялся (2) и над озером (3) показалось солнце (4) но вода оставалась холодной.","key":"4 (между «туман рассеялся» и «показалось солнце» – общее обстоятельство «на рассвете»)"}],"test":[{"q":"Где нужна запятая перед «и»?","o":["Пошёл дождь и подул ветер.","Вечером пошёл дождь и подул ветер.","Он встал и вышел.","Мы пели и танцевали."],"a":0,"e":"Две основы, общего члена нет.","tag":"Сложносочинённое предложение"},{"q":"Сколько основ: «Сверкнула молния и загремел гром»?","a":"2|две","e":"Молния сверкнула, гром загремел.","tag":"Сложносочинённое предложение"},{"q":"Какой союз противительный?","o":["зато","или","и","то… то"],"a":0,"e":"Зато – противопоставление.","tag":"Сложносочинённое предложение"},{"q":"Где пунктуационная ошибка?","o":["Он позвонил, и сказал.","Он позвонил, и я ответил.","Он позвонил и сказал."],"a":0,"e":"Однородные сказуемые – без запятой.","tag":"Сложносочинённое предложение"},{"q":"Нужна ли запятая: «В саду цвели яблони и пели соловьи»?","o":["нет","да"],"a":0,"e":"Общее обстоятельство «в саду».","tag":"Сложносочинённое предложение"},{"q":"Схема «[ ], но [ ]» соответствует предложению…","o":["Я ждал, но он не пришёл.","Я ждал его, но не дождался.","Я ждал и надеялся."],"a":0,"e":"Две основы: я ждал, он не пришёл.","tag":"Сложносочинённое предложение"}],"hwtest":[{"q":"Где нужна запятая?","o":["Стемнело и зажглись фонари.","Мы погуляли и вернулись."],"a":0,"e":"Две основы.","tag":"Сложносочинённое предложение"},{"q":"Где запятая перед «и» не нужна?","o":["Зимой дни короткие и ночи длинные.","Дни стали короче и ночи длиннее, а мы всё гуляли."],"a":0,"e":"Общее обстоятельство «зимой».","tag":"Сложносочинённое предложение"},{"q":"Сколько основ: «Дул ветер, но было тепло»?","a":"2|две","e":"Ветер дул; было тепло.","tag":"Сложносочинённое предложение"}],"hw":"Выписать из любого рассказа А. П. Чехова 5 ССП с разными союзами и 2 простых предложения с однородными сказуемыми. Подчеркнуть основы, начертить схемы. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"ССП: две основы и сочинительный союз; общий второстепенный член снимает запятую.","tips":["Подчёркиваем основы прежде всего.","Общий член или вводное слово – без запятой.","Однородные сказуемые – не ССП."]},"memo":{"h":"Сначала основы","t":"Подчеркни все грамматические основы. Две основы и союз между ними – запятая перед союзом. Одна основа с двумя сказуемыми – без запятой.","ex":["[ ], и [ ].","[П ⩸ и ⩸]."]},"date":"2026-12-22"},{"id":"oge-ru-18","title":"Сложноподчинённое предложение: строение и средства связи","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["находить главную и придаточную части","отличать союзы от союзных слов","ставить запятые на границах придаточного"],"theory":[{"h":"Главная и придаточная части","t":"В СПП одна часть (придаточная) зависит от другой (главной) и отвечает на вопрос от неё. Придаточная присоединяется подчинительным союзом или союзным словом.","list":["Главную часть обозначаем квадратными скобками, придаточную – круглыми.","Придаточная может стоять после главной, перед ней или внутри неё.","Запятыми отделяем придаточную со всех сторон."],"ex":["[Я знал], (что ты придёшь).","(Когда стемнело), [мы вернулись].","[Дом, (который построил дед), стоит до сих пор]."],"scheme":"[ ], (что …).   (Когда …), [ ].   [ …, (который …), … ].","mini":[{"q":"Как обозначается придаточная часть в схеме?","a":"круглыми скобками|круглые скобки"}]},{"h":"Союз или союзное слово","t":"Союзы (что, чтобы, когда, если, потому что, хотя, как будто) только связывают части. Союзные слова (который, какой, чей, кто, что, где, куда, откуда, когда, почему) ещё и являются членом предложения в придаточной части.","list":["Проверка 1: союзное слово можно заменить словом из главной части: «Я знаю, что (= какую вещь) он купил» – союзное слово.","Проверка 2: на союзное слово падает логическое ударение, союз безударный.","«Я знаю, что он купил хлеб» – союз (что = «а именно»), нельзя задать вопрос."],"ex":["Я вижу, [[b:что]] ты устал. – союз","Я вижу, [[o:что]] ты нарисовал. – союзное слово (дополнение)"],"mini":[{"q":"«Город, где я родился, стоит на Волге». «Где» – союз или союзное слово?","a":"союзное слово"}]},{"h":"Ловушки на границах","list":["Составной союз «потому что», «так как», «для того чтобы» может разделяться: Мы опоздали потому, что сломался автобус (если выделяем причину).","Если перед подчинительным союзом стоит «и» после другой части – смотрим на структуру: Он сказал, что придёт и что принесёт книгу.","Придаточное в середине главного выделяется с двух сторон."],"mini":[{"q":"Сколько запятых: «Книга которую ты подарил лежит на столе»?","a":"2|две"}]}],"practice":[{"t":"Подчеркните грамматические основы и расставьте запятые.","key":"1) Мы поняли, что заблудились. 2) Когда солнце село, стало прохладно. 3) Деревня, в которой жила бабушка, стояла у реки. 4) Я не знаю, где он живёт.","items":["Мы поняли что заблудились.","Когда солнце село стало прохладно.","Деревня в которой жила бабушка стояла у реки.","Я не знаю где он живёт."]},{"t":"Над словом, присоединяющим придаточное, подпишите: «союз» или «с. сл.».","key":"1) союз; 2) с. сл. (что = какую вещь, дополнение); 3) с. сл. (который – подлежащее); 4) союз","items":["Учитель сказал что контрольная будет завтра.","Расскажи что ты видел.","Я встретил друга который приехал из Москвы.","Если завтра будет тепло мы поедем на дачу."]},{"t":"Начертите схемы СПП в поле.\n\n1) Когда наступило утро, мы отправились в путь. 2) Река, которая протекает через город, замерзает в ноябре. 3) Мы ждали, пока утихнет буря.","key":"1) (Когда …), [ ]. 2) [ …, (которая …), … ]. 3) [ ], (пока …)."},{"t":"Задание в формате ОГЭ (2). Найдите сложноподчинённое предложение и выпишите его номер.\n\n1) Ветер стих, и выглянуло солнце. 2) Когда ветер стих, выглянуло солнце. 3) Ветер стих; выглянуло солнце.","key":"2"},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nСтарый парк (1) где мы гуляли в детстве (2) теперь стал заповедником (3) и (4) когда я приезжаю домой (5) я обязательно прихожу туда.","key":"1, 2, 3, 4, 5 (4 – стык союзов «и» и «когда»: после придаточного нет «то»)"}],"test":[{"q":"Где союзное слово?","o":["Я знаю, кто это сделал.","Я знаю, что он прав.","Я ушёл, потому что устал."],"a":0,"e":"Кто – подлежащее в придаточной.","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Схема «(Если …), [ ].» соответствует:","o":["Если пойдёт снег, мы слепим снеговика.","Мы слепим снеговика, если пойдёт снег."],"a":0,"e":"Придаточное впереди.","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Сколько запятых: «Мальчик который сидел у окна читал книгу»?","a":"2|две","e":"Придаточное внутри главной.","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Какое слово – союз?","o":["чтобы","который","чей","где"],"a":0,"e":"Чтобы не бывает членом предложения.","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Где СПП?","o":["Я пришёл, когда все ушли.","Я пришёл, а все ушли.","Я пришёл и сел."],"a":0,"e":"Подчинительная связь «когда».","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Какую часть обозначают квадратными скобками?","o":["главную","придаточную"],"a":0,"e":"Главная – [ ].","tag":"Сложноподчинённое предложение: строение и средства связи"}],"hwtest":[{"q":"Где союзное слово?","o":["Дом, где я жил, снесли.","Я рад, что ты пришёл."],"a":0,"e":"Где = в котором.","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Сколько запятых: «Когда мы вышли шёл снег»?","a":"1|одна","e":"Когда мы вышли, шёл снег.","tag":"Сложноподчинённое предложение: строение и средства связи"},{"q":"Схема «[ ], (что …).»:","o":["Я думаю, что он прав.","Что он прав, я не сомневаюсь."],"a":0,"e":"Главная впереди.","tag":"Сложноподчинённое предложение: строение и средства связи"}],"hw":"Составить 6 СПП со средствами связи: что (союз), что (союзное слово), когда, который, если, потому что. Начертить схемы. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Главная и придаточная части; союз и союзное слово.","tips":["Вопрос от главной части.","Союзное слово – член предложения.","Придаточное в середине – две запятые."]},"memo":{"h":"Вопрос от главной к придаточной","t":"От главной части ставим вопрос: [Мы ушли] (когда?) – (когда кончился дождь). Где вопрос задать нельзя, там главная.","ex":["[Я верю], (что всё получится).","(Если пойдёт дождь), [мы останемся дома]."]},"date":"2026-12-29"},{"id":"oge-ru-19","title":"Придаточные определительные","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["находить придаточные определительные","ставить запятые при «который», «какой», «где», «куда», «откуда», «когда» в определительном значении"],"theory":[{"h":"Значение и вопросы","t":"Придаточное определительное поясняет существительное (или местоимение) в главной части и отвечает на вопрос «какой?».","list":["Средства связи – союзные слова который, какой, чей, где, куда, откуда, когда, что (= который).","Придаточное стоит сразу после определяемого слова.","От существительного ставим вопрос: дом (какой?) в котором я вырос."],"ex":["Я вспоминаю [[x:дом]], (в котором я вырос).","Наступил [[x:день]], (когда мы уезжали)."],"mini":[{"q":"На какой вопрос отвечает придаточное определительное?","a":"какой?|какой"}]},{"h":"«Где», «когда» – не всегда обстоятельство","t":"Если «где», «куда», «когда» стоят после существительного и их можно заменить на «который» – придаточное определительное.","list":["Город, где я родился (= в котором) – определительное.","Я пошёл туда, где был свет – это другое придаточное (места).","Местоименно-определительное: относится к местоимению «тот», «такой», «всякий»: Тот, кто ищет, всегда найдёт."],"mini":[{"q":"«Я помню вечер, когда мы встретились». Вид придаточного?","a":"определительное"}]}],"practice":[{"t":"Поставьте крестик над словом, которое поясняет придаточное, и расставьте запятые.","key":"1) Мы вышли на поляну, где росли ромашки. 2) Письмо, которое я ждал, пришло только вечером. 3) Наступило утро, когда всё вокруг ожило. 4) Я перечитал книгу, автор которой мне незнаком.","items":["Мы вышли на поляну где росли ромашки.","Письмо которое я ждал пришло только вечером.","Наступило утро когда всё вокруг ожило.","Я перечитал книгу автор которой мне незнаком."]},{"t":"Определите, определительное это придаточное или нет. Запишите в поле.\n\n1) Я знаю место, где растут грибы. 2) Я знаю, где растут грибы. 3) Мы пошли туда, где растут грибы.","key":"1) определительное (место какое?); 2) изъяснительное (знаю что?); 3) придаточное места (пошли куда?)"},{"t":"Соедините простые предложения в СПП с придаточным определительным и запишите.\n\n1) Мы прошли мимо озера. В озере водятся щуки. 2) Я встретил одноклассника. Отец одноклассника работает врачом.","key":"1) Мы прошли мимо озера, в котором водятся щуки. 2) Я встретил одноклассника, отец которого работает врачом."},{"t":"Задание в формате ОГЭ (2). Выпишите номер предложения с придаточным определительным.\n\n1) Когда пришла весна, растаял снег. 2) Весна, которую мы так ждали, пришла неожиданно. 3) Мы знали, что весна скоро придёт.","key":"2"}],"test":[{"q":"Где придаточное определительное?","o":["Я видел дом, где жил поэт.","Я знаю, где жил поэт.","Я пошёл, куда указали."],"a":0,"e":"Дом (какой?) где жил поэт.","tag":"Придаточные определительные"},{"q":"Какое слово НЕ присоединяет определительное придаточное?","o":["потому что","который","чей","какой"],"a":0,"e":"Потому что – союз причины.","tag":"Придаточные определительные"},{"q":"Сколько запятых: «Дерево которое посадил дед уже выше крыши»?","a":"2|две","e":"Придаточное внутри главной.","tag":"Придаточные определительные"},{"q":"«Тот, кто рано встаёт, много успевает». Вид придаточного?","o":["местоименно-определительное","изъяснительное","условия"],"a":0,"e":"Относится к местоимению «тот».","tag":"Придаточные определительные"},{"q":"Где придаточное отвечает на вопрос «какой?»?","o":["Это книга, которую я люблю.","Я люблю, когда читают вслух."],"a":0,"e":"Книга какая?","tag":"Придаточные определительные"}],"hwtest":[{"q":"Где определительное придаточное?","o":["Наступил час, когда все уснули.","Когда все уснули, я вышел."],"a":0,"e":"Час какой?","tag":"Придаточные определительные"},{"q":"Сколько запятых: «Река куда мы ходили купаться обмелела»?","a":"2|две","e":"Придаточное в середине.","tag":"Придаточные определительные"},{"q":"Можно ли «где» заменить на «в котором» в предложении «Это школа, где я учусь»?","o":["да","нет"],"a":0,"e":"Значит, придаточное определительное.","tag":"Придаточные определительные"}],"hw":"Описать свою улицу в 6 предложениях с придаточными определительными (который, где, куда, когда, чей). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Придаточное определительное: вопрос «какой?» и замена на «который».","tips":["Придаточное стоит после определяемого слова.","«Где» и «когда» после существительного – определительное.","Крестик над поясняемым словом."]},"memo":{"h":"Заменяй на «который»","t":"Если союзное слово легко заменить словом «который» в нужном падеже – придаточное определительное.","ex":["Озеро, где мы купались = озеро, в котором мы купались.","Время, когда цветут сады = время, в которое цветут сады."]},"date":"2027-01-05"},{"id":"oge-ru-20","title":"Придаточные изъяснительные","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["находить придаточные изъяснительные","различать «что» – союз и «что» – союзное слово в изъяснительных придаточных"],"theory":[{"h":"Значение и вопросы","t":"Придаточное изъяснительное отвечает на вопросы косвенных падежей (что? о чём? чего?) и зависит от глаголов речи, мысли, чувства, восприятия: сказать, знать, думать, видеть, слышать, радоваться, бояться.","list":["Средства связи: союзы что, чтобы, будто, как будто, ли, как; союзные слова кто, что, какой, где, куда, когда, почему, зачем.","«Ли» стоит после первого слова придаточного: Я не знаю, придёт ли он."],"ex":["Я [[b:слышал]] (что?), (что ты переезжаешь).","Мама [[b:спросила]], (вернусь ли я к ужину)."],"mini":[{"q":"На какие вопросы отвечает придаточное изъяснительное?","a":"вопросы косвенных падежей|что? о чём?|падежные вопросы"}]},{"h":"Изъяснительное или определительное","t":"Если придаточное зависит от глагола (или слова со значением речи и мысли) и отвечает на падежный вопрос – изъяснительное. Если от существительного и на вопрос «какой?» – определительное.","list":["Он сообщил (что?), что приедет. – изъяснительное.","Известие, что он приедет, обрадовало всех. – Известие (какое? = о чём?) – тоже изъяснительное: «что» – союз, слово «известие» – значения речи.","Известие, которое он принёс, обрадовало всех. – определительное."],"mini":[{"q":"«Мне сказали, что поезд задерживается». Вид придаточного?","a":"изъяснительное"}]}],"practice":[{"t":"Расставьте запятые. Подчеркните слово главной части, от которого зависит придаточное (маркер).","key":"1) Я понял, что ошибся. 2) Сестра спросила, когда начнётся фильм. 3) Учитель попросил, чтобы мы говорили тише. 4) Никто не знал, придёт ли он.","items":["Я понял что ошибся.","Сестра спросила когда начнётся фильм.","Учитель попросил чтобы мы говорили тише.","Никто не знал придёт ли он."]},{"t":"Определите вид придаточного: изъяснительное или определительное. Запишите в поле.\n\n1) Я прочитал книгу, которую ты советовал. 2) Я прочитал, что ты советовал. 3) Мы услышали, как поёт соловей.","key":"1) определительное; 2) изъяснительное (что – союзное слово); 3) изъяснительное"},{"t":"Замените прямой вопрос придаточным с частицей «ли» и запишите.\n\n1) Мама спросила: «Ты сделал уроки?» 2) Я не уверен: «Успею ли я?»","key":"1) Мама спросила, сделал ли я уроки. 2) Я не уверен, успею ли я."},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nКапитан объявил (1) что шторм усиливается (2) и (3) что всем пассажирам нужно спуститься в каюты.","key":"1 (перед «и что» запятая не ставится: два однородных придаточных, соединённых «и»)"}],"test":[{"q":"Где изъяснительное придаточное?","o":["Я думаю, что ты прав.","Мысль, которая пришла мне в голову, была проста."],"a":0,"e":"Думаю (что?).","tag":"Придаточные изъяснительные"},{"q":"Где правильно стоит частица «ли»?","o":["Не знаю, успеем ли мы.","Не знаю, ли мы успеем."],"a":0,"e":"«Ли» после первого слова придаточного.","tag":"Придаточные изъяснительные"},{"q":"Сколько запятых: «Я слышал что он уехал и что вернётся не скоро»?","a":"1|одна","e":"Однородные придаточные, соединённые «и».","tag":"Придаточные изъяснительные"},{"q":"Средство связи в «Я хочу, чтобы ты пришёл»:","o":["союз","союзное слово"],"a":0,"e":"Чтобы – всегда союз.","tag":"Придаточные изъяснительные"},{"q":"Где «что» – союзное слово?","o":["Я знаю, что ты ищешь.","Я знаю, что ты здесь."],"a":0,"e":"Ищешь (что?) – дополнение.","tag":"Придаточные изъяснительные"}],"hwtest":[{"q":"Вид придаточного: «Мы видели, как взлетает самолёт».","o":["изъяснительное","определительное"],"a":0,"e":"Видели (что?).","tag":"Придаточные изъяснительные"},{"q":"Сколько запятых: «Скажи где ты был»?","a":"1|одна","e":"Скажи, где ты был.","tag":"Придаточные изъяснительные"},{"q":"Где изъяснительное?","o":["Я боюсь, что опоздаю.","Я пришёл, когда все ушли."],"a":0,"e":"Боюсь (чего?).","tag":"Придаточные изъяснительные"}],"hw":"Записать 6 СПП с придаточными изъяснительными после глаголов: узнать, бояться, надеяться, спросить (с «ли»), попросить (с «чтобы»), услышать (с «как»). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Придаточные изъяснительные после слов речи, мысли, чувства.","tips":["Вопрос падежа от глагола главной части.","«Ли» – после первого слова.","Однородные придаточные с «и» – без запятой между ними."]},"memo":{"h":"Глагол мысли и речи – сигнал","t":"Знать, думать, сказать, услышать, понять, бояться, надеяться + вопрос «что?» → изъяснительное придаточное.","ex":["Я надеюсь, что ты придёшь.","Он боялся, как бы не опоздать."]},"date":"2027-01-12"},{"id":"oge-ru-21","title":"Придаточные обстоятельственные","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["различать придаточные времени, места, причины, условия, цели, следствия, уступки, сравнения, образа действия","ставить запятые при составных союзах"],"theory":[{"h":"Виды и вопросы","table":[["Вид","Вопрос","Средства связи","Пример"],["времени","когда? как долго?","когда, пока, как только, едва, после того как","Когда стемнело, зажгли свет."],["места","где? куда? откуда?","где, куда, откуда","Иди туда, куда зовёт сердце."],["причины","почему?","потому что, так как, оттого что, ибо","Мы спешили, потому что опаздывали."],["условия","при каком условии?","если, если бы, раз, когда (= если)","Если пойдёт дождь, возьми зонт."],["цели","зачем? с какой целью?","чтобы, для того чтобы","Я записал, чтобы не забыть."],["следствия","что из этого следует?","так что","Стало темно, так что пришлось вернуться."],["уступки","несмотря на что?","хотя, несмотря на то что, пусть","Хотя было поздно, никто не спал."],["сравнения","как? подобно чему?","как, как будто, словно, точно","Листья кружились, словно бабочки."],["образа действия и степени","как? в какой степени?","так… что, такой… что, как","Было так тихо, что слышался шорох."]],"mini":[{"q":"«Мы остались дома, потому что шёл дождь». Вид придаточного?","a":"причины"},{"q":"«Хотя было холодно, мы купались». Вид?","a":"уступки"}]},{"h":"Запятая при составных союзах","t":"Составной союз (потому что, так как, после того как, несмотря на то что) может стоять целиком после запятой или разделяться запятой, если выделяется первая часть.","list":["Мы задержались, потому что шёл снег.","Мы задержались потому, что шёл снег (подчёркиваем именно причину).","«Так что» (следствие) никогда не разделяется."],"mini":[{"q":"Разделяется ли союз «так что»?","a":"нет"}]},{"h":"Следствие или образ действия","list":["«…так что» после главной части – следствие: Пошёл дождь, так что мы вернулись.","«так…, что» с указательным словом в главной – образ действия и степени: Он говорил так тихо, что его не слышали."],"mini":[{"q":"«Было так жарко, что мы не выходили». Вид придаточного?","a":"степени|образа действия и степени|меры и степени"}]}],"practice":[{"t":"Расставьте запятые.","key":"1) Пока мы спорили, поезд ушёл. 2) Если ты придёшь рано, мы успеем в кино. 3) Хотя было поздно, в окнах горел свет. 4) Ветер дул так сильно, что деревья гнулись. 5) Мы говорили шёпотом, чтобы не разбудить малыша.","items":["Пока мы спорили поезд ушёл.","Если ты придёшь рано мы успеем в кино.","Хотя было поздно в окнах горел свет.","Ветер дул так сильно что деревья гнулись.","Мы говорили шёпотом чтобы не разбудить малыша."]},{"t":"Над союзом подпишите вид придаточного.","key":"1) времени; 2) условия; 3) уступки; 4) образа действия и степени; 5) цели","items":["Пока мы спорили поезд ушёл.","Если ты придёшь рано мы успеем в кино.","Хотя было поздно в окнах горел свет.","Ветер дул так сильно что деревья гнулись.","Мы говорили шёпотом чтобы не разбудить малыша."]},{"t":"Определите вид придаточного: следствия или образа действия и степени. Запишите в поле.\n\n1) Снег выпал рано, так что дети обрадовались. 2) Снег выпал так рано, что никто не успел убрать урожай.","key":"1) следствия; 2) образа действия и степени"},{"t":"Задание в формате ОГЭ (2). Выпишите номер предложения с придаточным уступки.\n\n1) Мы пошли гулять, потому что выглянуло солнце. 2) Мы пошли гулять, хотя шёл дождь. 3) Мы пошли гулять, чтобы подышать воздухом.","key":"2"},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nКогда мы подошли к реке (1) оказалось (2) что мост разрушен (3) так что пришлось искать брод.","key":"1, 2, 3"}],"test":[{"q":"Вид придаточного: «Я взял фонарь, чтобы не споткнуться в темноте».","o":["цели","причины","следствия"],"a":0,"e":"Взял зачем?","tag":"Придаточные обстоятельственные"},{"q":"Вид придаточного: «Раз ты обещал, сделай».","o":["условия","причины","уступки"],"a":0,"e":"Раз = если.","tag":"Придаточные обстоятельственные"},{"q":"Вид придаточного: «Он бежал, словно за ним гнались».","o":["сравнения","образа действия","причины"],"a":0,"e":"Словно – сравнение.","tag":"Придаточные обстоятельственные"},{"q":"Где придаточное следствия?","o":["Пошёл дождь, так что мы вернулись.","Дождь был такой сильный, что мы вернулись."],"a":0,"e":"Так что – следствие.","tag":"Придаточные обстоятельственные"},{"q":"Сколько запятых: «Хотя мы устали мы продолжали путь»?","a":"1|одна","e":"Хотя мы устали, мы продолжали путь.","tag":"Придаточные обстоятельственные"},{"q":"Вид придаточного: «Где кончался лес, начиналось болото».","o":["места","определительное","времени"],"a":0,"e":"Где? – место.","tag":"Придаточные обстоятельственные"}],"hwtest":[{"q":"Вид: «Пока шёл урок, в коридоре было тихо».","o":["времени","условия"],"a":0,"e":"Пока – время.","tag":"Придаточные обстоятельственные"},{"q":"Вид: «Мы не пошли, потому что заболели».","o":["причины","цели"],"a":0,"e":"Почему?","tag":"Придаточные обстоятельственные"},{"q":"Вид: «Несмотря на то что было холодно, мы купались».","o":["уступки","причины"],"a":0,"e":"Несмотря на что?","tag":"Придаточные обстоятельственные"}],"hw":"Составить по одному СПП с придаточными каждого вида из таблицы (9 предложений). Подписать вид. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Обстоятельственные придаточные: вопрос от главной части определяет вид.","tips":["Таблица видов – опора.","«Так что» – следствие, «так…, что» – степень.","«Хотя» и «но» вместе не употребляем."]},"memo":{"h":"Вопрос от главной – и вид готов","t":"Ставь вопрос от главной части: почему? – причина; зачем? – цель; несмотря на что? – уступка.","ex":["Мы ушли (почему?), потому что устали.","Мы ушли (зачем?), чтобы отдохнуть."]},"date":"2027-01-19"},{"id":"oge-ru-22","title":"СПП с несколькими придаточными","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["различать последовательное, однородное и параллельное подчинение","ставить запятые на стыке союзов"],"theory":[{"h":"Три вида подчинения","list":["Последовательное: придаточное зависит от другого придаточного (цепочка): [Я знаю], (что ты читал книгу), (которую я дал).","Однородное: придаточные одного вида зависят от одного слова и отвечают на один вопрос: [Я слышал], (что он уехал) и (что вернётся нескоро).","Параллельное (неоднородное): придаточные разного вида зависят от главной: (Когда я вернулся), [я узнал], (что гости уже ушли)."],"scheme":"Последовательное: [ ] → ( ) → ( ).   Однородное: [ ] → ( ) и ( ).   Параллельное: ( ) ← [ ] → ( ).","mini":[{"q":"Как называется подчинение, если придаточные образуют цепочку?","a":"последовательное|последовательное подчинение"}]},{"h":"Запятая на стыке союзов","t":"Если рядом стоят два союза (что + если, что + когда), запятую между ними ставят, если после второго придаточного нет второй части двойного союза «то» или «так».","list":["Он сказал, что, когда закончит, позвонит.","Он сказал, что когда закончит, то позвонит. (есть «то» – запятой между союзами нет)","Однородные придаточные с одиночным «и» – запятая не ставится."],"mini":[{"q":"Нужна ли запятая между «что» и «если»: «Я думаю что если пойдёт дождь то мы останемся»?","a":"нет"}]}],"practice":[{"t":"Расставьте запятые.","key":"1) Мы поняли, что, если не поспешим, опоздаем на автобус. 2) Я думаю, что если погода наладится, то мы пойдём в поход. 3) Когда мы вышли, было ясно, что дождя не будет. 4) Он рассказал, где был и что видел.","items":["Мы поняли что если не поспешим опоздаем на автобус.","Я думаю что если погода наладится то мы пойдём в поход.","Когда мы вышли было ясно что дождя не будет.","Он рассказал где был и что видел."]},{"t":"Определите вид подчинения. Запишите в поле.\n\n1) Я прочитал книгу, которую мне подарил друг, когда я болел. 2) Мама сказала, что обед готов и что можно садиться за стол. 3) Если будет время, я расскажу, как мы путешествовали.","key":"1) последовательное; 2) однородное; 3) параллельное"},{"t":"Начертите схемы предложений из задания 2 в поле.","key":"1) [ ], (которую …), (когда …). – последовательное: [ ] → (которую) → (когда). 2) [ ], (что …) и (что …). 3) (Если …), [ ], (как …)."},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nСтарик говорил (1) что (2) когда он был молод (3) здесь шумел густой лес (4) где водились медведи.","key":"1, 2, 3, 4"}],"test":[{"q":"Вид подчинения: «Я знаю, что ты придёшь и что принесёшь книгу».","o":["однородное","последовательное","параллельное"],"a":0,"e":"Оба придаточных отвечают на «что?» от «знаю».","tag":"СПП с несколькими придаточными"},{"q":"Вид подчинения: «Когда стемнело, мы поняли, что заблудились».","o":["параллельное","однородное","последовательное"],"a":0,"e":"Разные вопросы от главной.","tag":"СПП с несколькими придаточными"},{"q":"Нужна ли запятая между союзами: «Он сказал что когда освободится то придёт»?","o":["нет","да"],"a":0,"e":"Есть «то».","tag":"СПП с несколькими придаточными"},{"q":"Нужна ли запятая между союзами: «Он сказал что когда освободится придёт»?","o":["да","нет"],"a":0,"e":"Нет «то» – запятая ставится.","tag":"СПП с несколькими придаточными"},{"q":"Сколько придаточных: «Я видел дом, в котором жил человек, который построил этот мост»?","a":"2|два","e":"Последовательное подчинение.","tag":"СПП с несколькими придаточными"}],"hwtest":[{"q":"Вид подчинения: «Я пишу, чтобы ты знал, как я живу».","o":["последовательное","однородное"],"a":0,"e":"Цепочка.","tag":"СПП с несколькими придаточными"},{"q":"Запятая между «что» и «если»: «Знаю что если захочешь то сможешь»","o":["не нужна","нужна"],"a":0,"e":"Есть «то».","tag":"СПП с несколькими придаточными"},{"q":"Сколько запятых: «Мы шли туда где кончалась дорога и где начинался лес»?","a":"1|одна","e":"Однородные придаточные с «и».","tag":"СПП с несколькими придаточными"}],"hw":"Составить по два СПП с последовательным, однородным и параллельным подчинением; одно – со стыком союзов «что» + «если». Начертить схемы. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Несколько придаточных: схема и стрелки решают пунктуацию.","tips":["Рисуем схему со стрелками.","Стык союзов: смотрим на «то».","Однородные придаточные с «и» – без запятой."]},"memo":{"h":"Рисуй стрелки","t":"От главной части к каждому придаточному – стрелка с вопросом. Цепочка – последовательное; две стрелки к одному слову с одним вопросом – однородное; разные вопросы – параллельное.","ex":["[ ] (что?) → ( ) (какой?) → ( )"]},"date":"2027-01-26"},{"id":"oge-ru-23","title":"Бессоюзное предложение: запятая и точка с запятой","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["находить части БСП","ставить запятую и точку с запятой при перечислении"],"theory":[{"h":"Что такое БСП","t":"Бессоюзное сложное предложение состоит из частей, которые связаны без союзов – только интонацией. Знак между частями зависит от смысловых отношений.","list":["Перечисление (события происходят одновременно или друг за другом) – запятая: Светило солнце, пели птицы.","Если части далеки по смыслу или в них уже есть запятые – точка с запятой: Солнце село, поднялся ветер; в доме зажгли огни."],"ex":["[[s:Ветер]] [[p:стих]], [[s:облака]] [[p:рассеялись]]."],"scheme":"[ ], [ ], [ ].     [ , ]; [ ].","mini":[{"q":"Какой знак при простом перечислении в БСП?","a":"запятая"}]},{"h":"Точка с запятой","list":["Части распространённые и содержат свои запятые: В лесу, заросшем папоротником, было тихо; только где-то вдали стучал дятел.","Части слабо связаны по смыслу."],"mini":[{"q":"«Был поздний вечер, дождь не переставал; мы решили остаться». Почему точка с запятой?","a":"части распространены и внутри есть запятая|внутри частей есть запятые"}]}],"practice":[{"t":"Подчеркните грамматические основы и расставьте запятые.","key":"1) Наступила ночь, взошла луна, на небе зажглись звёзды. 2) Шумит прибой, кричат чайки. 3) Падал снег, деревья стояли белые.","items":["Наступила ночь взошла луна на небе зажглись звёзды.","Шумит прибой кричат чайки.","Падал снег деревья стояли белые."]},{"t":"Расставьте знаки препинания: запятые и точку с запятой.","key":"1) Дорога, размытая дождями, была непроходимой; машины застревали в грязи. 2) Солнце поднялось высоко, роса высохла; в поле начали работу. 3) Вокруг шумел лес, журчал ручей.","items":["Дорога размытая дождями была непроходимой машины застревали в грязи.","Солнце поднялось высоко роса высохла в поле начали работу.","Вокруг шумел лес журчал ручей."]},{"t":"Начертите схемы в поле.\n\n1) Шёл снег, дул ветер. 2) В комнате, освещённой лампой, было уютно; за окном бушевала метель.","key":"1) [ ], [ ]. 2) [ … , … ]; [ ]."},{"t":"Задание в формате ОГЭ (2). Найдите бессоюзное сложное предложение и выпишите его номер.\n\n1) Зазвенел звонок, и урок начался. 2) Зазвенел звонок, урок начался. 3) Когда зазвенел звонок, урок начался.","key":"2"}],"test":[{"q":"Где БСП?","o":["Шёл дождь, гремел гром.","Шёл дождь, и гремел гром.","Шёл и шёл дождь."],"a":0,"e":"Без союзов.","tag":"Бессоюзное предложение: запятая и точка с запятой"},{"q":"Какой знак при перечислении в БСП?","o":["запятая","двоеточие","тире"],"a":0,"e":"Перечисление событий.","tag":"Бессоюзное предложение: запятая и точка с запятой"},{"q":"Когда ставят точку с запятой между частями БСП?","o":["если части распространены и внутри есть запятые","если вторая часть – причина","если вторая часть – следствие"],"a":0,"e":"Сложные части.","tag":"Бессоюзное предложение: запятая и точка с запятой"},{"q":"Сколько частей: «Светило солнце, пели птицы, шумели деревья»?","a":"3|три","e":"Три основы.","tag":"Бессоюзное предложение: запятая и точка с запятой"},{"q":"Где правильный знак?","o":["Улица опустела, фонари погасли.","Улица опустела: фонари погасли."],"a":0,"e":"Перечисление одновременных событий.","tag":"Бессоюзное предложение: запятая и точка с запятой"}],"hwtest":[{"q":"Знак в БСП с перечислением:","o":["запятая","двоеточие"],"a":0,"e":"Перечисление.","tag":"Бессоюзное предложение: запятая и точка с запятой"},{"q":"Где БСП?","o":["Пришла весна, растаял снег.","Пришла весна, и растаял снег."],"a":0,"e":"Без союза.","tag":"Бессоюзное предложение: запятая и точка с запятой"},{"q":"Сколько основ: «Ветер утих, волны улеглись»?","a":"2|две","e":"Ветер утих; волны улеглись.","tag":"Бессоюзное предложение: запятая и точка с запятой"}],"hw":"Описать в 5 БСП летний вечер в деревне (перечисление событий); в двух предложениях части распространить и поставить точку с запятой. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"БСП с перечислением: запятая и точка с запятой.","tips":["Перечисление – запятая.","Длинные части с запятыми – точка с запятой.","Сначала находим все основы."]},"memo":{"h":"Перечисляем – запятая","t":"Если между частями можно поставить «и» и ничего не поменяется – это перечисление: запятая (или точка с запятой при длинных частях).","ex":["Гремел гром, сверкала молния, лил дождь."]},"date":"2027-02-02"},{"id":"oge-ru-24","title":"Бессоюзное предложение: двоеточие","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["ставить двоеточие в БСП","узнавать значения причины, пояснения, дополнения"],"theory":[{"h":"Когда ставится двоеточие","t":"Двоеточие ставится, если вторая часть раскрывает первую. Проверяем, какой союз можно подставить.","list":["Причина (потому что): Я не пошёл гулять: болела голова.","Пояснение (а именно): Картина была чудесной: над озером поднимался туман.","Дополнение (что, и увидел, что): Я выглянул в окно: во дворе играли дети. Знаю: ты прав."],"ex":["[[s:Я]] [[p:не пошёл]] гулять: [[p:болела]] [[s:голова]]."],"scheme":"[ ]: [ ]  (потому что / а именно / что)","mini":[{"q":"Какой союз подставляем, если вторая часть – причина?","a":"потому что"}]},{"h":"Как проверить","list":["Подставь «потому что» – смысл сохранился? Двоеточие.","Подставь «а именно» – подходит? Двоеточие.","Можно вставить «что» или «и увидел, что»? Двоеточие."],"ex":["Я понял: опоздали. (= понял, что опоздали)"],"mini":[{"q":"Какой знак: «Лес молчал ? все птицы улетели»?","a":"двоеточие"}]}],"practice":[{"t":"Расставьте знаки препинания в БСП.","key":"1) Мы не купались: вода была холодной. 2) Я оглянулся: за мной шла собака. 3) Погода стояла чудесная: светило солнце, дул лёгкий ветерок. 4) Помни: дружба дороже всего.","items":["Мы не купались вода была холодной.","Я оглянулся за мной шла собака.","Погода стояла чудесная светило солнце дул лёгкий ветерок.","Помни дружба дороже всего."]},{"t":"Над двоеточием подпишите значение: причина, пояснение, дополнение.","key":"1) причина; 2) дополнение; 3) пояснение; 4) дополнение","items":["Мы не купались вода была холодной.","Я оглянулся за мной шла собака.","Погода стояла чудесная светило солнце дул лёгкий ветерок.","Помни дружба дороже всего."]},{"t":"Замените СПП бессоюзным и запишите с двоеточием.\n\n1) Мы вернулись, потому что начался дождь. 2) Я знал, что он не придёт.","key":"1) Мы вернулись: начался дождь. 2) Я знал: он не придёт."},{"t":"Задание в формате ОГЭ (3). Какой знак нужен на месте пропуска? Запишите в поле.\n\nРебята радовались (?) завтра начинались каникулы.","key":"двоеточие (причина)"}],"test":[{"q":"Какой знак: «Я поднял голову ? по небу летели журавли»?","o":["двоеточие","тире","запятая"],"a":0,"e":"Поднял голову и увидел, что…","tag":"Бессоюзное предложение: двоеточие"},{"q":"Значение двоеточия: «В доме было тихо: все спали».","o":["причина","пояснение","противопоставление"],"a":0,"e":"Потому что все спали.","tag":"Бессоюзное предложение: двоеточие"},{"q":"Где нужно двоеточие?","o":["Сад был прекрасен цвели вишни.","Наступило утро запели птицы."],"a":0,"e":"Пояснение: а именно цвели вишни.","tag":"Бессоюзное предложение: двоеточие"},{"q":"Какой союз подставляем при значении дополнения?","o":["что","но","если"],"a":0,"e":"Знаю (что) ты прав.","tag":"Бессоюзное предложение: двоеточие"},{"q":"Где правильно?","o":["Он улыбнулся: всё получилось.","Он улыбнулся – всё получилось и он ушёл."],"a":0,"e":"Причина.","tag":"Бессоюзное предложение: двоеточие"}],"hwtest":[{"q":"Знак: «Не опаздывай ? поезд уходит в семь».","o":["двоеточие","запятая"],"a":0,"e":"Причина.","tag":"Бессоюзное предложение: двоеточие"},{"q":"Значение: «Я увидел: в окне горел свет».","o":["дополнение","противопоставление"],"a":0,"e":"Увидел, что…","tag":"Бессоюзное предложение: двоеточие"},{"q":"Подставьте союз: «Мы спешили: начинался концерт».","a":"потому что","e":"Причина.","tag":"Бессоюзное предложение: двоеточие"}],"hw":"Составить 6 БСП с двоеточием: по два со значением причины, пояснения и дополнения. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Двоеточие в БСП: причина, пояснение, дополнение.","tips":["Подставляем союз.","Вторая часть объясняет первую.","Двоеточие – знак объяснения."]},"memo":{"h":"Двоеточие = «а именно / потому что / что»","t":"Двоеточие – знак объяснения: вторая часть отвечает на вопрос, возникший после первой.","ex":["Мне стало грустно: лето кончилось. (почему?)","Я услышал: кто-то стучит. (что?)"]},"date":"2027-02-09"},{"id":"oge-ru-25","title":"Бессоюзное предложение: тире","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["ставить тире в БСП","узнавать значения противопоставления, времени, условия, следствия, сравнения"],"theory":[{"h":"Когда ставится тире","t":"Тире ставится, если части противопоставлены, если первая часть – время или условие, а вторая – следствие, или если есть сравнение.","list":["Противопоставление (а, но): Хотел помочь – стало только хуже.","Время (когда): Солнце взойдёт – тронемся в путь.","Условие (если): Будешь лениться – ничего не добьёшься.","Следствие (так что): Ударил мороз – река замёрзла.","Сравнение (словно): Посмотрит – рублём подарит."],"scheme":"[ ] – [ ]  (а / но, когда, если, так что, словно)","mini":[{"q":"Какой знак: «Лес рубят ? щепки летят»?","a":"тире"}]},{"h":"Двоеточие или тире","t":"Сравни: причина во второй части – двоеточие; следствие во второй части – тире.","list":["Пошёл дождь – мы вернулись домой. (следствие: так что)","Мы вернулись домой: пошёл дождь. (причина: потому что)"],"mini":[{"q":"«Сверкнула молния – грянул гром». Значение?","a":"время|следствие|быстрая смена событий"}]}],"practice":[{"t":"Расставьте знаки препинания в БСП.","key":"1) Я хотел сказать – он перебил меня. 2) Посмотрит – рублём подарит. 3) Ударил мороз – лужи затянуло льдом. 4) Будет дождь – останемся дома.","items":["Я хотел сказать он перебил меня.","Посмотрит рублём подарит.","Ударил мороз лужи затянуло льдом.","Будет дождь останемся дома."]},{"t":"Над тире подпишите значение: против., время, условие, следствие, сравнение.","key":"1) против.; 2) сравнение (словно рублём подарит); 3) следствие (так что); 4) условие (если)","items":["Я хотел сказать он перебил меня.","Посмотрит рублём подарит.","Ударил мороз лужи затянуло льдом.","Будет дождь останемся дома."]},{"t":"Поставьте двоеточие или тире. Объясните в поле.\n\n1) Мы опоздали на автобус () пришлось идти пешком. 2) Пришлось идти пешком () мы опоздали на автобус.","key":"1) тире (следствие); 2) двоеточие (причина)"},{"t":"Задание в формате ОГЭ (2). Найдите БСП со значением противопоставления и выпишите номер.\n\n1) Ветер дул – лодку несло к берегу. 2) Звали его – он не откликнулся. 3) Гроза прошла: небо прояснилось.","key":"2"}],"test":[{"q":"Знак: «Пришла беда ? отворяй ворота»?","o":["тире","двоеточие","запятая"],"a":0,"e":"Условие/время.","tag":"Бессоюзное предложение: тире"},{"q":"Значение тире: «Ехал долго – не доехал».","o":["противопоставление","причина","дополнение"],"a":0,"e":"Но не доехал.","tag":"Бессоюзное предложение: тире"},{"q":"Где двоеточие, а не тире?","o":["Я не спал всю ночь болел зуб.","Будет солнце будет и урожай."],"a":0,"e":"Причина.","tag":"Бессоюзное предложение: тире"},{"q":"Подставьте союз: «Солнце село – стало прохладно».","a":"так что|когда","e":"Следствие или время.","tag":"Бессоюзное предложение: тире"},{"q":"Где тире со значением условия?","o":["Любишь кататься – люби и саночки возить.","Я пришёл – никого нет."],"a":0,"e":"Если любишь…","tag":"Бессоюзное предложение: тире"}],"hwtest":[{"q":"Знак: «Повеял ветер ? закачались ветви».","o":["тире","двоеточие"],"a":0,"e":"Следствие.","tag":"Бессоюзное предложение: тире"},{"q":"Знак: «Я молчал ? мне нечего было сказать».","o":["двоеточие","тире"],"a":0,"e":"Причина.","tag":"Бессоюзное предложение: тире"},{"q":"Значение: «Хотел позвонить – забыл».","o":["противопоставление","условие"],"a":0,"e":"Но забыл.","tag":"Бессоюзное предложение: тире"}],"hw":"Выписать 5 пословиц, построенных как БСП с тире, и определить значение тире. Составить 3 пары предложений «двоеточие – тире» (причина / следствие). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Тире в БСП и различение с двоеточием.","tips":["Причина во второй части – двоеточие.","Следствие, противопоставление, условие – тире.","Подставляем союз."]},"memo":{"h":"Тире – знак резкости","t":"Тире ставим, когда вторая часть – неожиданный результат, противопоставление или когда первая часть звучит как «если/когда».","ex":["Чин чина почитай – а ты не спорь. Хотел прийти – не смог."]},"date":"2027-02-16"},{"id":"oge-ru-26","title":"Сложное предложение с разными видами связи","block":"s3","oge":"Задание 2–3 · Сложное предложение","learn":["находить части предложения с сочинительной, подчинительной и бессоюзной связью","ставить знаки на стыках частей"],"theory":[{"h":"Как разобрать сложное предложение","list":["1. Подчеркнуть все грамматические основы и пронумеровать части.","2. Найти союзы и союзные слова, определить связь между каждой парой частей.","3. Начертить схему и расставить знаки на каждой границе."],"ex":["[[s:Дождь]] [[p:кончился]], и [[s:мы]] [[p:вышли]] во двор, где [[p:сверкали]] [[s:лужи]].","Схема: [1], и [2], (где 3)."],"scheme":"[ ], и [ ], (где …).    [ ]: [ ], (что …).","mini":[{"q":"С чего начинаем разбор сложного предложения?","a":"с основ|подчеркнуть основы|найти грамматические основы"}]},{"h":"Стык сочинительного и подчинительного союзов","t":"Если «и» стоит перед придаточным, а после придаточного нет «то», «так», «но», запятая между «и» и подчинительным союзом ставится.","list":["Было тихо, и, когда мы вошли, никто не обернулся.","Было тихо, и когда мы вошли, то никто не обернулся."],"mini":[{"q":"Нужна ли запятая между «и» и «когда», если дальше есть «то»?","a":"нет"}]}],"practice":[{"t":"Подчеркните основы и расставьте знаки препинания.","key":"1) Солнце село, и в небе зажглись звёзды, которые отражались в реке. 2) Мы долго шли по лесу: тропинка петляла, а компас сломался. 3) Когда пришла весна, растаял снег, и ручьи побежали к реке.","items":["Солнце село и в небе зажглись звёзды которые отражались в реке.","Мы долго шли по лесу тропинка петляла а компас сломался.","Когда пришла весна растаял снег и ручьи побежали к реке."]},{"t":"Начертите схемы предложений из задания 1 в поле.","key":"1) [1], и [2], (которые 3). 2) [1]: [2], а [3]. 3) (Когда 1), [2], и [3]."},{"t":"Расставьте запятые на стыке союзов.","key":"1) Лил дождь, и, когда мы добежали до дома, одежда промокла насквозь. 2) Лил дождь, и когда мы добежали до дома, то одежда промокла насквозь.","items":["Лил дождь и когда мы добежали до дома одежда промокла насквозь.","Лил дождь и когда мы добежали до дома то одежда промокла насквозь."]},{"t":"Задание в формате ОГЭ (2). Укажите, какие виды связи есть в предложении. Запишите в поле.\n\nЯ проснулся рано: за окном пели птицы, и солнце, которое только что взошло, золотило верхушки сосен.","key":"бессоюзная, сочинительная, подчинительная"},{"t":"Задание в формате ОГЭ (3). Укажите цифры, на месте которых должны стоять запятые.\n\nМы вышли на берег (1) и (2) когда солнце показалось из-за туч (3) море засверкало (4) так ярко (5) что пришлось зажмуриться.","key":"1, 2, 3, 5"}],"test":[{"q":"Какие виды связи: «Пришла осень, и листья пожелтели, потому что ночи стали холодными»?","o":["сочинительная и подчинительная","только сочинительная","бессоюзная и подчинительная"],"a":0,"e":"И – сочинение, потому что – подчинение.","tag":"Сложное предложение с разными видами связи"},{"q":"Сколько частей: «Я знал: он придёт, и мы поговорим»?","a":"3|три","e":"Я знал; он придёт; мы поговорим.","tag":"Сложное предложение с разными видами связи"},{"q":"Где нужна запятая между «и» и «если»?","o":["Мы устали, и если не отдохнём, то не дойдём.","Мы устали, и если не отдохнём, не дойдём."],"a":1,"e":"Нет «то» – запятая: …и, если не отдохнём, не дойдём.","tag":"Сложное предложение с разными видами связи"},{"q":"Схема «(Когда 1), [2], а [3].» соответствует:","o":["Когда стемнело, мы зажгли свечи, а дети легли спать.","Мы зажгли свечи, когда стемнело, а дети легли спать."],"a":0,"e":"Придаточное впереди.","tag":"Сложное предложение с разными видами связи"},{"q":"С чего начинаем разбор сложного предложения?","o":["с грамматических основ","с запятых","с союзов"],"a":0,"e":"Сначала основы.","tag":"Сложное предложение с разными видами связи"}],"hwtest":[{"q":"Какие виды связи: «Наступил вечер: зажглись фонари, которые осветили улицу»?","o":["бессоюзная и подчинительная","сочинительная"],"a":0,"e":"Двоеточие и «которые».","tag":"Сложное предложение с разными видами связи"},{"q":"Сколько частей: «Дождь прошёл, и мы увидели радугу, которая повисла над рекой»?","a":"3|три","e":"Три основы.","tag":"Сложное предложение с разными видами связи"},{"q":"Нужна ли запятая между «и» и «когда»: «Было тихо и когда мы вошли то все обернулись»?","o":["нет","да"],"a":0,"e":"Есть «то».","tag":"Сложное предложение с разными видами связи"}],"hw":"Выписать из текста ОГЭ (любой вариант открытого банка ФИПИ) 3 сложных предложения с разными видами связи, начертить схемы. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Разные виды связи: нумеруем части, ставим знаки на каждой границе.","tips":["Основы – номера – связи – знаки.","Стык «и» + подчинительный союз.","Каждая граница проверяется отдельно."]},"memo":{"h":"Нумеруй части","t":"Каждую основу – в скобки с номером, между частями – стрелка или союз. Знаки ставим на каждой границе отдельно.","ex":["[1]: [2], (что 3), и [4]."]},"date":"2027-02-23"},{"id":"oge-ru-27","title":"Согласование, управление, примыкание","block":"s4","oge":"Задание 4 · Словосочетание","learn":["находить главное и зависимое слово","определять вид подчинительной связи"],"theory":[{"h":"Главное и зависимое слово","t":"Словосочетание – два и более самостоятельных слова, связанных по смыслу и грамматически. От главного слова ставим вопрос к зависимому.","list":["Подлежащее + сказуемое – не словосочетание (это основа).","Слово с предлогом – не словосочетание: «в лесу».","Однородные члены – не словосочетание."],"ex":["читать (что?) книгу","интересная (что?) книга – главное слово «книга»: книга (какая?) интересная"],"mini":[{"q":"Является ли «мы шли» словосочетанием?","a":"нет"},{"q":"Найдите главное слово: «очень быстро».","a":"быстро"}]},{"h":"Три вида связи","table":[["Вид","Что происходит","Зависимое слово","Примеры"],["согласование","зависимое слово повторяет род, число, падеж главного; меняем главное – меняется зависимое","прилагательное, причастие, порядковое числительное, местоимение-прилагательное","новый дом – новому дому; мой друг; первый снег"],["управление","зависимое слово стоит в определённом падеже, который требует главное; меняем главное – зависимое не меняется","существительное, местоимение-существительное (часто с предлогом)","читать книгу – читаю книгу; дом у реки; письмо другу"],["примыкание","зависимое слово неизменяемое, связь только по смыслу","наречие, деепричастие, инфинитив, неизменяемое прилагательное, притяжательные его, её, их","быстро бежать; читать лёжа; хотел уйти; его книга; цвет хаки"]],"mini":[{"q":"Вид связи: «новый дом»?","a":"согласование"},{"q":"Вид связи: «читать книгу»?","a":"управление"},{"q":"Вид связи: «быстро бежать»?","a":"примыкание"}]},{"h":"Ловушки","list":["«Его книга» – примыкание (его = чья?), а «вижу его» – управление (его = кого?).","«Пальто беж» – примыкание (неизменяемое прилагательное).","Деепричастие всегда примыкает: шёл улыбаясь."],"mini":[{"q":"Вид связи: «её платье»?","a":"примыкание"},{"q":"Вид связи: «встретил её»?","a":"управление"}]}],"practice":[{"t":"Выпишите в поле словосочетания «главное слово → зависимое» из предложения.\n\nВечером мы долго гуляли по старому парку.","key":"гуляли вечером (примыкание), долго гуляли (примыкание), гуляли по парку (управление), старому парку (согласование)"},{"t":"Над каждым словосочетанием подпишите вид связи: согл., упр., прим.","key":"1) согл.; 2) упр.; 3) прим.; 4) упр.; 5) прим.; 6) согл.","items":["осенний лес","письмо брату","говорить громко","думать о каникулах","его портфель","наша школа"]},{"t":"Найдите лишнее словосочетание в каждой строке (по виду связи). Запишите в поле.\n\n1) зимний вечер, третий урок, читать вслух. 2) мечтать о море, весело смеяться, стакан воды.","key":"1) читать вслух (примыкание, остальные – согласование); 2) весело смеяться (примыкание, остальные – управление)"},{"t":"Задание в формате ОГЭ (4). Определите вид связи и выпишите ответ.\n\nСловосочетание: «шёл не торопясь».","key":"примыкание (зависимое – деепричастие)"}],"test":[{"q":"Вид связи: «каменный мост»?","o":["согласование","управление","примыкание"],"a":0,"e":"Прилагательное согласуется.","tag":"Согласование, управление, примыкание"},{"q":"Вид связи: «помогать маме»?","o":["управление","согласование","примыкание"],"a":0,"e":"Дательный падеж требует глагол.","tag":"Согласование, управление, примыкание"},{"q":"Вид связи: «ехать верхом»?","o":["примыкание","управление","согласование"],"a":0,"e":"Наречие.","tag":"Согласование, управление, примыкание"},{"q":"Вид связи: «его дом»?","o":["примыкание","управление","согласование"],"a":0,"e":"Притяжательное «его» не изменяется.","tag":"Согласование, управление, примыкание"},{"q":"Где НЕ словосочетание?","o":["солнце светит","яркое солнце","светит ярко"],"a":0,"e":"Это грамматическая основа.","tag":"Согласование, управление, примыкание"},{"q":"Найдите главное слово: «прогулка по лесу».","a":"прогулка","e":"Прогулка (где?) по лесу.","tag":"Согласование, управление, примыкание"}],"hwtest":[{"q":"Вид связи: «третий этаж»?","o":["согласование","примыкание"],"a":0,"e":"Порядковое числительное.","tag":"Согласование, управление, примыкание"},{"q":"Вид связи: «любить читать»?","o":["примыкание","управление"],"a":0,"e":"Инфинитив.","tag":"Согласование, управление, примыкание"},{"q":"Вид связи: «ждать автобуса»?","o":["управление","согласование"],"a":0,"e":"Родительный падеж.","tag":"Согласование, управление, примыкание"}],"hw":"Выписать из любого абзаца художественного текста 10 словосочетаний, указать главное слово и вид связи (по 3 на каждый вид и одно на выбор). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Вид связи: меняем главное слово и следим за зависимым.","tips":["Основа – не словосочетание.","«Его, её, их» в значении «чей?» – примыкание.","Деепричастие и наречие – примыкание."]},"memo":{"h":"Измени главное слово","t":"Поставь главное слово в другую форму. Зависимое изменилось вслед – согласование. Осталось в своём падеже – управление. Не изменяется вовсе – примыкание.","ex":["тёплый день → тёплого дня (согласование)","ждать друга → ждём друга (управление)","очень тепло (примыкание)"]},"date":"2027-03-02"},{"id":"oge-ru-28","title":"Замена словосочетания синонимичным","block":"s4","oge":"Задание 4 · Словосочетание","learn":["заменять словосочетание со связью согласование на управление и обратно","заменять примыкание на управление"],"theory":[{"h":"Как устроено задание 4","t":"В ОГЭ нужно заменить словосочетание синонимичным с другим видом связи и записать получившееся словосочетание.","list":["Согласование → управление: деревянный дом → дом из дерева; мамина сумка → сумка мамы.","Управление → согласование: ваза из стекла → стеклянная ваза; голос птицы → птичий голос.","Управление → примыкание: смотреть с восторгом → восторженно смотреть; ответить с вежливостью → вежливо ответить.","Примыкание → управление: радостно встретить → встретить с радостью."],"mini":[{"q":"Замените на управление: «осенний день».","a":"день осени|день осенью"}]},{"h":"Алгоритм","list":["1. Найди главное слово – оно в ответе не меняется.","2. Определи вид связи в исходном словосочетании.","3. Замени зависимое слово однокоренным словом нужной части речи.","4. Проверь: смысл тот же, форма главного слова та же."],"ex":["с радостью согласился → радостно согласился (управление → примыкание)","мамин голос → голос мамы (согласование → управление)"],"mini":[{"q":"Замените на примыкание: «смотреть с удивлением».","a":"удивлённо смотреть|смотреть удивлённо"}]}],"practice":[{"t":"Замените словосочетания со связью согласование синонимичными со связью управление. Запишите в поле.\n\n1) золотое кольцо 2) школьный двор 3) морской берег 4) бабушкин платок","key":"1) кольцо из золота; 2) двор школы; 3) берег моря; 4) платок бабушки"},{"t":"Замените словосочетания со связью управление синонимичными со связью согласование. Запишите в поле.\n\n1) стол из дуба 2) запах сирени 3) вечер в июне 4) игрушка из пластмассы","key":"1) дубовый стол; 2) сиреневый запах; 3) июньский вечер; 4) пластмассовая игрушка"},{"t":"Замените словосочетания со связью управление синонимичными со связью примыкание. Запишите в поле.\n\n1) говорить с волнением 2) ответить с вежливостью 3) встретить с радостью","key":"1) говорить взволнованно; 2) ответить вежливо; 3) встретить радостно"},{"t":"Задание в формате ОГЭ (4). Замените словосочетание «с тревогой посмотрел», построенное на основе управления, синонимичным словосочетанием со связью примыкание. Напишите получившееся словосочетание.","key":"тревожно посмотрел"}],"test":[{"q":"Синоним со связью управление к «стеклянная ваза»:","o":["ваза из стекла","стеклянно в вазе","вазочка стеклянная"],"a":0,"e":"Существительное с предлогом.","tag":"Замена словосочетания синонимичным"},{"q":"Синоним со связью согласование к «звон колокола»:","o":["колокольный звон","звенеть колоколом","звон колоколов"],"a":0,"e":"Прилагательное «колокольный».","tag":"Замена словосочетания синонимичным"},{"q":"Синоним со связью примыкание к «слушал с вниманием»:","o":["внимательно слушал","слушал внимание","внимательный слушатель"],"a":0,"e":"Наречие «внимательно».","tag":"Замена словосочетания синонимичным"},{"q":"Какое слово НЕ меняется при замене?","o":["главное","зависимое"],"a":0,"e":"Меняется только зависимое.","tag":"Замена словосочетания синонимичным"},{"q":"Замените на управление: «папин портфель».","a":"портфель папы","e":"Притяжательное прилагательное → существительное в р. п.","tag":"Замена словосочетания синонимичным"}],"hwtest":[{"q":"Синоним со связью согласование: «шапка из меха».","a":"меховая шапка","e":"Прилагательное.","tag":"Замена словосочетания синонимичным"},{"q":"Синоним со связью примыкание: «улыбнулся с хитростью».","a":"хитро улыбнулся|улыбнулся хитро","e":"Наречие.","tag":"Замена словосочетания синонимичным"},{"q":"Синоним со связью управление: «лесная тропинка».","a":"тропинка в лесу|тропинка леса","e":"С предлогом.","tag":"Замена словосочетания синонимичным"}],"hw":"Выполнить по 4 замены каждого типа (согласование ↔ управление, управление → примыкание) на материале текста упражнения или любого рассказа. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Задание 4: замена вида связи без изменения главного слова.","tips":["Главное слово – в той же форме.","Ищем однокоренное слово нужной части речи.","Проверяем смысл."]},"memo":{"h":"Главное слово не трогаем","t":"Меняется только зависимое слово, главное остаётся в той же форме и на том же месте по смыслу.","ex":["кожаная куртка → куртка из кожи","с интересом слушать → слушать заинтересованно"]},"date":"2027-03-09"},{"id":"oge-ru-29","title":"Правописание приставок","block":"s5","oge":"Задание 5 · Орфография","learn":["писать приставки на з/с","различать пре- и при-","писать ы/и после приставок"],"theory":[{"h":"Приставки на З и С","t":"Приставки без-/бес-, воз-/вос-, из-/ис-, раз-/рас-, через-/черес-, вз-/вс-, низ-/нис- пишутся по произношению.","list":["Перед звонким согласным и гласным – З: безвкусный, разбить, изучить.","Перед глухим согласным – С: бесполезный, рассказ, исчезнуть.","Приставка С- всегда пишется одинаково: сделать, сбить (з- приставки нет)."],"ex":["бе[[b:з]]шумный – бе[[b:с]]конечный","ра[[b:з]]говор – ра[[b:с]]писание"],"mini":[{"q":"Как пишется: бе..срочный?","a":"бессрочный"},{"q":"Как пишется: ра..бежаться?","a":"разбежаться"}]},{"h":"ПРЕ- и ПРИ-","table":[["ПРИ-","ПРЕ-"],["приближение: прибежать, приехать","очень (высокая степень): премилый, преинтересный"],["присоединение: пришить, приклеить","пере-: преградить (перегородить), преступить (переступить)"],["близость: пришкольный, приморский","слова, которые надо запомнить: преследовать, препятствие, превратиться"],["неполнота действия: приоткрыть, присесть","–"],["доведение до конца: придумать, приучить","–"]],"mini":[{"q":"Как пишется: пр..открыть (немного открыть)?","a":"приоткрыть"},{"q":"Как пишется: пр..красный?","a":"прекрасный"}]},{"h":"Ы и И после приставок","t":"После приставок на согласный корень на И пишется с Ы: играть – сыграть, искать – подыскать.","list":["Исключения: взимать, сверхизысканный.","После приставок меж- и сверх- пишем И: межинститутский, сверхинтересный.","После иноязычных приставок пишем И: постимпрессионизм, контригра."],"mini":[{"q":"Как пишется: без..дейный?","a":"безыдейный"}]}],"practice":[{"t":"Вставьте пропущенные буквы.","key":"бесценный, разгадать, исписать, вздрогнуть, расчёт, безвкусный, восход, чересчур","items":["бе..ценный","ра..гадать","и..писать","в..дрогнуть","ра..чёт","бе..вкусный","во..ход","чере..чур"]},{"t":"Вставьте пропущенные буквы.","key":"прибрежный, превосходный, приоткрыть, преодолеть, пригород, прекратить, преобразовать, придорожный","items":["пр..брежный","пр..восходный","пр..открыть","пр..одолеть","пр..город","пр..кратить","пр..образовать","пр..дорожный"]},{"t":"Вставьте пропущенные буквы.","key":"безынтересный, предыстория, разыграть, сверхизысканный, взимать, подытожить","items":["без..нтересный","пред..стория","раз..грать","сверх..зысканный","вз..мать","под..тожить"]},{"t":"Задание в формате ОГЭ (5). Найдите слово, в котором правописание приставки определяется её значением «близость к чему-либо». Запишите в поле.\n\nпрекрасный, пришкольный, преградить, приоткрыть","key":"пришкольный"},{"t":"Объясните написание приставок в поле: пребывать в городе – прибывать в город.","key":"пребывать = находиться (пре- в слове, которое надо запомнить, значение «находиться»); прибывать = приезжать (при- – приближение)"}],"test":[{"q":"В каком слове пишется С?","o":["ра..колоть","ра..бить","бе..грамотный","и..гнать"],"a":0,"e":"Перед глухим «к».","tag":"Правописание приставок"},{"q":"В каком слове пишется ПРЕ-?","o":["пр..следовать","пр..ехать","пр..город","пр..сесть"],"a":0,"e":"Преследовать – словарное слово.","tag":"Правописание приставок"},{"q":"В каком слове пишется Ы?","o":["с..грать","меж..гровой","сверх..нтересный","пост..мпрессионизм"],"a":0,"e":"Сыграть: после русской приставки на согласный.","tag":"Правописание приставок"},{"q":"Значение приставки в слове «приклеить»:","o":["присоединение","приближение","высокая степень"],"a":0,"e":"Присоединить.","tag":"Правописание приставок"},{"q":"Как пишется: «..делать»?","a":"сделать","e":"Приставка «с-» всегда одна.","tag":"Правописание приставок"},{"q":"В каком слове приставка ПРИ- обозначает неполноту действия?","o":["пригорюниться","приподнять","приморский","прибить"],"a":1,"e":"Приподнять = немного поднять.","tag":"Правописание приставок"}],"hwtest":[{"q":"Как пишется: «ра..сыпать»?","o":["рассыпать","разсыпать"],"a":0,"e":"Перед глухим «с».","tag":"Правописание приставок"},{"q":"Как пишется: «пр..мудрый» (очень мудрый)?","o":["премудрый","примудрый"],"a":0,"e":"Очень.","tag":"Правописание приставок"},{"q":"Как пишется: «раз..скать»?","a":"разыскать","e":"Ы после приставки.","tag":"Правописание приставок"}],"hw":"Составить таблицу по 5 слов на каждое значение ПРИ- и ПРЕ- и по 5 слов с приставками на з/с. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Приставки: з/с по произношению, пре/при по значению, ы/и после приставок.","tips":["Пре = пере / очень.","Перед глухим – С.","Сыграть, подыскать, но взимать."]},"memo":{"h":"Пре = пере / очень","t":"Подставь «очень» или «пере». Получилось – пиши ПРЕ. Приближение, присоединение, близость, неполнота – ПРИ.","ex":["преградить = перегородить","пресмешной = очень смешной","присесть – неполнота действия"]},"date":"2027-03-16"},{"id":"oge-ru-30","title":"Правописание корней","block":"s5","oge":"Задание 5 · Орфография","learn":["проверять безударную гласную в корне","писать корни с чередованием","проверять непроизносимые согласные"],"theory":[{"h":"Проверяемые и непроверяемые","t":"Безударную гласную проверяем ударением в однокоренном слове: вода – воды. Непроверяемые гласные запоминаем по словарю.","list":["Проверяем словом той же части речи или однокоренным: дождливый – дождь.","Нельзя проверять глаголы видовыми парами: опоздать – не «опаздывать», а «поздно»."],"ex":["з[[b:е]]мля – з[[b:е]]мли","в[[b:е]]ликан – в[[b:е]]лик"],"mini":[{"q":"Как пишется: «м..ря»?","a":"моря"}]},{"h":"Корни с чередованием","table":[["Правило","Корни","Примеры"],["зависит от ударения: без ударения пишем по правилу","гар-/гор- (без ударения – О), зар-/зор- (без ударения – А), клан-/клон- (без ударения – О), твар-/твор- (без ударения – О)","загорать, озарение, наклониться, творение (исключения: выгарки, изгарь, пригарь, зоревать, утварь)"],["зависит от последующей буквы","лаг-/лож- (перед Г – А), раст-/ращ-/рос- (перед СТ, Щ – А); скак-/скоч- (перед К – А)","предлагать – предложить (исключение: полог); расти – росла (исключения: отрасль, росток, ростовщик, Ростов, Ростислав); скакать – вскочить (исключения: скачок, скачу)"],["зависит от суффикса -А- после корня","бер-/бир-, дер-/дир-, мер-/мир-, пер-/пир-, тер-/тир-, стел-/стил-, блест-/блист-, жег-/жиг-, чет-/чит- (И, если после корня -А-); кас-/кос- (А, если после корня -А-)","собирать – соберу; расстилать – расстелить; касаться – коснуться"],["зависит от значения","мак-/моч- (мак – погружать, моч – пропускать жидкость), равн-/ровн- (равн – одинаковый, ровн – гладкий)","макать печенье, промокнуть ноги; уравнять, выровнять дорогу"]],"mini":[{"q":"Как пишется: «пол..жить»?","a":"положить"},{"q":"Как пишется: «зам..рать»?","a":"замирать"}]},{"h":"Непроизносимые согласные","t":"Проверяем словом, где согласный слышится: честный – честь, грустный – грустить.","list":["Пишем без лишней буквы: вкусный (вкус), опасный (опасен), прелестный (прелесть).","Словарные: лестница, чувство, здравствуйте."],"mini":[{"q":"Как пишется: «уча..ник»?","a":"участник"}]}],"practice":[{"t":"Вставьте пропущенные буквы в корнях с чередованием.","key":"предлагать, предложение, выросший, растение, загорать, зарница, касаться, коснуться, блистать, заблестеть, равнина, выровнять","items":["предл..гать","предл..жение","выр..сший","р..стение","заг..рать","з..рница","к..саться","к..снуться","бл..стать","забл..стеть","р..внина","выр..внять"]},{"t":"Вставьте пропущенные буквы в проверяемых и непроверяемых корнях.","key":"холодный (холод), сверкать (сверк), обаяние (словарное), калейдоскоп (словарное), прелестный (прелесть), сторожить (сторож)","items":["х..лодный","св..ркать","об..яние","к..лейдоскоп","прел..стный","ст..рожить"]},{"t":"Вставьте пропущенные непроизносимые согласные там, где они нужны (если буквы нет – оставьте пропуск пустым).","key":"честный, вкусный, лестница, опасный, чувство, грустный, праздник, интересный","items":["че..ный","вку..ный","ле..ница","опа..ный","чу..ство","гру..ный","пра..ник","интере..ный"]},{"t":"Задание в формате ОГЭ (5). Найдите слово, в котором написание безударной гласной в корне определяется наличием суффикса -А-. Запишите в поле.\n\nрасстилать, растение, загорать, замочить","key":"расстилать"},{"t":"Объясните в поле, почему пишем по-разному: «обмакнуть кисть в краску» – «промокнуть под дождём».","key":"мак- – погружать в жидкость; мок- – пропускать жидкость, становиться мокрым"}],"test":[{"q":"В каком слове пишется А?","o":["предл..жение","р..сток","пол..жить","выр..щенный"],"a":3,"e":"Перед Щ – А: выращенный.","tag":"Правописание корней"},{"q":"В каком слове пишется И?","o":["зам..рать","зам..реть","зап..реть","отт..реть"],"a":0,"e":"После корня суффикс -А-.","tag":"Правописание корней"},{"q":"Какое слово – исключение?","o":["росток","растение","растущий","выросший"],"a":0,"e":"Росток пишется с О перед СТ.","tag":"Правописание корней"},{"q":"В каком слове пропущена непроизносимая согласная?","o":["со..нце","вку..ный","опа..ный","интере..ный"],"a":0,"e":"Солнце – солнышко.","tag":"Правописание корней"},{"q":"Как пишется: «ур..внение» (в математике)?","a":"уравнение","e":"Равн- – равный, одинаковый.","tag":"Правописание корней"},{"q":"Где корень с чередованием?","o":["выросла","вода","лестница","молоко"],"a":0,"e":"-раст-/-рос-.","tag":"Правописание корней"}],"hwtest":[{"q":"Как пишется: «изл..жить»?","o":["изложить","излажить"],"a":0,"e":"Без суффикса -А- после корня – О.","tag":"Правописание корней"},{"q":"Как пишется: «з..ря»?","o":["заря","зоря"],"a":0,"e":"Без ударения – А.","tag":"Правописание корней"},{"q":"Вставьте букву: «бл..стящий» (блистать – блестеть: суффикса -А- нет).","a":"е|блестящий","e":"Блестеть – без суффикса -А-.","tag":"Правописание корней"}],"hw":"Выучить таблицу корней с чередованием; записать по 3 слова на каждую группу (12 групп), выделить корни. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Корни: проверка ударением, чередования, непроизносимые согласные.","tips":["Чередования не проверяем ударением.","Исключения учим списком.","Непроизносимые – проверяем словом, где звук слышен."]},"memo":{"h":"Определи тип корня","t":"Сначала спроси себя: проверяемый, чередующийся или словарный корень? Чередование ударением НЕ проверяем.","ex":["загорелый – НЕ проверяем «гореть»: правило – без ударения О.","собирать: после корня -А- → И."]},"date":"2027-03-23"},{"id":"oge-ru-31","title":"Суффиксы существительных, прилагательных и глаголов","block":"s5","oge":"Задание 5 · Орфография","learn":["писать суффиксы -чик-/-щик-, -ек-/-ик-","писать суффиксы прилагательных -к-/-ск-, -ив-/-ев-, -чив-/-лив-","писать суффиксы глаголов -ова-/-ева-, -ыва-/-ива-"],"theory":[{"h":"Суффиксы существительных","list":["-ЧИК- пишем после букв д, т, з, с, ж: переводчик, лётчик, заказчик, разносчик, перебежчик.","-ЩИК- – после остальных согласных: каменщик, сварщик, кровельщик.","-ЕК- – если при склонении гласная выпадает: замочек – замочка.","-ИК- – если гласная сохраняется: ключик – ключика."],"ex":["разве[[b:д]]чик – ка[[b:м]]енщик","кусоч[[b:е]]к (кусочка) – карандаш[[b:и]]к (карандашика)"],"mini":[{"q":"Как пишется: «перебежч..к»?","a":"перебежчик"},{"q":"Как пишется: «горош..к»?","a":"горошек"}]},{"h":"Суффиксы прилагательных","list":["-К- – в качественных прилагательных с краткой формой: резкий – резок, низкий – низок.","-К- – в относительных прилагательных от слов на к, ч, ц (с чередованием на ц): казак – казацкий, ткач – ткацкий, немец – немецкий.","-СК- – в остальных относительных прилагательных: француз – французский, матрос – матросский, море – морской.","-ИВ- под ударением (красивый, ленивый), -ЕВ- без ударения (грушевый, сиреневый); исключения: милостивый, юродивый.","-ЧИВ-, -ЛИВ- – всегда с И: доверчивый, заботливый."],"ex":["рез[[b:к]]ий (резок) – француз[[b:ск]]ий"],"mini":[{"q":"Как пишется: «застенч..вый»?","a":"застенчивый"},{"q":"Как пишется: «рыба..кий»?","a":"рыбацкий"}]},{"h":"Суффиксы глаголов","t":"-ОВА-/-ЕВА- пишем, если в 1-м лице ед. ч. глагол оканчивается на -ую/-юю. -ЫВА-/-ИВА- – если на -ываю/-иваю.","ex":["заведовать – заведую","заканчивать – заканчиваю"],"mini":[{"q":"Как пишется: «команд..вать»?","a":"командовать"},{"q":"Как пишется: «разгляд..вать»?","a":"разглядывать"}]}],"practice":[{"t":"Вставьте пропущенные буквы в суффиксах существительных.","key":"лётчик, обманщик, перебежчик, уборщик, замочек (замочка), ключик (ключика), кармашек (кармашка), ножик (ножика)","items":["лёт..ик","обман..ик","перебеж..ик","убор..ик","замоч..к","ключ..к","кармаш..к","нож..к"]},{"t":"Вставьте пропущенные буквы в суффиксах прилагательных.","key":"немецкий, низкий, рыбацкий, сибирский, обидчивый, сонливый, грушевый, красивый","items":["неме..кий","низ..ий","рыба..кий","сибир..кий","обидч..вый","сонл..вый","груш..вый","крас..вый"]},{"t":"Вставьте пропущенные буквы в суффиксах глаголов.","key":"проповедовать (проповедую), выкраивать (выкраиваю), горевать (горюю), застраивать (застраиваю), ночевать (ночую), разглядывать (разглядываю)","items":["проповед..вать","выкра..вать","гор..вать","застра..вать","ноч..вать","разгляд..вать"]},{"t":"Задание в формате ОГЭ (5). Найдите слово, в котором написание суффикса определяется правилом: «в глаголах пишется -ОВА-, если в 1-м лице ед. ч. глагол оканчивается на -УЮ». Запишите в поле.\n\nрассказывать, путешествовать, развеивать, заканчивать","key":"путешествовать (путешествую)"}],"test":[{"q":"Где пишется -ЧИК-?","o":["заказ..ик","камен..ик","свар..ик","кровель..ик"],"a":0,"e":"После «з» – -чик-.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"Где пишется -ЕК-?","o":["звоноч..к","ключ..к","карандаш..к","мяч..к"],"a":0,"e":"Звоночек – звоночка: гласная выпадает.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"Где пишется -СК-?","o":["матро..кий","ре..кий","бли..кий","ни..кий"],"a":0,"e":"Матросский: матрос + -ск-.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"Где пишется -ОВА-?","o":["команд..вать","разгляд..вать","выкра..вать","доказ..вать"],"a":0,"e":"Командую.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"Как пишется: «совет..вать»?","a":"советовать","e":"Советую – -ова-.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"В каком слове суффикс -ЕВ-?","o":["груш..вый","крас..вый","лен..вый"],"a":0,"e":"Без ударения – -ев-.","tag":"Суффиксы существительных, прилагательных и глаголов"}],"hwtest":[{"q":"Где пишется -ЩИК-?","o":["налёт..ик","кровель..ик"],"a":1,"e":"После «ль» – -щик-.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"Как пишется: «танц..вать»?","o":["танцевать","танцывать"],"a":0,"e":"Танцую – суффикс -ева-.","tag":"Суффиксы существительных, прилагательных и глаголов"},{"q":"Как пишется: «горош..к»?","a":"горошек","e":"Горошка – гласная выпадает.","tag":"Суффиксы существительных, прилагательных и глаголов"}],"hw":"Составить таблицу «Суффиксы» по 4 примера на каждое правило урока. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Суффиксы разных частей речи: каждое правило с проверкой.","tips":["-Чик- после д, т, з, с, ж.","-Ек-: гласная выпадает.","Глагол – форма «я»."]},"memo":{"h":"Проверка формой «я»","t":"Глагол поставь в форму «я». «Я рисую» – суффикс -ова-. «Я заканчиваю» – -ива-.","ex":["беседовать – беседую","развеивать – развеиваю"]},"date":"2027-03-30"},{"id":"oge-ru-32","title":"Н и НН в разных частях речи","block":"s5","oge":"Задание 5 · Орфография","learn":["писать Н и НН в прилагательных","писать Н и НН в причастиях и отглагольных прилагательных","писать Н и НН в кратких формах и наречиях"],"theory":[{"h":"Прилагательные от существительных","list":["НН: корень на Н + суффикс -Н-: длинный, туманный, лимонный.","НН: суффиксы -ОНН-, -ЕНН-: революционный, клюквенный, соломенный. Исключение: ветреный (но безветренный, наветренный).","Н: суффиксы -АН-, -ЯН-, -ИН-: кожаный, глиняный, лебединый. Исключения: стеклянный, оловянный, деревянный."],"ex":["карма[[b:нн]]ый (карман + н)","соломе[[b:нн]]ый (солома + енн)","серебря[[b:н]]ый (-ян-)"],"mini":[{"q":"Как пишется: «глиня..ый»?","a":"глиняный"},{"q":"Как пишется: «клюкве..ый»?","a":"клюквенный"}]},{"h":"Причастия и отглагольные прилагательные","t":"Полные страдательные причастия пишутся с НН, отглагольные прилагательные – с Н.","list":["НН, если есть приставка (кроме не-): прочитанная книга.","НН, если есть зависимое слово: жаренная в масле рыба.","НН, если глагол совершенного вида: решённая задача (решить).","НН в словах на -ованный, -ёванный: маринованный, корчёванный.","Н – если ничего этого нет: жареная рыба, вязаный шарф.","Кованый, жёваный – с Н: -ов- здесь входит в корень.","Исключения с НН: желанный, жеманный, священный, чеканный, чванный, нечаянный, невиданный, неслыханный, негаданный."],"ex":["[[b:про]]читанная книга – НН (приставка)","кошеная трава – Н, [[b:с]]кошенная трава – НН"],"mini":[{"q":"Как пишется: «вяза..ый шарф»?","a":"вязаный"},{"q":"Как пишется: «связа..ый бабушкой шарф»?","a":"связанный"}]},{"h":"Краткие формы и наречия","list":["В кратких причастиях всегда Н: книга прочитана, задача решена.","В кратких прилагательных столько Н, сколько в полной форме: туманная – туманна, пустынная – пустынна.","В наречиях на -О/-Е столько Н, сколько в слове, от которого наречие образовано: туманно (туманный), взволнованно (взволнованный)."],"ex":["Задача реше[[b:н]]а. – краткое причастие","Ночь тума[[b:нн]]а. – краткое прилагательное"],"mini":[{"q":"Как пишется: «Письма отправле..ы»?","a":"отправлены"}]}],"practice":[{"t":"Вставьте Н или НН в прилагательных.","key":"длинный, кожаный, лебединый, стеклянный, традиционный, ветреный, безветренный, песчаный","items":["дли..ый","кожа..ый","лебеди..ый","стекля..ый","традицио..ый","ветре..ый","безветре..ый","песча..ый"]},{"t":"Вставьте Н или НН в причастиях и отглагольных прилагательных.","key":"крашеный пол, покрашенный пол, крашенный краской пол, решённая задача, маринованные грибы, кованый сундук, нечаянная встреча","items":["краше..ый пол","покраше..ый пол","краше..ый краской пол","решё..ая задача","маринова..ые грибы","кова..ый сундук","нечая..ая встреча"]},{"t":"Вставьте Н или НН в кратких формах и наречиях.","key":"написаны (кр. прич.), пустынна (пустынный), взволнованно (взволнованный), туманно (туманный)","items":["Ответы написа..ы.","Улица пусты..а.","Он говорил взволнова..о.","Утро было тума..о."]},{"t":"Задание в формате ОГЭ (5). Найдите слово, в котором правописание НН определяется правилом: «в полных страдательных причастиях с приставкой пишется НН». Запишите в поле.\n\nоловянный, нарисованный, утренний, гусиный","key":"нарисованный"},{"t":"Объясните в поле разницу: «жареный картофель» – «жаренный на сковороде картофель».","key":"жареный – отглагольное прилагательное без зависимых слов (Н); жаренный на сковороде – причастие с зависимым словом (НН)"}],"test":[{"q":"Где пишется НН?","o":["серебря..ый","деревя..ый","кожа..ый","гуси..ый"],"a":1,"e":"Деревянный – исключение.","tag":"Н и НН в разных частях речи"},{"q":"Где пишется одна Н?","o":["ветре..ый день","безветре..ый день","соломе..ая шляпа","клюкве..ый морс"],"a":0,"e":"Ветреный – исключение.","tag":"Н и НН в разных частях речи"},{"q":"Где пишется НН?","o":["стриже..ый мальчик","постриже..ый мальчик","вяза..ый шарф","плетё..ая корзина"],"a":1,"e":"Есть приставка по-.","tag":"Н и НН в разных частях речи"},{"q":"Сколько Н: «Задача реше..а»?","a":"1|одна|одну","e":"Краткое причастие.","tag":"Н и НН в разных частях речи"},{"q":"В каком наречии одна Н?","o":["ветре..о","взволнова..о","тума..о"],"a":0,"e":"Ветрено – от «ветреный».","tag":"Н и НН в разных частях речи"},{"q":"Какое слово пишется с НН?","o":["невида..ый","кова..ый","жаре..ый","варё..ый"],"a":0,"e":"Невиданный – исключение.","tag":"Н и НН в разных частях речи"}],"hwtest":[{"q":"Где НН?","o":["лимо..ый","конопля..ый","глиня..ый"],"a":0,"e":"Лимон + -н-.","tag":"Н и НН в разных частях речи"},{"q":"Сколько Н: «Книги прочита..ы»?","a":"1|одна|одну","e":"Краткое причастие.","tag":"Н и НН в разных частях речи"},{"q":"Где одна Н?","o":["варё..ая картошка","сварё..ая картошка"],"a":0,"e":"Варёная – без приставки и зависимых слов.","tag":"Н и НН в разных частях речи"}],"hw":"Выписать в два столбика по 6 пар «отглагольное прилагательное – причастие» (жареный – зажаренный и т. д.), объяснить написание. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Н/НН: часть речи → суффикс или признаки причастия → краткая форма.","tips":["Стеклянный, оловянный, деревянный.","Приставка, зависимое слово, совершенный вид, -ованн- → НН.","Краткое причастие – Н."]},"memo":{"h":"Алгоритм для Н/НН","t":"1. Определи часть речи. 2. Прилагательное от существительного – смотри на суффикс. 3. Слово от глагола – ищи приставку, зависимое слово, совершенный вид, -ованн-. Есть – НН. 4. Краткое причастие – Н.","ex":["стеклянный, оловянный, деревянный – НН","ветреный – Н"]},"date":"2027-04-06"},{"id":"oge-ru-33","title":"Личные окончания глаголов и суффиксы причастий","block":"s5","oge":"Задание 5 · Орфография","learn":["определять спряжение глагола","писать безударные личные окончания","писать суффиксы причастий настоящего времени и гласную перед -нн-"],"theory":[{"h":"Спряжение и личные окончания","t":"Если окончание безударное, спряжение определяем по инфинитиву.","list":["II спряжение: глаголы на -ить (кроме брить, стелить), 7 глаголов на -еть (смотреть, видеть, ненавидеть, зависеть, терпеть, обидеть, вертеть) и 4 на -ать (гнать, держать, дышать, слышать).","I спряжение – все остальные.","Окончания I: -ешь, -ет, -ем, -ете, -ут/-ют. Окончания II: -ишь, -ит, -им, -ите, -ат/-ят."],"ex":["стро[[b:и]]т (строить – II)","дела[[b:е]]т (делать – I)","держ[[b:и]]шь (держать – II, исключение)"],"mini":[{"q":"Какое спряжение у глагола «гнать»?","a":"II|второе|2"},{"q":"Как пишется: «кле..т обои»?","a":"клеят"}]},{"h":"Суффиксы причастий настоящего времени","t":"Суффикс причастия зависит от спряжения глагола.","list":["Действительные: I спр. – -УЩ-/-ЮЩ- (борющийся, колеблющийся), II спр. – -АЩ-/-ЯЩ- (клеящий, дышащий).","Страдательные: I спр. – -ЕМ-/-ОМ- (колеблемый, ведомый), II спр. – -ИМ- (видимый, гонимый)."],"ex":["кле[[b:я]]щий (клеить – II)","бор[[b:ю]]щийся (бороться – I)"],"mini":[{"q":"Как пишется: «стел..щийся туман»?","a":"стелющийся"}]},{"h":"Гласная перед -НН- и -Н-","t":"В страдательных причастиях прошедшего времени гласная перед -нн- зависит от инфинитива.","list":["Глагол на -ать/-ять → А/Я: посеять – посеянный, развешать – развешанный.","Глагол на -ить/-еть → Е: развесить – развешенный, увидеть – увиденный."],"mini":[{"q":"Как пишется: «обид..нный»?","a":"обиженный"}]}],"practice":[{"t":"Вставьте пропущенные буквы в окончаниях глаголов.","key":"строят, колют, стелешь, видишь, дышит, слушаешь, ненавидим, клеят","items":["стро..т","кол..т","стел..шь","вид..шь","дыш..т","слуша..шь","ненавид..м","кле..т"]},{"t":"Вставьте пропущенные буквы в суффиксах причастий.","key":"клеящий, колеблющийся, движимый, дышащий, слышимый, тающий","items":["кле..щий","колебл..щийся","движ..мый","дыш..щий","слыш..мый","та..щий"]},{"t":"Вставьте пропущенные буквы перед -нн-.","key":"посеянный, развешанное (развешать), развешенные (развесить), замешанное (замешать), обиженный (обидеть), увиденный (увидеть)","items":["посе..нный","развеш..нное бельё (развешать)","развеш..нные на стене картины (развесить)","замеш..нное тесто (замешать)","обиж..нный","увид..нный"]},{"t":"Задание в формате ОГЭ (5). Найдите слово, в котором написание суффикса причастия зависит от спряжения глагола. Запишите в поле.\n\nпосеянный, борющийся, рассказанный, нарисованный","key":"борющийся (бороться – I спряжение, суффикс -ющ-)"}],"test":[{"q":"Какое спряжение у глагола «стелить»?","o":["I","II"],"a":0,"e":"Исключение.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"Как пишется: «он дыш..т»?","o":["дышит","дышет"],"a":0,"e":"Дышать – II спряжение.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"Где пишется -ЯЩ-?","o":["кле..щий","та..щий","се..щий","ла..щий"],"a":0,"e":"Клеить – II спряжение.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"Где пишется -ИМ-?","o":["вид..мый","колебл..мый","вед..мый"],"a":0,"e":"Видеть – II спряжение.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"Как пишется: «замеш..нный» (от «замешать»)?","a":"замешанный","e":"Глагол на -ать.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"В каком слове пишется И?","o":["вид..шь","дума..шь","чита..шь"],"a":0,"e":"Видеть – II спряжение.","tag":"Личные окончания глаголов и суффиксы причастий"}],"hwtest":[{"q":"Спряжение глагола «зависеть»:","o":["II","I"],"a":0,"e":"Исключение на -еть.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"Как пишется: «бор..щийся»?","o":["борющийся","борящийся"],"a":0,"e":"Бороться – I спряжение.","tag":"Личные окончания глаголов и суффиксы причастий"},{"q":"Как пишется: «посе..нный»?","a":"посеянный","e":"Посеять – на -ять.","tag":"Личные окончания глаголов и суффиксы причастий"}],"hw":"Выписать в три столбика по 5 глаголов II спряжения на -ить, 11 глаголов-исключений и 5 глаголов I спряжения. Образовать от 6 глаголов причастия настоящего времени. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Спряжение по инфинитиву решает окончание и суффикс причастия.","tips":["Исключения – наизусть.","Суффикс причастия – по спряжению.","Гласная перед -нн- – по инфинитиву."]},"memo":{"h":"Спряжение по инфинитиву","t":"Брить, стелить – I. Гнать, держать, дышать, слышать, смотреть, видеть, ненавидеть, зависеть, терпеть, обидеть, вертеть – II.","ex":["гонят, держат, дышат, видят – II","бреют, стелют – I"]},"date":"2027-04-13"},{"id":"oge-ru-34","title":"НЕ с разными частями речи","block":"s5","oge":"Задание 5 · Орфография","learn":["писать НЕ с глаголами и деепричастиями","писать НЕ с существительными, прилагательными, наречиями","писать НЕ с причастиями"],"theory":[{"h":"Глаголы и деепричастия","t":"С глаголами и деепричастиями НЕ пишется раздельно.","list":["не знал, не зная, не спеша","Слитно – если без НЕ слово не употребляется: ненавидеть, негодовать, недоумевать, нездоровиться, ненавидя, негодуя.","Приставка недо- (меньше нормы): недосыпать, недооценивать."],"ex":["[[b:не]] успел, [[b:не]] успев","[[b:не]]годовать"],"mini":[{"q":"Как пишется: «(не)навидеть»?","a":"ненавидеть|слитно"}]},{"h":"Существительные, прилагательные, наречия на -О/-Е","list":["Слитно, если можно подобрать синоним без НЕ: неправда (ложь), невысокий (низкий), нескоро (поздно).","Слитно, если без НЕ не употребляется: невежда, небрежный, нелепо.","Раздельно, если есть противопоставление с союзом А: не высокий, а низкий; не правда, а ложь.","Раздельно со словами далеко не, вовсе не, отнюдь не, ничуть не: вовсе не интересный."],"ex":["[[b:не]]большой дом – [[b:не]] большой, а маленький дом"],"mini":[{"q":"Как пишется: «(не)весёлый, а грустный»?","a":"не весёлый|раздельно"},{"q":"Как пишется: «(не)весёлый вечер»?","a":"невесёлый|слитно"}]},{"h":"Причастия","list":["Слитно – полное причастие без зависимых слов: непрочитанная книга.","Раздельно – полное причастие с зависимыми словами: не прочитанная мной книга.","Раздельно – краткое причастие: книга не прочитана.","Раздельно – при противопоставлении: не прочитанная, а пролистанная книга."],"mini":[{"q":"Как пишется: «(не)законченная вовремя работа»?","a":"не законченная|раздельно"}]}],"practice":[{"t":"Раскройте скобки: нажимайте на скобку, пока не получится слитное или раздельное написание.","key":"не видел, ненавидеть, не спеша, недоумевать, не сказав","items":["(не)видел","(не)навидеть","(не)спеша","(не)доумевать","(не)сказав"]},{"t":"Раскройте скобки.","key":"неглубокая река, не глубокая, а мелкая река, вовсе не глубокая река, неприятель, недалеко, далеко не простой","items":["(не)глубокая река","(не)глубокая, а мелкая река","вовсе (не)глубокая река","(не)приятель","(не)далеко","далеко (не)простой"]},{"t":"Раскройте скобки в причастиях.","key":"непроверенная работа, не проверенная учителем работа, работа не проверена, нескошенный луг, не скошенный вовремя луг","items":["(не)проверенная работа","(не)проверенная учителем работа","работа (не)проверена","(не)скошенный луг","(не)скошенный вовремя луг"]},{"t":"Задание в формате ОГЭ (5). Найдите слово, в котором НЕ пишется раздельно, потому что есть противопоставление с союзом «а». Запишите в поле.\n\nОн был (не)глуп. Это был (не)друг, а враг. (Не)смотря на дождь, мы шли.","key":"не друг"}],"test":[{"q":"Как пишется: «(не)годовать»?","o":["слитно","раздельно"],"a":0,"e":"Без НЕ не употребляется.","tag":"НЕ с разными частями речи"},{"q":"Где НЕ пишется раздельно?","o":["(не)решённая задача","(не)решённая учеником задача","(не)счастье","(не)большой"],"a":1,"e":"Есть зависимое слово.","tag":"НЕ с разными частями речи"},{"q":"Где НЕ пишется слитно?","o":["(не)смотря на мороз","(не)глядя под ноги","(не)сказав ни слова"],"a":0,"e":"Несмотря на – предлог (пишется слитно).","tag":"НЕ с разными частями речи"},{"q":"Как пишется: «Задача (не)решена»?","o":["раздельно","слитно"],"a":0,"e":"Краткое причастие.","tag":"НЕ с разными частями речи"},{"q":"Как пишется: «отнюдь (не)умный»?","a":"не умный|раздельно","e":"Отнюдь не.","tag":"НЕ с разными частями речи"},{"q":"Где НЕ слитно?","o":["(не)вежда","(не)знал","(не)был"],"a":0,"e":"Без НЕ не употребляется.","tag":"НЕ с разными частями речи"}],"hwtest":[{"q":"Как пишется: «(не)спеша»?","o":["раздельно","слитно"],"a":0,"e":"Деепричастие.","tag":"НЕ с разными частями речи"},{"q":"Как пишется: «(не)высокий, а низкий»?","o":["раздельно","слитно"],"a":0,"e":"Противопоставление.","tag":"НЕ с разными частями речи"},{"q":"Как пишется: «(не)прочитанная книга» (без зависимых слов)?","a":"непрочитанная|слитно","e":"Полное причастие без зависимых слов.","tag":"НЕ с разными частями речи"}],"hw":"Составить таблицу «НЕ с разными частями речи» с 3 примерами на каждый случай. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"НЕ: часть речи → синоним без НЕ, противопоставление, зависимые слова.","tips":["Глагол и деепричастие – раздельно (кроме не употребляемых без НЕ).","Синоним без НЕ → слитно.","Причастие с зависимым словом – раздельно."]},"memo":{"h":"Сначала часть речи","t":"Глагол и деепричастие – раздельно. Сущ., прил., наречие – синоним без НЕ → слитно. Причастие – есть зависимое слово или краткая форма → раздельно.","ex":["не зная – незнакомый – не знакомый мне человек"]},"date":"2027-04-20"},{"id":"oge-ru-35","title":"Правописание наречий","block":"s5","oge":"Задание 5 · Орфография","learn":["писать гласные на конце наречий","писать Ь после шипящих на конце наречий","писать наречия через дефис"],"theory":[{"h":"Гласные на конце наречий","list":["Приставки ИЗ-, ДО-, С- → на конце А: издалека, досуха, слева.","Приставки В-, НА-, ЗА- → на конце О: вправо, налево, засветло.","После шипящих под ударением – О: горячо, свежо; без ударения – Е: певуче, могуче. Исключение: ещё."],"ex":["[[b:с]]лев[[b:а]] – [[b:на]]лев[[b:о]]","горяч[[b:о]] – певуч[[b:е]]"],"mini":[{"q":"Как пишется: «добел..»?","a":"добела"},{"q":"Как пишется: «засветл..»?","a":"засветло"}]},{"h":"Ь после шипящих","t":"На конце наречий после шипящих пишется Ь: вскачь, настежь, наотмашь, прочь.","list":["Исключения: уж, замуж, невтерпёж."],"mini":[{"q":"Как пишется: «настеж..»?","a":"настежь"}]},{"h":"Дефис в наречиях","list":["ПО- + -ому/-ему, -ски, -цки, -ьи: по-новому, по-русски, по-немецки, по-волчьи.","ВО-/В- + -ых/-их: во-первых, в-третьих.","КОЕ-, -ТО, -ЛИБО, -НИБУДЬ: кое-где, когда-то, куда-нибудь.","Повторы: еле-еле, крепко-накрепко, давным-давно."],"ex":["по-[[b:дружески]]","во-[[b:вторых]]"],"mini":[{"q":"Как пишется: «(по)волчьи»?","a":"по-волчьи"}]}],"practice":[{"t":"Вставьте пропущенные буквы на конце наречий.","key":"справа, наглухо, досуха, засветло, изредка, влево","items":["справ..","наглух..","досух..","засветл..","изредк..","влев.."]},{"t":"Вставьте О или Е после шипящих, Ь – где нужен.","key":"горячо, певуче, ещё, вскачь, уж, настежь, невтерпёж","items":["горяч..","певуч..","ещ..","вскач..","уж..","настеж..","невтерпёж.."]},{"t":"Раскройте скобки: выберите дефисное написание там, где оно нужно (нажимайте на скобку).","key":"по-новому, по-английски, во-вторых, кое-где, по-зимнему","items":["(по)новому","(по)английски","(во)вторых","(кое)где","(по)зимнему"]},{"t":"Задание в формате ОГЭ (5). Найдите наречие, в котором на конце пишется буква А, потому что оно образовано с помощью приставки С-. Запишите в поле.\n\nвлево, справа, засветло, наглухо","key":"справа"}],"test":[{"q":"Как пишется: «издавн..»?","o":["издавна","издавно"],"a":0,"e":"Приставка из- → А.","tag":"Правописание наречий"},{"q":"Как пишется: «докрасн..»?","o":["докрасна","докрасно"],"a":0,"e":"До- → А.","tag":"Правописание наречий"},{"q":"Где пишется Ь?","o":["наотмаш..","уж..","замуж.."],"a":0,"e":"Уж и замуж – исключения.","tag":"Правописание наречий"},{"q":"Как пишется: «(по)дружески»?","o":["через дефис","слитно","раздельно"],"a":0,"e":"По- + -ски.","tag":"Правописание наречий"},{"q":"Где после шипящего пишется Е?","o":["могуч..","горяч..","свеж.."],"a":0,"e":"Без ударения – Е.","tag":"Правописание наречий"},{"q":"Как пишется наречие: «(во)первых»?","a":"во-первых","e":"Во- + -ых.","tag":"Правописание наречий"}],"hwtest":[{"q":"Как пишется: «слев..»?","o":["слева","слево"],"a":0,"e":"Приставка с- → А.","tag":"Правописание наречий"},{"q":"Как пишется: «настеж..»?","a":"настежь","e":"Ь после шипящего на конце наречия.","tag":"Правописание наречий"},{"q":"Как пишется: «(по)русски»?","o":["по-русски","порусски"],"a":0,"e":"По- + -ски.","tag":"Правописание наречий"}],"hw":"Составить таблицу «Правописание наречий» (4 правила урока) по 5 примеров на каждое. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Наречия: гласные на конце, Ь после шипящих, дефис.","tips":["Из-, до-, с- → А; в-, на-, за- → О.","Уж, замуж, невтерпёж – без Ь.","По- + -ому, -ски, -ьи – дефис."]},"memo":{"h":"Приставка подскажет конец","t":"ИЗ-, ДО-, С- тянут к А (издалека, докрасна, сначала); В-, НА-, ЗА- – к О (влево, направо, заново).","ex":["слева – налево","досуха – насухо"]},"date":"2027-04-27"},{"id":"oge-ru-36","title":"Анализ содержания текста (задание 6)","block":"s6","oge":"Задание 6 · Анализ текста","learn":["находить в тексте подтверждение каждого утверждения","отличать верное утверждение от частично верного"],"theory":[{"h":"Как устроено задание 6","t":"Даны несколько утверждений о тексте. Нужно выбрать те, которые соответствуют содержанию. Ответ всегда ищем в конкретных предложениях текста.","list":["Читаем утверждение и находим в тексте предложение, о котором оно говорит.","Сравниваем каждое слово: кто, что сделал, когда, почему.","Утверждение верно только тогда, когда верно целиком."],"mini":[{"q":"Можно ли выбрать утверждение, которое верно наполовину?","a":"нет"}]},{"h":"Типичные ловушки","list":["Подмена героя: в тексте действует бабушка, в утверждении – мама.","Подмена причины: «он скучал, потому что…» – а в тексте причина другая.","Сведения «из жизни», которых нет в тексте: утверждение кажется разумным, но в тексте об этом не говорится.","Слова «всегда», «никогда», «все»: проверяем, не преувеличение ли это."],"mini":[{"q":"Утверждение звучит правдоподобно, но в тексте об этом ничего нет. Верно ли оно для задания 6?","a":"нет"}]}],"practice":[{"t":"Прочитайте текст. Отметьте маркером предложения, в которых говорится, почему герой перестал скучать в деревне.\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"предложения 6, 8, 9 (герой услышал, «как просыпается мир», и понял, что красоту надо уметь замечать)"},{"t":"Какие утверждения соответствуют содержанию текста? Запишите номера в поле и укажите номер предложения-доказательства для каждого верного.\n\n1) Герой с нетерпением ждал каникул в городе. 2) В деревне у героя было много друзей. 3) Бабушка привела героя к реке до рассвета. 4) Бабушка приезжала в деревню ради рыбалки. 5) Герой понял, что красоту нужно уметь замечать.","key":"1 (предл. 2), 3 (предл. 4), 5 (предл. 9). Неверно: 2 – друзей не было (3); 4 – бабушка приезжала ради утренней красоты (7)."},{"t":"Найдите в утверждении ошибку и исправьте его в поле.\n\n«Первую неделю в деревне герой радовался тишине и не вспоминал о городе».","key":"Первую неделю герой скучал по шумным улицам города (предложение 2)."},{"t":"Сформулируйте в поле основную мысль текста одним предложением.","key":"Красоту окружающего мира нужно уметь замечать; иногда для этого достаточно остановиться и прислушаться."}],"test":[{"q":"Что значит «утверждение соответствует тексту»?","o":["оно подтверждается конкретным предложением","оно кажется правдоподобным","оно совпадает с моим мнением"],"a":0,"e":"Нужно доказательство из текста.","tag":"Анализ содержания текста (задание 6)"},{"q":"Утверждение «Бабушка уезжала в деревню каждое лето». Какое предложение подтверждает его?","o":["1","4","7","9"],"a":0,"e":"«Каждое лето бабушка уезжала в деревню…»","tag":"Анализ содержания текста (задание 6)"},{"q":"Утверждение «Герою в деревне было скучно всё лето». Верно ли?","o":["нет – после утра у реки он больше не скучал","да"],"a":0,"e":"Предложение 8.","tag":"Анализ содержания текста (задание 6)"},{"q":"Какой приём используют составители, чтобы сделать утверждение неверным?","o":["подменяют причину или героя","меняют знаки препинания","сокращают текст"],"a":0,"e":"Подмена – главная ловушка.","tag":"Анализ содержания текста (задание 6)"},{"q":"С каким словом в утверждениях надо быть особенно осторожным?","o":["никогда","однажды","утром"],"a":0,"e":"Обобщения легко превращаются в преувеличение.","tag":"Анализ содержания текста (задание 6)"}],"hwtest":[{"q":"Почему бабушка приезжала в деревню?","o":["ради красоты пробуждающегося утра","чтобы работать в огороде"],"a":0,"e":"Предложение 7.","tag":"Анализ содержания текста (задание 6)"},{"q":"Сколько верных утверждений может быть в задании 6?","o":["несколько","всегда одно"],"a":0,"e":"Обычно два–три.","tag":"Анализ содержания текста (задание 6)"},{"q":"Номер предложения, где говорится, что в деревне не было кинотеатра:","a":"3","e":"Предложение 3.","tag":"Анализ содержания текста (задание 6)"}],"hw":"Выполнить задание 6 в двух вариантах открытого банка ФИПИ; для каждого выбранного утверждения записать номер предложения-доказательства. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Задание 6: доказательство номером предложения.","tips":["Каждое утверждение – с номером предложения.","Частично верное – неверное.","Не додумываем за автора."]},"memo":{"h":"Номер предложения – доказательство","t":"Напротив каждого утверждения выпиши номер предложения, которое его подтверждает. Нет номера – утверждение неверное.","ex":["«Бабушка будила внука до рассвета» – (4)."]},"date":"2027-05-04"},{"id":"oge-ru-37","title":"Средства выразительности: тропы (задание 7)","block":"s6","oge":"Задание 7 · Тропы","learn":["узнавать эпитет, метафору, олицетворение, сравнение, гиперболу, литоту","объяснять, зачем автор использует троп"],"theory":[{"h":"Что такое троп","t":"Троп – слово или выражение в переносном значении, которое создаёт образ. Чтобы найти троп, спрашиваем: в прямом ли значении употреблено слово?","table":[["Троп","Что это","Пример"],["эпитет","образное определение, выделяющее яркий признак","золотая осень, хрустальный звон"],["сравнение","сопоставление с помощью как, словно, будто, точно, или творительного падежа","Туман лежал, как пуховое одеяло. Снег лёг ковром."],["метафора","скрытое сравнение: перенос по сходству без «как»","костёр рябины, море цветов"],["олицетворение","неживое наделяется свойствами живого","проснулся мир, лес задумался"],["гипербола","художественное преувеличение","сто раз говорил, море слёз"],["литота","художественное преуменьшение","мальчик с пальчик, ждать одну минуточку"]],"mini":[{"q":"Какое значение у слова в тропе – прямое или переносное?","a":"переносное"}]},{"h":"Как отличить метафору от сравнения и олицетворения","list":["Есть «как, словно, будто» или творительный падеж – сравнение.","Неживое ведёт себя как человек (думает, плачет, просыпается) – олицетворение.","Нет слов сравнения, есть перенос по сходству – метафора: «костёр рябины» (рябина красная, как костёр)."],"ex":["Туман [[b:лежал, как пуховое одеяло]]. – сравнение","[[b:Просыпается мир]]. – олицетворение"],"mini":[{"q":"«Звёзды перешёптывались». Какой троп?","a":"олицетворение"}]}],"practice":[{"t":"Отметьте маркером тропы в предложениях. Над каждым подпишите название (инструмент «Подпись»).","key":"1) золотые – эпитет; 2) как пуховое одеяло – сравнение; 3) лес дремлет – олицетворение; 4) тысячу раз – гипербола; 5) огонь рябины – метафора","items":["Наступили золотые дни осени.","Туман лежал на воде как пуховое одеяло.","Под снегом дремлет лес.","Я тысячу раз просил тебя не опаздывать.","В саду горит огонь рябины красной."]},{"t":"Найдите в тексте предложения, где использованы сравнение и олицетворение. Запишите номера в поле.\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"сравнение – 5 (как пуховое одеяло); олицетворение – 6 (просыпается мир)"},{"t":"Определите, какой троп использован, и объясните в поле, зачем он нужен автору.\n\n«Берёзы стояли в тишине, словно задумавшись о чём-то своём».","key":"сравнение (словно) с элементом олицетворения: деревья наделены способностью думать – автор передаёт тишину и неподвижность осеннего дня"},{"t":"Задание в формате ОГЭ (7). В каком варианте ответа средством выразительности является метафора? Запишите номер в поле.\n\n1) Ветер выл, как раненый зверь. 2) Тихая речка блестела на солнце. 3) Над городом бушевал океан огней. 4) Мы ждали целую вечность.","key":"3 (океан огней); 1 – сравнение, 2 – эпитет, 4 – гипербола"}],"test":[{"q":"Какой троп: «вода как зеркало»?","o":["сравнение","метафора","эпитет","олицетворение"],"a":0,"e":"Есть «как».","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Какой троп: «тучи хмурятся»?","o":["олицетворение","гипербола","литота","сравнение"],"a":0,"e":"Неживое хмурится, как человек.","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Какой троп: «море улыбок»?","o":["метафора","сравнение","эпитет"],"a":0,"e":"Скрытое сравнение без «как».","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Какой троп: «ростом с мизинчик»?","o":["литота","гипербола","эпитет"],"a":0,"e":"Преуменьшение.","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Какой троп: «весёлый ручеёк»?","o":["эпитет","литота","сравнение"],"a":0,"e":"Образное определение.","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Какой троп: «я сто лет тебя не видел»?","a":"гипербола","e":"Преувеличение.","tag":"Средства выразительности: тропы (задание 7)"}],"hwtest":[{"q":"Троп: «луна, как бледное пятно»","o":["сравнение","метафора"],"a":0,"e":"Как.","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Троп: «спит земля»","o":["олицетворение","эпитет"],"a":0,"e":"Неживое спит.","tag":"Средства выразительности: тропы (задание 7)"},{"q":"Троп: «серебряный иней»","o":["эпитет","гипербола"],"a":0,"e":"Образное определение.","tag":"Средства выразительности: тропы (задание 7)"}],"hw":"Найти в стихотворении С. А. Есенина «Берёза» или А. С. Пушкина «Зимнее утро» по два примера эпитета, сравнения, олицетворения, метафоры. Выписать с объяснением. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Тропы: переносное значение и проверочные вопросы.","tips":["«Как» – сравнение.","Живое действие у неживого – олицетворение.","Объясняем, какой образ создаёт троп."]},"memo":{"h":"Проверочные вопросы","t":"Есть «как»? – сравнение. Живое действие у неживого? – олицетворение. Определение-образ? – эпитет. Скрытое сравнение? – метафора. Преувеличение? – гипербола.","ex":["шёлковые травы – эпитет","вьюга злится – олицетворение"]},"date":"2027-05-11"},{"id":"oge-ru-38","title":"Средства выразительности: лексические средства и фигуры речи (задание 7)","block":"s6","oge":"Задание 7 · Фигуры речи","learn":["узнавать фразеологизм, лексический повтор, антитезу, градацию, риторический вопрос и восклицание","отличать фигуры речи от тропов"],"theory":[{"h":"Лексические средства","list":["Фразеологизм – устойчивое сочетание с цельным значением: бить баклуши (бездельничать), как снег на голову (неожиданно).","Лексический повтор – повторение одного и того же слова для усиления: Жди меня, и я вернусь, только очень жди.","Контекстные синонимы и антонимы – слова, которые становятся синонимами или антонимами только в этом тексте.","Разговорные и просторечные слова создают живую интонацию: глазеть, болтать."],"mini":[{"q":"«Он вернулся как снег на голову». Какое средство?","a":"фразеологизм"}]},{"h":"Фигуры речи","t":"Фигура речи – особое построение фразы. Слова в ней могут быть и в прямом значении.","list":["Антитеза – противопоставление: Они сошлись: волна и камень, стихи и проза, лёд и пламень.","Градация – нарастание: Не жалею, не зову, не плачу.","Риторический вопрос – вопрос, на который не ждут ответа: Кто не любит весну?","Риторическое восклицание – эмоциональное восклицание: Как хороша зима!","Ряд однородных членов – перечисление создаёт полноту картины: плеснула рыба, запела птица, зашелестела трава."],"mini":[{"q":"«Не жалею, не зову, не плачу». Какая фигура?","a":"градация"}]}],"practice":[{"t":"Отметьте маркером средство выразительности и подпишите его название.","key":"1) риторический вопрос; 2) антитеза (богатый – бедный); 3) фразеологизм (сломя голову); 4) градация (пришёл, увидел, победил); 5) лексический повтор (лес)","items":["Кто из нас не мечтал о путешествиях?","Богатый и бедный одинаково радовались весне.","Мальчишки бежали к реке сломя голову.","Пришёл увидел победил.","Лес лес кругом бескрайний лес."]},{"t":"Найдите в тексте предложение с рядом однородных членов, которые создают картину пробуждения природы. Запишите номер и объясните роль приёма.\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"6: «плеснула рыба, запела птица, зашелестела трава» – перечисление звуков передаёт, как постепенно оживает утро"},{"t":"Задание в формате ОГЭ (7). В каком варианте средством выразительности является фразеологизм? Запишите номер.\n\n1) В деревне время текло медленно. 2) Мы работали спустя рукава. 3) Как ярко светит солнце! 4) Шумный город – тихая деревня.","key":"2 (спустя рукава); 1 – метафора/олицетворение, 3 – риторическое восклицание, 4 – антитеза"},{"t":"Составьте в поле 3 предложения о зиме: с антитезой, с риторическим вопросом, с градацией.","key":"Например: Дома тепло, а на улице лютый мороз. Кто не радуется первому снегу? Снег падал, кружил, укутывал всё вокруг."}],"test":[{"q":"Какая фигура: «Где ты, моё детство?»","o":["риторический вопрос","антитеза","градация"],"a":0,"e":"Вопрос без ожидания ответа.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"},{"q":"Средство: «водой не разольёшь»?","o":["фразеологизм","метафора","эпитет"],"a":0,"e":"Устойчивое выражение = очень дружны.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"},{"q":"Средство: «Я царь – я раб, я червь – я бог»?","o":["антитеза","градация","повтор"],"a":0,"e":"Противопоставление.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"},{"q":"Средство: «Ждал, ждал и ждал»?","o":["лексический повтор","антитеза","литота"],"a":0,"e":"Повтор слова.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"},{"q":"Что относится к фигурам речи?","o":["градация","эпитет","метафора","гипербола"],"a":0,"e":"Градация – построение фразы.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"}],"hwtest":[{"q":"Средство: «Как прекрасна весна!»","o":["риторическое восклицание","сравнение"],"a":0,"e":"Эмоциональное восклицание.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"},{"q":"Средство: «как в воду глядел»","o":["фразеологизм","антитеза"],"a":0,"e":"Устойчивое выражение.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"},{"q":"Средство: «Мелькнул, сверкнул, исчез»","o":["градация","литота"],"a":0,"e":"Нарастание.","tag":"Средства выразительности: лексические средства и фигуры речи (задание 7)"}],"hw":"Найти в стихотворениях М. Ю. Лермонтова по одному примеру антитезы, риторического вопроса, риторического восклицания, лексического повтора. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Фигуры речи и лексические средства: построение фразы, а не переносное значение.","tips":["Фигура – как построена фраза.","Фразеологизм заменяем одним словом.","Объясняем роль приёма."]},"memo":{"h":"Троп или фигура?","t":"Троп – переносное значение слова. Фигура – построение предложения: вопрос без ответа, противопоставление, нарастание, повтор.","ex":["Как прекрасен этот мир! – восклицание","Ты и убогая, ты и обильная… – антитеза"]},"date":"2027-05-18"},{"id":"oge-ru-39","title":"Лексический анализ (задание 8)","block":"s6","oge":"Задание 8 · Лексика","learn":["находить синонимы, антонимы, фразеологизмы в тексте","подбирать синоним к слову из текста","определять значение слова по контексту"],"theory":[{"h":"Что проверяет задание 8","t":"Нужно найти в указанных предложениях слово с заданным значением, синоним или антоним к слову, фразеологизм, разговорное или книжное слово.","list":["Синонимы – слова, близкие по значению: тихо – беззвучно.","Контекстные синонимы – сближаются только в этом тексте: бабушка – старушка.","Антонимы – противоположные по значению: шумный – тихий.","Фразеологизм – устойчивое выражение с цельным значением."],"mini":[{"q":"Подберите антоним к слову «шумный».","a":"тихий"}]},{"h":"Как искать","list":["Читаем указанные предложения целиком, а не только одно слово.","Подставляем найденное слово вместо данного – смысл не должен измениться (для синонима).","Записываем слово в той форме, в какой оно стоит в тексте, если задание этого требует."],"mini":[{"q":"Синоним к слову «рассвет»:","a":"заря|восход"}]}],"practice":[{"t":"В предложениях 2–3 найдите антоним к слову «тихим» и выпишите его.\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"шумным (шумным улицам)"},{"t":"Подберите в поле синонимы к словам из текста: медленно, тихо, старый, однажды.","key":"медленно – неспешно, неторопливо; тихо – негромко, вполголоса; старый – ветхий, давний; однажды – как-то раз"},{"t":"Объясните значение слов в поле: «околица», «туман», «рассвет».","key":"околица – окраина деревни, край села; туман – скопление мелких капель воды в воздухе у земли; рассвет – время, когда начинает светать"},{"t":"Задание в формате ОГЭ (8). В предложениях 6–9 найдите фразеологизм или напишите «нет», если его нет. Затем замените слово «молча» (предложение 6) синонимом.","key":"фразеологизма нет; молча – безмолвно, не говоря ни слова"}],"test":[{"q":"Синоним к слову «скучать» (по городу):","o":["тосковать","радоваться","веселиться"],"a":0,"e":"Тосковать по городу.","tag":"Лексический анализ (задание 8)"},{"q":"Антоним к слову «рассвет»:","o":["закат","восход","утро"],"a":0,"e":"Закат – конец дня.","tag":"Лексический анализ (задание 8)"},{"q":"Что такое контекстные синонимы?","o":["слова, близкие по значению только в данном тексте","слова с одинаковым написанием","устаревшие слова"],"a":0,"e":"Сближаются в контексте.","tag":"Лексический анализ (задание 8)"},{"q":"Фразеологизм со значением «очень быстро»:","o":["во весь дух","спустя рукава","сидеть сложа руки"],"a":0,"e":"Бежать во весь дух.","tag":"Лексический анализ (задание 8)"},{"q":"Значение слова «околица»:","a":"окраина деревни|край деревни|окраина села","e":"Выход из деревни, её край.","tag":"Лексический анализ (задание 8)"}],"hwtest":[{"q":"Синоним к слову «тихо»:","o":["негромко","звонко"],"a":0,"e":"Негромко.","tag":"Лексический анализ (задание 8)"},{"q":"Антоним к слову «старый» (дом):","o":["новый","ветхий"],"a":0,"e":"Ветхий – синоним.","tag":"Лексический анализ (задание 8)"},{"q":"Значение фразеологизма «как снег на голову»:","a":"неожиданно|внезапно","e":"Неожиданно.","tag":"Лексический анализ (задание 8)"}],"hw":"Выполнить задание 8 в трёх вариантах открытого банка ФИПИ. Составить словарик из 10 синонимических пар по теме «Природа». Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Лексический анализ: проверка подстановкой.","tips":["Читаем предложения целиком.","Синоним проверяем подстановкой.","Записываем слово так, как требует задание."]},"memo":{"h":"Проверка подстановкой","t":"Синоним подставь в предложение вместо исходного слова: если предложение не стало странным – синоним найден верно.","ex":["Туман «лежал» → «стелился» – подходит.","«Медленно» → «неспешно» – подходит."]},"date":"2027-05-25"},{"id":"oge-ru-40","title":"Изложение: микротемы и абзацы","block":"s7","oge":"Задание 1 · Изложение","learn":["выделять микротемы текста","сохранять абзацное членение","формулировать микротему одним предложением"],"theory":[{"h":"Как устроено задание 1","t":"Текст прослушивают два раза. Нужно написать сжатое изложение (не менее 70 слов), передав все микротемы и главное содержание каждой.","list":["В тексте ОГЭ обычно три микротемы – три абзаца.","Каждая микротема в изложении – отдельный абзац.","Потерянная микротема снижает баллы по первому критерию."],"mini":[{"q":"Сколько микротем обычно в тексте изложения ОГЭ?","a":"3|три"}]},{"h":"Микротема","t":"Микротема – часть общей темы, о которой говорится в одном абзаце. Её удобно формулировать вопросом или коротким утверждением.","list":["Ищем ключевые слова абзаца – они подскажут микротему.","Первое предложение абзаца часто содержит его главную мысль.","Записываем микротему: «Дружба проверяется в трудностях»."],"mini":[{"q":"Где чаще всего находится главная мысль абзаца?","a":"в первом предложении|в начале абзаца|первое предложение"}]}],"practice":[{"t":"Прочитайте текст. Отметьте маркером в каждом абзаце предложение, в котором заключена микротема.\n\nЧто значит быть настоящим другом? Многие думают, что друг – это тот, кто всегда рядом в весёлую минуту, с кем интересно проводить время. Но легко быть рядом, когда всё хорошо. Настоящая дружба проверяется в трудностях.\n\nДруг не отвернётся, если ты ошибся, и не станет радоваться твоей неудаче. Он скажет правду, даже если она неприятна, потому что ему важно, чтобы ты стал лучше. Иногда такая честность обижает, но именно она отличает друга от приятеля.\n\nДружба – это ещё и умение отдавать. Невозможно только получать поддержку и внимание и ничего не давать взамен. Тот, кто хочет иметь друга, должен сам научиться быть другом: слушать, помогать, прощать. Только тогда дружба станет долгой и крепкой.","key":"1-й абзац: «Настоящая дружба проверяется в трудностях»; 2-й: «Он скажет правду… именно она отличает друга от приятеля»; 3-й: «Дружба – это ещё и умение отдавать»"},{"t":"Сформулируйте в поле три микротемы текста (по одному предложению).","key":"1) Настоящая дружба проверяется не в радости, а в трудностях. 2) Друг говорит правду, даже неприятную, и этим отличается от приятеля. 3) Чтобы иметь друга, нужно самому уметь отдавать: слушать, помогать, прощать."},{"t":"Составьте в поле план изложения из трёх пунктов (назывные предложения).","key":"1) Испытание дружбы трудностями. 2) Честность как признак друга. 3) Умение отдавать."},{"t":"Напишите в поле изложение первого абзаца в 2–3 предложениях.","key":"Например: Многие считают другом того, с кем весело. Однако быть рядом в хорошие минуты легко, а настоящая дружба проверяется в трудностях."}],"test":[{"q":"Минимальный объём сжатого изложения:","o":["70 слов","150 слов","50 слов"],"a":0,"e":"Не менее 70 слов.","tag":"Изложение: микротемы и абзацы"},{"q":"Сколько раз прослушивают текст?","o":["2","1","3"],"a":0,"e":"Два раза.","tag":"Изложение: микротемы и абзацы"},{"q":"Что такое микротема?","o":["часть темы, раскрываемая в абзаце","главная мысль всего текста","заглавие"],"a":0,"e":"Одна микротема – один абзац.","tag":"Изложение: микротемы и абзацы"},{"q":"Сколько абзацев должно быть в изложении по тексту с тремя микротемами?","a":"3|три","e":"Каждая микротема – абзац.","tag":"Изложение: микротемы и абзацы"},{"q":"Что записываем при первом прослушивании?","o":["ключевые слова каждого абзаца","текст дословно","ничего"],"a":0,"e":"Опорные слова.","tag":"Изложение: микротемы и абзацы"}],"hwtest":[{"q":"Микротема второго абзаца текста о дружбе:","o":["честность друга","умение прощать"],"a":0,"e":"Друг говорит правду.","tag":"Изложение: микротемы и абзацы"},{"q":"Можно ли объединить две микротемы в один абзац?","o":["нет","да"],"a":0,"e":"Нарушится абзацное членение.","tag":"Изложение: микротемы и абзацы"},{"q":"Минимальный объём изложения в словах:","a":"70","e":"Не менее 70.","tag":"Изложение: микротемы и абзацы"}],"hw":"Прослушать текст изложения из открытого банка ФИПИ, записать микротемы и план. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Микротемы и абзацы – основа изложения.","tips":["Три микротемы – три абзаца.","Ключевые слова при первом прослушивании.","Формулируем микротему одним предложением."]},"memo":{"h":"Слушаем – записываем опоры","t":"При первом прослушивании записываем 3–4 ключевых слова на каждый абзац, при втором – уточняем и связываем их.","ex":["1) друг – трудности","2) правда, честность","3) умение отдавать"]},"date":"2027-06-01"},{"id":"oge-ru-41","title":"Изложение: приёмы сжатия","block":"s7","oge":"Задание 1 · Изложение","learn":["использовать исключение, обобщение и упрощение","сохранять главное в каждой микротеме"],"theory":[{"h":"Три приёма сжатия","table":[["Приём","Что делаем","Пример"],["исключение","убираем повторы, подробности, второстепенные примеры","«Друг не отвернётся, если ты ошибся, и не станет радоваться твоей неудаче» → «Друг не отвернётся в беде»"],["обобщение","заменяем перечень одним общим словом","«слушать, помогать, прощать» → «заботиться о друге»"],["упрощение","заменяем сложное предложение простым, придаточное – оборотом или словом","«Тот, кто хочет иметь друга, должен…» → «Желающий иметь друга должен…»"]],"mini":[{"q":"Какой приём: «яблоки, груши, сливы» → «фрукты»?","a":"обобщение"},{"q":"Какой приём: убираем подробности и примеры?","a":"исключение"}]},{"h":"Как не потерять смысл","list":["Сжимаем подробности, а не мысль: главное предложение абзаца остаётся.","Не добавляем своих рассуждений – изложение передаёт текст автора.","Связываем предложения: однако, поэтому, кроме того."],"mini":[{"q":"Можно ли добавлять свои мысли в сжатое изложение?","a":"нет"}]}],"practice":[{"t":"Сожмите предложение приёмом обобщения. Запишите в поле.\n\nТот, кто хочет иметь друга, должен сам научиться быть другом: слушать, помогать, прощать.","key":"Чтобы иметь друга, нужно самому быть заботливым другом."},{"t":"Сожмите предложение приёмом исключения. Запишите в поле.\n\nМногие думают, что друг – это тот, кто всегда рядом в весёлую минуту, с кем интересно проводить время.","key":"Многие считают другом того, с кем весело."},{"t":"Сожмите предложение приёмом упрощения. Запишите в поле.\n\nОн скажет правду, даже если она неприятна, потому что ему важно, чтобы ты стал лучше.","key":"Он скажет даже неприятную правду, желая тебе добра."},{"t":"Напишите в поле сжатое изложение всего текста (не менее 70 слов).\n\nЧто значит быть настоящим другом? Многие думают, что друг – это тот, кто всегда рядом в весёлую минуту, с кем интересно проводить время. Но легко быть рядом, когда всё хорошо. Настоящая дружба проверяется в трудностях.\n\nДруг не отвернётся, если ты ошибся, и не станет радоваться твоей неудаче. Он скажет правду, даже если она неприятна, потому что ему важно, чтобы ты стал лучше. Иногда такая честность обижает, но именно она отличает друга от приятеля.\n\nДружба – это ещё и умение отдавать. Невозможно только получать поддержку и внимание и ничего не давать взамен. Тот, кто хочет иметь друга, должен сам научиться быть другом: слушать, помогать, прощать. Только тогда дружба станет долгой и крепкой.","key":"Образец: Многие считают другом того, с кем весело. Однако быть рядом в радости легко, а настоящая дружба проверяется в трудностях.\n\nДруг не отвернётся в беде. Он скажет даже неприятную правду, желая тебе добра. Именно честность отличает друга от приятеля.\n\nКроме того, дружба – это умение отдавать. Нельзя лишь получать поддержку. Чтобы иметь друга, нужно самому стать внимательным и заботливым другом. Тогда дружба будет долгой и крепкой."}],"test":[{"q":"Приём: «Он любил книги, фильмы, музыку» → «Он любил искусство».","o":["обобщение","исключение","упрощение"],"a":0,"e":"Перечень заменён общим словом.","tag":"Изложение: приёмы сжатия"},{"q":"Приём: «Когда наступил вечер» → «Вечером».","o":["упрощение","обобщение","исключение"],"a":0,"e":"Придаточное заменено словом.","tag":"Изложение: приёмы сжатия"},{"q":"Что нельзя исключать при сжатии?","o":["главную мысль абзаца","повторы","второстепенные примеры"],"a":0,"e":"Главное сохраняем.","tag":"Изложение: приёмы сжатия"},{"q":"Какие слова помогают связать предложения изложения?","o":["однако, поэтому, кроме того","ой, ах, ух","ничего не нужно"],"a":0,"e":"Средства связи.","tag":"Изложение: приёмы сжатия"},{"q":"Сколько приёмов сжатия изучаем?","a":"3|три","e":"Исключение, обобщение, упрощение.","tag":"Изложение: приёмы сжатия"}],"hwtest":[{"q":"Приём: убрать примеры и подробности –","o":["исключение","обобщение"],"a":0,"e":"Исключение.","tag":"Изложение: приёмы сжатия"},{"q":"Приём: перечень → одно слово –","o":["обобщение","упрощение"],"a":0,"e":"Обобщение.","tag":"Изложение: приёмы сжатия"},{"q":"Можно ли добавлять своё мнение в изложение?","o":["нет","да"],"a":0,"e":"Передаём текст автора.","tag":"Изложение: приёмы сжатия"}],"hw":"Написать сжатое изложение по аудиозаписи из открытого банка ФИПИ, отметить в тексте, где использован каждый приём сжатия. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Приёмы сжатия без потери микротем.","tips":["Сжимаем подробности, а не мысль.","Своих рассуждений не добавляем.","Связываем предложения."]},"memo":{"h":"Сжатие = главное без подробностей","t":"Читай абзац и спрашивай: что здесь самое важное? Всё остальное – кандидаты на исключение или обобщение.","ex":["«ни кинотеатра, ни друзей, ни шумных улиц» → «никаких развлечений»"]},"date":"2027-06-08"},{"id":"oge-ru-42","title":"Сочинение-рассуждение: строение и примеры из текста","block":"s8","oge":"Задание 9 · Сочинение","learn":["строить сочинение: тезис, примеры, пояснения, вывод","приводить примеры из текста и пояснять их","показывать смысловую связь между примерами"],"theory":[{"h":"Строение сочинения","t":"Сочинение по заданию 9 – рассуждение объёмом не менее 70 слов. Оно состоит из трёх частей.","list":["Тезис – ответ на вопрос задания или толкование понятия (1–2 предложения).","Аргументация – два примера из текста; к каждому примеру – пояснение: что он показывает и как связан с тезисом.","Вывод – возвращение к тезису (1–2 предложения).","Между примерами показываем смысловую связь: противопоставление, причина и следствие, дополнение."],"scheme":"Тезис → Пример 1 + пояснение → связь → Пример 2 + пояснение → Вывод","mini":[{"q":"Сколько примеров-аргументов нужно в сочинении?","a":"2|два"}]},{"h":"Как оформить пример","list":["Ссылаемся на номер предложения: «В предложении 6 автор пишет…».","Можно цитировать или пересказывать близко к тексту.","Пояснение отвечает на вопрос «что это доказывает?»."],"ex":["Пример: «В предложениях 4–6 бабушка будит внука до рассвета, и он впервые слышит, как просыпается мир». Пояснение: «Этот эпизод показывает, что красота открывается тому, кто готов остановиться и прислушаться»."],"mini":[{"q":"На что ссылаемся, приводя пример из текста?","a":"на номер предложения|номера предложений"}]}],"practice":[{"t":"Прочитайте текст и сформулируйте в поле тезис – ответ на вопрос: «Почему герой перестал скучать в деревне?»\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"Например: Герой перестал скучать, потому что научился замечать красоту природы, которую раньше не видел."},{"t":"Приведите в поле пример-аргумент 1 из текста и поясните его.","key":"В предложении 2 герой признаётся, что первую неделю в деревне скучал по шумным улицам. Это показывает, что сначала он не видел ничего интересного вокруг."},{"t":"Приведите в поле пример-аргумент 2 и покажите связь с первым примером.","key":"Однако после утра у реки (предложения 4–6) он впервые услышал, как просыпается мир. Этот эпизод противопоставлен первому: герой открыл красоту, которой раньше не замечал."},{"t":"Напишите в поле вывод сочинения (1–2 предложения).","key":"Таким образом, скука уходит, когда человек учится замечать красоту рядом с собой."}],"test":[{"q":"Минимальный объём сочинения:","o":["70 слов","150 слов","200 слов"],"a":0,"e":"Не менее 70 слов.","tag":"Сочинение-рассуждение: строение и примеры из текста"},{"q":"Что следует за каждым примером?","o":["пояснение","новый тезис","вывод"],"a":0,"e":"Пояснение – обязательная часть.","tag":"Сочинение-рассуждение: строение и примеры из текста"},{"q":"Где формулируем тезис?","o":["в начале сочинения","в конце","в середине"],"a":0,"e":"Тезис – вступление.","tag":"Сочинение-рассуждение: строение и примеры из текста"},{"q":"Какая связь между примерами возможна?","o":["противопоставление","только повтор","никакой"],"a":0,"e":"Противопоставление, причина и следствие, дополнение.","tag":"Сочинение-рассуждение: строение и примеры из текста"},{"q":"Как сослаться на текст?","o":["указать номер предложения","указать номер страницы","не ссылаться"],"a":0,"e":"Номер предложения.","tag":"Сочинение-рассуждение: строение и примеры из текста"}],"hwtest":[{"q":"Сколько частей в сочинении-рассуждении?","a":"3|три","e":"Тезис, аргументы, вывод.","tag":"Сочинение-рассуждение: строение и примеры из текста"},{"q":"Что такое пояснение к примеру?","o":["объяснение, что пример доказывает","пересказ всего текста"],"a":0,"e":"Связь с тезисом.","tag":"Сочинение-рассуждение: строение и примеры из текста"},{"q":"Можно ли обойтись одним примером?","o":["нет","да"],"a":0,"e":"Нужно два.","tag":"Сочинение-рассуждение: строение и примеры из текста"}],"hw":"Написать сочинение по тексту «Каждое лето бабушка уезжала в деревню…» на вопрос: «Почему герой перестал скучать в деревне?» (не менее 70 слов). Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Сочинение: тезис, два примера с пояснениями, связь, вывод.","tips":["Пример + пояснение.","Связка между примерами.","Вывод возвращает к тезису."]},"memo":{"h":"Пример без пояснения – полбалла","t":"Каждый пример заканчиваем фразой-пояснением: «Это показывает, что…», «Этот эпизод доказывает…».","ex":["Связки: «Кроме того…», «В отличие от этого…», «Именно поэтому…»"]},"date":"2027-06-15"},{"id":"oge-ru-43","title":"Сочинение 9.2: смысл фрагмента текста","block":"s8","oge":"Задание 9 · Сочинение 9.2","learn":["объяснять смысл фрагмента текста","подбирать к нему два примера из текста"],"theory":[{"h":"Что нужно сделать","t":"В задании 9.2 нужно объяснить, как вы понимаете смысл фрагмента (обычно финала текста), и привести два примера из текста, которые это подтверждают.","list":["Тезис – толкование фрагмента своими словами, а не пересказ.","Примеры берём из всего текста: эпизоды, поступки, слова героев.","Примеры должны подтверждать именно ваше толкование."],"mini":[{"q":"Можно ли вместо толкования просто переписать фрагмент?","a":"нет"}]},{"h":"Как истолковать фрагмент","list":["Найди ключевые слова фрагмента.","Спроси: к какому событию текста он относится? что понял герой?","Сформулируй мысль одним предложением своими словами."],"ex":["Фрагмент: «красоту надо уметь замечать, а для этого иногда достаточно просто остановиться». Толкование: человек проходит мимо прекрасного в спешке; стоит замедлиться – и мир откроется по-новому."],"mini":[{"q":"С чего начинаем толкование фрагмента?","a":"с ключевых слов|найти ключевые слова"}]}],"practice":[{"t":"Объясните в поле смысл фрагмента: «С тех пор я никогда не скучал в деревне» (предложение 8).\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"Герой изменился: он научился находить радость не в развлечениях, а в природе и тишине, поэтому деревня стала для него интересной."},{"t":"Выберите два эпизода текста, которые подтверждают толкование, и запишите их в поле с номерами предложений.","key":"Пример 1: предложения 2–3 – герой скучает, потому что в деревне нет привычных развлечений. Пример 2: предложения 5–7 – утро у реки, когда герой увидел и услышал, как просыпается природа."},{"t":"Найдите в поле недочёты в сочинении ученика.\n\n«Эти слова означают, что в деревне хорошо. В тексте много красивых описаний природы. Мне текст понравился».","key":"нет толкования фрагмента (что изменилось в герое); нет двух примеров с номерами предложений и пояснений; вывод не связан с тезисом; объём меньше 70 слов"},{"t":"Напишите в поле сочинение 9.2 (не менее 70 слов) по фрагменту из предложения 8.","key":"Образец: Я понимаю эти слова так: герой научился видеть красоту природы, и поэтому деревня перестала казаться ему скучной. Сначала, как видно из предложений 2–3, мальчик тосковал по городским улицам: ему казалось, что в деревне нечего делать. Однако в предложениях 5–7 рассказано, как бабушка показала ему рассвет над рекой, и он впервые услышал пробуждение мира. Этот эпизод противопоставлен первому и объясняет перемену в герое. Таким образом, скука исчезает, когда человек открывает для себя красоту обычных вещей."}],"test":[{"q":"Что нужно сделать в 9.2?","o":["объяснить смысл фрагмента и привести два примера из текста","пересказать текст","привести примеры только из жизни"],"a":0,"e":"Толкование + два примера.","tag":"Сочинение 9.2: смысл фрагмента текста"},{"q":"Откуда берём примеры для 9.2?","o":["из прочитанного текста","из учебника","из других книг"],"a":0,"e":"Из текста.","tag":"Сочинение 9.2: смысл фрагмента текста"},{"q":"Что такое толкование фрагмента?","o":["объяснение его смысла своими словами","переписывание цитаты","поиск ошибок"],"a":0,"e":"Своими словами.","tag":"Сочинение 9.2: смысл фрагмента текста"},{"q":"Сколько примеров-аргументов нужно?","a":"2|два","e":"Два примера из текста.","tag":"Сочинение 9.2: смысл фрагмента текста"},{"q":"Какая фраза подходит для начала?","o":["«Я понимаю эти слова так: …»","«В тексте много слов»","«Мне понравился текст»"],"a":0,"e":"Начинаем с толкования.","tag":"Сочинение 9.2: смысл фрагмента текста"}],"hwtest":[{"q":"Нужно ли толковать фрагмент своими словами?","o":["да","нет"],"a":0,"e":"Обязательно.","tag":"Сочинение 9.2: смысл фрагмента текста"},{"q":"Примеры в 9.2 – из…","o":["текста","жизненного опыта"],"a":0,"e":"Из текста.","tag":"Сочинение 9.2: смысл фрагмента текста"},{"q":"Минимальный объём:","a":"70","e":"Не менее 70 слов.","tag":"Сочинение 9.2: смысл фрагмента текста"}],"hw":"Написать сочинение 9.2 по любому тексту из открытого банка ФИПИ. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"9.2: толкование фрагмента + два примера из текста.","tips":["Толкование – своими словами.","Примеры – из разных частей текста.","Связь между примерами."]},"memo":{"h":"Толкую – значит объясняю своими словами","t":"Хорошее толкование начинается так: «Эти слова означают, что…», «Автор хочет сказать, что…».","ex":["«Я понимаю эти слова так: …»"]},"date":"2027-06-22"},{"id":"oge-ru-44","title":"Сочинение 9.3: толкование понятия","block":"s8","oge":"Задание 9 · Сочинение 9.3","learn":["давать определение нравственному понятию","приводить пример из текста и пример из жизненного опыта"],"theory":[{"h":"Что нужно сделать","t":"В задании 9.3 нужно дать определение понятию (дружба, доброта, сострадание, мужество), прокомментировать его и привести два примера-аргумента.","list":["Определение – одно-два предложения: «Доброта – это…».","Комментарий – почему это качество важно, как оно проявляется.","Пример 1 – из прочитанного текста; пример 2 – из жизненного опыта (своего или известного случая, книги, фильма).","Вывод – возврат к определению."],"mini":[{"q":"Откуда берём второй пример в 9.3?","a":"из жизненного опыта|из жизни"}]},{"h":"Как дать определение","list":["Называем более общее понятие: «Дружба – это отношения…», «Сострадание – это способность…».","Добавляем отличительный признак: «…основанные на доверии и готовности помочь».","Избегаем определения через то же слово: «Дружба – это когда дружат» – ошибка."],"ex":["Красота – это то, что вызывает у человека восхищение и радость, делает мир светлее."],"mini":[{"q":"Можно ли определять понятие через однокоренное слово?","a":"нет"}]}],"practice":[{"t":"Дайте в поле определение понятия «дружба».","key":"Дружба – это близкие отношения между людьми, основанные на доверии, честности и готовности поддержать друг друга."},{"t":"Подберите в поле пример из текста о дружбе (задание 1 этого курса) и поясните его.\n\nЧто значит быть настоящим другом? Многие думают, что друг – это тот, кто всегда рядом в весёлую минуту, с кем интересно проводить время. Но легко быть рядом, когда всё хорошо. Настоящая дружба проверяется в трудностях.\n\nДруг не отвернётся, если ты ошибся, и не станет радоваться твоей неудаче. Он скажет правду, даже если она неприятна, потому что ему важно, чтобы ты стал лучше. Иногда такая честность обижает, но именно она отличает друга от приятеля.\n\nДружба – это ещё и умение отдавать. Невозможно только получать поддержку и внимание и ничего не давать взамен. Тот, кто хочет иметь друга, должен сам научиться быть другом: слушать, помогать, прощать. Только тогда дружба станет долгой и крепкой.","key":"Во втором абзаце говорится, что друг скажет правду, даже если она неприятна. Это показывает, что настоящий друг заботится о том, чтобы ты стал лучше."},{"t":"Приведите в поле пример из жизненного опыта, подтверждающий определение.","key":"Например: когда я болел и пропустил две недели учёбы, одноклассник каждый вечер звонил и объяснял новые темы. Его поддержка помогла мне не отстать."},{"t":"Напишите в поле сочинение 9.3 «Что такое дружба?» (не менее 70 слов).","key":"Образец: Дружба – это отношения между людьми, основанные на доверии и готовности помочь. Друг остаётся рядом не только в радости, но и в беде. Во втором абзаце текста сказано, что друг говорит правду, даже неприятную, потому что желает тебе добра. Кроме того, я сам убедился в силе дружбы: когда я болел, одноклассник каждый вечер объяснял мне новые темы. Таким образом, настоящая дружба проявляется в честности и поддержке."}],"test":[{"q":"Из чего состоит определение понятия?","o":["общее слово + отличительный признак","только пример","однокоренное слово"],"a":0,"e":"Формула определения.","tag":"Сочинение 9.3: толкование понятия"},{"q":"Сколько примеров-аргументов нужно в 9.3?","a":"2|два","e":"Один из текста, другой из жизненного опыта.","tag":"Сочинение 9.3: толкование понятия"},{"q":"Какое определение неудачное?","o":["Доброта – это когда добрый.","Доброта – это готовность бескорыстно помогать людям."],"a":0,"e":"Определение через однокоренное слово.","tag":"Сочинение 9.3: толкование понятия"},{"q":"Где формулируем определение?","o":["в начале сочинения","в конце сочинения"],"a":0,"e":"Определение – тезис.","tag":"Сочинение 9.3: толкование понятия"},{"q":"Что может быть примером из жизненного опыта?","o":["случай из жизни, книга, фильм","только текст ОГЭ"],"a":0,"e":"Опыт читателя и человека.","tag":"Сочинение 9.3: толкование понятия"}],"hwtest":[{"q":"Первый пример в 9.3 берём из…","o":["прочитанного текста","интернета"],"a":0,"e":"Из текста.","tag":"Сочинение 9.3: толкование понятия"},{"q":"Определение «Мужество – это когда мужественный» –","o":["ошибочное","верное"],"a":0,"e":"Через однокоренное слово.","tag":"Сочинение 9.3: толкование понятия"},{"q":"Минимальный объём сочинения:","a":"70","e":"Не менее 70 слов.","tag":"Сочинение 9.3: толкование понятия"}],"hw":"Написать сочинение 9.3 «Что такое сострадание?» с примером из любого рассказа и из жизненного опыта. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"9.3: определение понятия, два примера (текст + жизнь), вывод.","tips":["Общее слово + признак.","Пример из текста + пример из жизни.","Вывод возвращает к определению."]},"memo":{"h":"Формула определения","t":"Понятие = общее слово + отличительный признак.","ex":["Дружба – это отношения (общее) между людьми, основанные на доверии и взаимной поддержке (признак)."]},"date":"2027-06-29"},{"id":"oge-ru-45","title":"Собеседование: чтение вслух и пересказ с цитатой","block":"s9","oge":"Собеседование · Задания 1–2","learn":["выразительно читать текст с соблюдением орфоэпических норм","пересказывать текст, включая в него высказывание"],"theory":[{"h":"Задание 1: чтение вслух","t":"Текст читаем вслух выразительно, в темпе естественной речи, без искажения слов.","list":["На подготовку даётся около 2 минут: прочитай текст про себя, отметь сложные слова и ударения.","Интонация соответствует знакам препинания: паузы на запятых, понижение голоса на точке.","Ударения: звонИт, красИвее, договОр, квартАл, тОрты, жалюзИ."],"mini":[{"q":"Как правильно: «звонит» – ударение на…","a":"и|звонИт|второй слог"}]},{"h":"Задание 2: пересказ с цитатой","t":"Пересказываем текст подробно, сохраняя все микротемы, и уместно включаем предложенное высказывание (цитату).","list":["Цитату вводим словами: «Как сказал…», «По словам…», «…, – писал…».","Цитату не обрываем и не искажаем.","Пересказываем от третьего лица, своими словами, но близко к тексту."],"ex":["По словам академика Д. С. Лихачёва, «…» – вставляем точно, без изменений."],"mini":[{"q":"Можно ли изменять слова цитаты?","a":"нет"}]}],"practice":[{"t":"Расставьте ударения в словах (инструмент «Подпись»: подпишите ударную гласную).","key":"звонИт, квартАл, тОрты, красИвее, договОр, жалюзИ, щавЕль, катАлог","items":["звонит","квартал","торты","красивее","договор","жалюзи","щавель","каталог"]},{"t":"Прочитайте вслух текст о бабушке и деревне, затем перескажите его, включив высказывание: «Природа – это книга, которую нужно уметь читать». Запишите в поле план пересказа.\n\n(1)Каждое лето бабушка уезжала в деревню и звала меня с собой. (2)В городе я считал дни до каникул, а в деревне первую неделю скучал по шумным улицам. (3)Здесь не было ни кинотеатра, ни друзей – только старый дом, огород и речка за околицей. (4)Однажды бабушка разбудила меня до рассвета и повела к реке. (5)Туман лежал на воде, как пуховое одеяло, а над ним медленно поднималось солнце. (6)Мы долго стояли молча, и я вдруг услышал, как просыпается мир: плеснула рыба, запела птица, зашелестела трава. (7)«Вот ради этого я и приезжаю сюда», – тихо сказала бабушка. (8)С тех пор я никогда не скучал в деревне. (9)Я понял, что красоту надо уметь замечать, а для этого иногда достаточно просто остановиться.","key":"План: 1) поездки в деревню и скука героя; 2) утро у реки; 3) вывод героя. Цитату уместно включить перед выводом: «Как говорят, природа – это книга, которую нужно уметь читать…»"},{"t":"Запишите в поле три способа ввести цитату в пересказ.","key":"«Как говорил…, „…“»; «По словам…, „…“»; «„…“, – писал…»"},{"t":"Подготовьте в поле пересказ (8–10 предложений) с цитатой.","key":"Свободный ответ: пересказ всех трёх частей текста и уместно введённая цитата."}],"test":[{"q":"Ударение: «торты»","o":["тОрты","тортЫ"],"a":0,"e":"тОрты.","tag":"Собеседование: чтение вслух и пересказ с цитатой"},{"q":"Ударение: «квартал»","o":["квартАл","квАртал"],"a":0,"e":"квартАл.","tag":"Собеседование: чтение вслух и пересказ с цитатой"},{"q":"Что делаем с цитатой при пересказе?","o":["включаем точно, не изменяя","пересказываем своими словами","пропускаем"],"a":0,"e":"Цитата приводится точно.","tag":"Собеседование: чтение вслух и пересказ с цитатой"},{"q":"Как читаем текст в задании 1?","o":["выразительно, в темпе естественной речи","как можно быстрее","по слогам"],"a":0,"e":"Естественный темп.","tag":"Собеседование: чтение вслух и пересказ с цитатой"},{"q":"Ударение: «звонит»","a":"звонИт|и","e":"звонИт.","tag":"Собеседование: чтение вслух и пересказ с цитатой"}],"hwtest":[{"q":"Ударение: «красивее»","o":["красИвее","красивЕе"],"a":0,"e":"красИвее.","tag":"Собеседование: чтение вслух и пересказ с цитатой"},{"q":"Можно ли пропустить цитату в пересказе?","o":["нет","да"],"a":0,"e":"Её нужно уместно включить.","tag":"Собеседование: чтение вслух и пересказ с цитатой"},{"q":"Ударение: «договор»","o":["договОр","дОговор"],"a":0,"e":"договОр.","tag":"Собеседование: чтение вслух и пересказ с цитатой"}],"hw":"Выучить 20 слов орфоэпического минимума. Прочитать вслух и пересказать текст из демоверсии итогового собеседования, включив цитату. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Собеседование: выразительное чтение и пересказ с цитатой.","tips":["Ударения – заранее.","Цитата – точно.","Пересказ – все микротемы."]},"memo":{"h":"Подготовка – с карандашом","t":"Отметь ударения в трудных словах и паузы. Напиши на полях 3–4 опорных слова для пересказа и место, куда вставишь цитату.","ex":["звонИт, тОрты, квартАл, договОр, красИвее, обеспЕчение"]},"date":"2027-07-06"},{"id":"oge-ru-46","title":"Собеседование: монолог и диалог","block":"s9","oge":"Собеседование · Задания 3–4","learn":["строить монолог (описание, повествование, рассуждение) на 10–12 предложений","отвечать на вопросы собеседника полно и вежливо"],"theory":[{"h":"Задание 3: монолог","t":"Нужно выбрать одну тему (описание фотографии, повествование на основе жизненного опыта или рассуждение) и говорить около трёх минут, опираясь на вопросы-подсказки.","list":["Описание: что изображено, где, кто, какое настроение; от общего к деталям.","Повествование: когда, где, что произошло, чем закончилось, чему научило.","Рассуждение: тезис – доказательства – вывод.","Объём – не менее 10 предложений; отвечаем на все вопросы плана."],"mini":[{"q":"Сколько предложений минимум в монологе?","a":"10|десять"}]},{"h":"Задание 4: диалог","t":"Экзаменатор задаёт вопросы по теме монолога. Отвечаем полно, развёрнуто, не односложно.","list":["Ответ – 2–3 предложения с объяснением.","Если вопрос непонятен, вежливо просим повторить.","Соблюдаем речевой этикет: «Мне кажется…», «Я считаю…»."],"mini":[{"q":"Можно ли отвечать в диалоге одним словом «да»?","a":"нет"}]}],"practice":[{"t":"Составьте в поле монолог-повествование (10–12 предложений) на тему «Незабываемый день лета» по плану: когда это было; что произошло; что вы почувствовали; чему этот день вас научил.","key":"Свободный ответ: 10–12 предложений, отвечающих на все вопросы плана, с вводными словами и средствами связи."},{"t":"Составьте в поле монолог-рассуждение «Нужно ли человеку уметь замечать красоту природы?» по схеме: тезис – два доказательства – вывод.","key":"Например: Я считаю, что умение замечать красоту делает жизнь богаче. Во-первых… Во-вторых… Таким образом…"},{"t":"Ответьте в поле развёрнуто (2–3 предложения) на вопросы диалога: 1) Какое время года вы любите больше всего и почему? 2) Где вам нравится отдыхать?","key":"Развёрнутые ответы с объяснением причины."},{"t":"Подберите в поле 5 речевых формул для диалога (согласие, несогласие, уточнение).","key":"Например: «Я согласен с вами, потому что…», «Мне кажется иначе…», «Не могли бы вы повторить вопрос?», «С одной стороны…, с другой стороны…», «По моему мнению…»"}],"test":[{"q":"Сколько тем выбирают для монолога?","o":["одну","все три","две"],"a":0,"e":"Одну из трёх.","tag":"Собеседование: монолог и диалог"},{"q":"Как строится рассуждение?","o":["тезис – доказательства – вывод","только перечень фактов","вопросы без ответов"],"a":0,"e":"Схема рассуждения.","tag":"Собеседование: монолог и диалог"},{"q":"Как отвечать в диалоге?","o":["полно, 2–3 предложения","одним словом","молчать и ждать"],"a":0,"e":"Развёрнуто.","tag":"Собеседование: монолог и диалог"},{"q":"Что делать, если вопрос непонятен?","o":["вежливо попросить повторить","ответить наугад"],"a":0,"e":"Этикет общения.","tag":"Собеседование: монолог и диалог"},{"q":"Минимум предложений в монологе:","a":"10","e":"Не менее 10.","tag":"Собеседование: монолог и диалог"}],"hwtest":[{"q":"Описание фотографии строим…","o":["от общего к деталям","с вывода"],"a":0,"e":"От общего к частному.","tag":"Собеседование: монолог и диалог"},{"q":"Повествование отвечает на вопрос…","o":["что произошло?","каков предмет?"],"a":0,"e":"События.","tag":"Собеседование: монолог и диалог"},{"q":"Можно ли отвечать в диалоге «не знаю»?","o":["лучше развёрнуто объяснить своё мнение","да, это достаточно"],"a":0,"e":"Нужен развёрнутый ответ.","tag":"Собеседование: монолог и диалог"}],"hw":"Подготовить и записать на диктофон три монолога (описание, повествование, рассуждение) по темам из демоверсии итогового собеседования. Пройти ДЗ-тест.","writing":null,"stub":false,"method":{"focus":"Монолог по плану и развёрнутый диалог.","tips":["Вопросы плана – опора.","Не меньше 10 предложений.","В диалоге – 2–3 предложения на ответ."]},"memo":{"h":"Вопросы плана = план ответа","t":"Каждый вопрос-подсказка – это 2–3 предложения монолога. Ответил на все – монолог готов.","ex":["Где это было? Что произошло? Что вы почувствовали? Чему научились?"]},"date":"2027-07-13"}],"events":[],"texts":{},"izl":{},"criteria":{"errors":[]},"methodology":[{"h":"Как устроен курс","t":"Одно занятие – одна тема. Сначала короткая теория с примерами и мини-практикой после каждого правила, потом задания в формате ОГЭ на интерактивном листе (подчёркивание, знаки, пропущенные буквы), тест и ДЗ-тест."},{"h":"Структура экзамена","t":"Задание 1 – сжатое изложение; 2 – синтаксический анализ; 3 – пунктуационный анализ; 4 – анализ словосочетания; 5 – орфографический анализ; 6 – анализ содержания текста; 7 – средства выразительности; 8 – лексический анализ; 9 – сочинение (9.1, 9.2 или 9.3)."}]}});
